      expect(exclusionReason(ex, { commit: 'c', source: 's.ts', base: 'c', run_id: 'r1' }))
        .toBe('TG-001 task key');
      ex.tg.delete('c');
      expect(exclusionReason(ex, { commit: 'c', source: 's.ts', base: 'c', run_id: 'r1' }))
        .toBe('attempted in a genome trial');
      ex.trialAttempted.delete('c');
      expect(exclusionReason(ex, { commit: 'c', source: 's.ts', base: 'c', run_id: 'r1' }))
        .toBe('dream-exposed commit');
    });
  });
