    const rs = [rec({ tokens: 100 }), rec({ mirror: true, tokens: 999 })];
    const s = windowSums(rs, NOW);
    expect(s['5h'].calls).toBe(1);
    expect(s['5h'].tokens).toBe(100);
  });
  it('sets tokens to null when every call in the window lacks tokens', () => {
    const rs = [rec({ at: NOW - 60_000, tokens: null }), rec({ at: NOW - 30_000, tokens: null })];
    const s = windowSums(rs, NOW);
    expect(s['5h'].calls).toBe(2);
    expect(s['5h'].tokens).toBeNull();
    expect(s['5h'].calls_without_tokens).toBe(2);
  });
  it('sums only known tokens and reports calls_without_tokens for the rest', () => {
    const rs = [
      rec({ at: NOW - 60_000, tokens: 100 }),
      rec({ at: NOW - 30_000, tokens: null }),
      rec({ at: NOW - 10_000, tokens: 50 }),
    ];
    const s = windowSums(rs, NOW);
    expect(s['5h'].calls).toBe(3);
    expect(s['5h'].tokens).toBe(150);
    expect(s['5h'].calls_without_tokens).toBe(1);
  });
  it('includes records exactly at the window start boundary (>=) and at now (<=)', () => {
    const fiveHStart = NOW - 5 * 3_600_000;
    const rs = [rec({ at: fiveHStart, tokens: 10 }), rec({ at: NOW, tokens: 20 })];
    const s = windowSums(rs, NOW);
    expect(s['5h'].calls).toBe(2);
    expect(s['5h'].tokens).toBe(30);
  });
  it('excludes records before the window start or after now', () => {
    const fiveHStart = NOW - 5 * 3_600_000;
    const rs = [
      rec({ at: fiveHStart - 1, tokens: 999 }), // just before
      rec({ at: NOW + 1, tokens: 888 }),        // just after
      rec({ at: fiveHStart, tokens: 10 }),       // included
    ];
    const s = windowSums(rs, NOW);
    expect(s['5h'].calls).toBe(1);
    expect(s['5h'].tokens).toBe(10);
  });
  it('applies each window independently (a record in 7d but not in today)', () => {
    const threeDaysAgo = NOW - 3 * 86_400_000;
    const rs = [rec({ at: threeDaysAgo, tokens: 42 })];
    const s = windowSums(rs, NOW);
    expect(s['7d'].calls).toBe(1);
    expect(s['7d'].tokens).toBe(42);
    expect(s['today'].calls).toBe(0);
    expect(s['5h'].calls).toBe(0);
  });
});
describe('parsePlanLimits', () => {
  const validEntry = { account: 'claude_max' as const, plan: 'Max 20x', window: 'weekly' as const, unit: 'messages' as const, limit: 15000, limit_text: '15k messages/week', source_url: null, checked_at: null, confidence: null, note: null, exceed_behaviour: null };
  it('parses a valid entry and returns it with all fields intact', () => {
