    const neg = parsePlanLimits({ provider_plan_limits: [{ ...validEntry, limit: -5 }] });
    expect(neg.invalid).toBe(1);
    const nul = parsePlanLimits({ provider_plan_limits: [{ ...validEntry, limit: null }] });
    expect(nul.invalid).toBe(0); expect(nul.limits[0].limit).toBeNull();
