describe('limitView', () => {
  const mkSums = (over: Partial<Record<WindowId, WindowSum>> = {}): Record<WindowId, WindowSum> => ({
    '5h': { calls: 10, tokens: 5000, calls_without_tokens: 0 },
    today: { calls: 20, tokens: 9000, calls_without_tokens: 1 },
    '7d': { calls: 80, tokens: 40000, calls_without_tokens: 3 },
    month: { calls: 200, tokens: 100000, calls_without_tokens: 5 },
    ...over,
  });
  const baseLimit: PlanLimit = { account: 'claude_max', plan: 'Max 20x', window: 'weekly', unit: 'messages', limit: 15000, limit_text: '', source_url: null, checked_at: null, confidence: null, note: null, exceed_behaviour: null };
  it('maps vendor windows to our measured windows correctly', () => {
    expect(limitView({ ...baseLimit, window: '5h' }, mkSums()).measured_window).toBe('5h');
    expect(limitView({ ...baseLimit, window: 'session' }, mkSums()).measured_window).toBe('5h');
    expect(limitView({ ...baseLimit, window: 'weekly' }, mkSums()).measured_window).toBe('7d');
    expect(limitView({ ...baseLimit, window: 'daily' }, mkSums()).measured_window).toBe('today');
    expect(limitView({ ...baseLimit, window: 'monthly' }, mkSums()).measured_window).toBe('month');
    expect(limitView({ ...baseLimit, window: 'none' }, mkSums()).measured_window).toBe('month');
  });
  it('uses calls for requests unit and tokens otherwise', () => {
    const sums = mkSums();
    const req = limitView({ ...baseLimit, unit: 'requests', limit: 100, window: 'weekly' }, sums);
    expect(req.measured_unit).toBe('calls');
    expect(req.used).toBe(80); // 7d calls
    const tok = limitView({ ...baseLimit, unit: 'tokens', limit: 50000, window: 'weekly' }, sums);
    expect(tok.measured_unit).toBe('tokens');
    expect(tok.used).toBe(40000); // 7d tokens
  });
  it('sets comparable=true only when limit is a number, unit is tokens/requests, and used is not null', () => {
    const sums = mkSums();
    expect(limitView({ ...baseLimit, unit: 'tokens', limit: 50000 }, sums).comparable).toBe(true);
    expect(limitView({ ...baseLimit, unit: 'requests', limit: 200 }, sums).comparable).toBe(true);
    expect(limitView({ ...baseLimit, unit: 'messages', limit: 15000 }, sums).comparable).toBe(false);
    expect(limitView({ ...baseLimit, unit: 'credits', limit: 100 }, sums).comparable).toBe(false);
    expect(limitView({ ...baseLimit, unit: 'unknown', limit: 100 }, sums).comparable).toBe(false);
    expect(limitView({ ...baseLimit, unit: 'tokens', limit: null }, sums).comparable).toBe(false);
    // used null (all calls lack tokens)
    const noTok = mkSums({ '7d': { calls: 5, tokens: null, calls_without_tokens: 5 } });
    expect(limitView({ ...baseLimit, unit: 'tokens', limit: 100 }, noTok).comparable).toBe(false);
  });
  it('computes used_pct rounded to one decimal when comparable', () => {
    const sums = mkSums(); // 7d tokens = 40000
    const v = limitView({ ...baseLimit, unit: 'tokens', limit: 80000, window: 'weekly' }, sums);
    expect(v.used_pct).toBe(50.0);
    const v2 = limitView({ ...baseLimit, unit: 'tokens', limit: 30000, window: 'weekly' }, sums);
    expect(v2.used_pct).toBe(133.3);
  });
  it('sets active based on account_plan match', () => {
    const sums = mkSums();
    expect(limitView(baseLimit, sums, {}).active).toBeNull();
    expect(limitView(baseLimit, sums, { claude_max: 'Max 20x' }).active).toBe(true);
    expect(limitView(baseLimit, sums, { claude_max: 'Pro 5x' }).active).toBe(false);
  });
  it('includes a caveat in unit_note for requests and session windows', () => {
    const v = limitView({ ...baseLimit, unit: 'requests', window: 'session', limit: 100 }, mkSums());
    expect(v.unit_note).toContain('session length not published');
    expect(v.unit_note).toMatch(/we count calls/);
  });
});
describe('ACCOUNTS constant', () => {
  it('contains exactly the eight documented accounts with correct cost_basis values', () => {
    expect(ACCOUNTS.map((a) => a.id)).toEqual(['ollama_cloud', 'claude_max', 'chatgpt_pro', 'opencode_free', 'typesafe_jev', 'nvidia', 'local_workstation', 'other']);
    expect(Object.fromEntries(ACCOUNTS.map((a) => [a.id, a.cost_basis]))).toEqual({
