  outageFallbackRuntime,
  TG_LOOP_NAME,
} from '../services/ollama-outage-fallback';

// Hardcoded literal so each SQL assertion is independent of the imported constant.
const REF_LITERAL = 'runtime_fallback:ollama_outage';

type DbLike = Parameters<typeof applyOutageFallback>[0];
interface FakeCall { sql: string; args: unknown[] }
function makeFakeDb() {
  const calls: FakeCall[] = [];
  return {
    calls,
    prepare(sql: string) {
      return {
        sql,
        run(...args: unknown[]) {
          calls.push({ sql, args });
        },
      };
    },
  };
}

describe('ollama-outage-fallback constants', () => {
