    expect(FALLBACK_REASON).toBe('ollama_outage');
    expect(FALLBACK_REF).toBe(REF_LITERAL);
    // The evidence ref must be derived from the reason with a colon separator.
    expect(FALLBACK_REF).toBe(`runtime_fallback:${FALLBACK_REASON}`);
    expect(F2_SUSPENDED_ARM).toBe('fallback_suspended');
    expect(TG_LOOP_NAME).toBe('tg-001');
