describe('applyOutageFallback — lease rewrite contract', () => {
  it('rewrites an opencode production lease to claude and records full fallback metadata', () => {
    const db = makeFakeDb();
    const run = { id: 'run-1', loop_name: 'maker' };
    const lease = {
      id: 'lease-1',
      role: 'maker',
      runtime: 'opencode',
      metadata: { model: 'm1', checker_family_arm: 'arm-x' } as Record<string, unknown>,
    };
    const env = { OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' } as NodeJS.ProcessEnv;

    const result = applyOutageFallback(db as unknown as DbLike, run, lease, 'opencode', env);

    expect(result).toBe('claude');
    expect(lease.runtime).toBe('claude');
    // Exactly one UPDATE against worker_leases, keyed by the lease id.
    expect(db.calls.length).toBe(1);
    expect(db.calls[0].sql).toBe('UPDATE worker_leases SET runtime = ?, metadata = ?, updated_at = ? WHERE id = ?');
    expect(db.calls[0].args[0]).toBe('claude');
    expect(typeof db.calls[0].args[1]).toBe('string');
    expect(db.calls[0].args[3]).toBe('lease-1');

    const meta = JSON.parse(db.calls[0].args[1] as string) as Record<string, any>;
    // The opencode provider/model is dropped; the checker arm is suspended.
    expect(meta.model).toBeUndefined();
    expect(meta.checker_family_arm).toBe(F2_SUSPENDED_ARM);
    // Subscription marker set so the executor strips keys and uses OAuth + acceptEdits.
    expect(meta.subscription_auth).toBe('claude');
    const fb = meta.runtime_fallback as Record<string, any>;
    expect(fb.from).toBe('opencode');
    expect(fb.to).toBe('claude');
    expect(fb.reason).toBe(FALLBACK_REASON);
    expect(fb.from_model).toBe('m1');
    expect(fb.from_checker_family_arm).toBe('arm-x');
    expect(typeof fb.at).toBe('string');
    expect(Number.isNaN(Date.parse(fb.at))).toBe(false);
    // Manual flag on → no 'auto' trigger recorded.
    expect(fb.trigger).toBeUndefined();
  });

  it('records a minimal fallback when the lease has no model or checker arm', () => {
    const db = makeFakeDb();
    const run = { id: 'run-2', loop_name: 'checker' };
    const lease = { id: 'lease-2', role: 'checker', runtime: 'opencode', metadata: {} as Record<string, unknown> };
    const env = { OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' } as NodeJS.ProcessEnv;

    const result = applyOutageFallback(db as unknown as DbLike, run, lease, 'opencode', env);

    expect(result).toBe('claude');
    expect(lease.runtime).toBe('claude');
    expect(db.calls.length).toBe(1);
    const meta = JSON.parse(db.calls[0].args[1] as string) as Record<string, any>;
    expect(meta.model).toBeUndefined();
    expect(meta.checker_family_arm).toBeUndefined();
    expect(meta.subscription_auth).toBe('claude');
    expect(meta.runtime_fallback.from_model).toBeUndefined();
    expect(meta.runtime_fallback.from_checker_family_arm).toBeUndefined();
    expect(meta.runtime_fallback.reason).toBe(FALLBACK_REASON);
  });

  it('keeps an already-fallen-back lease and does not rewrite the row (continuation)', () => {
    const db = makeFakeDb();
    const run = { id: 'run-3', loop_name: 'maker' };
    const baseMeta = { runtime_fallback: { from: 'opencode', to: 'claude' } } as Record<string, unknown>;
    // Continuing a fallback that started from opencode preserves the claude target.
    expect(
      applyOutageFallback(db as unknown as DbLike, run, { id: 'l', role: 'm', runtime: 'opencode', metadata: { ...baseMeta } }, 'opencode', {}),
    ).toBe('claude');
    // An unrelated runtime passes through unchanged.
    expect(
      applyOutageFallback(db as unknown as DbLike, run, { id: 'l2', role: 'm', runtime: 'something-else', metadata: { ...baseMeta } }, 'something-else', {}),
    ).toBe('something-else');
    // No DB write on either continuation path.
    expect(db.calls.length).toBe(0);
  });

  it('leaves non-opencode / gym / tg-001 / already-subscribed leases untouched (no write)', () => {
    const env = { OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' } as NodeJS.ProcessEnv;

    let db = makeFakeDb();
    expect(
      applyOutageFallback(db as unknown as DbLike, { id: 'r', loop_name: 'maker' }, { id: 'l', role: 'm', runtime: 'claude', metadata: {} as Record<string, unknown> }, 'claude', env),
    ).toBe('claude');
    expect(db.calls.length).toBe(0);

    db = makeFakeDb();
    expect(
      applyOutageFallback(db as unknown as DbLike, { id: 'r', loop_name: 'evolution-gym' }, { id: 'l', role: 'm', runtime: 'opencode', metadata: {} as Record<string, unknown> }, 'opencode', env),
    ).toBe('opencode');
    expect(db.calls.length).toBe(0);

    db = makeFakeDb();
    expect(
      applyOutageFallback(db as unknown as DbLike, { id: 'r', loop_name: TG_LOOP_NAME }, { id: 'l', role: 'm', runtime: 'opencode', metadata: {} as Record<string, unknown> }, 'opencode', env),
    ).toBe('opencode');
    expect(db.calls.length).toBe(0);

    db = makeFakeDb();
    expect(
      applyOutageFallback(db as unknown as DbLike, { id: 'r', loop_name: 'maker' }, { id: 'l', role: 'm', runtime: 'opencode', metadata: { subscription_auth: 'claude' } as Record<string, unknown> }, 'opencode', env),
    ).toBe('opencode');
    expect(db.calls.length).toBe(0);
  });
});

