import {
  ATTEMPT_STATES,
  MIN_SEMANTIC_N,
  PARSE_OR_SCHEMA,
  quarantineState,
  ledgerState,
} from '../services/panel-attempt-metrics';

// The classification core is pure and deterministic; these tests pin every branch
// (including the negative / boundary cases) so that a subtly broken implementation
// — swapped branches, an unanchored regex, substring instead of exact matching,
// case-insensitive or trimmed status handling — fails here.
