  it('exposes exactly the eight attempt states', () => {
    expect(new Set<string>(ATTEMPT_STATES)).toEqual(
      new Set([
        'VALID_FIRST_PASS',
        'VALID_AFTER_RETRY',
        'QUARANTINED',
        'GENERATION_FAILED',
        'PARSE_FAILED',
        'SCHEMA_INVALID',
        'INFRA_FAILED',
        'UNKNOWN_FAILURE',
      ]),
    );
  });

  it('defines the combined pre-E4 class as the literal union string', () => {
    expect(PARSE_OR_SCHEMA).toBe('PARSE_FAILED|SCHEMA_INVALID');
  });

  it('keeps the semantic-evidence floor at 10', () => {
    expect(MIN_SEMANTIC_N).toBe(10);
  });
});

describe('quarantineState', () => {
  // --- generation-failed branch: prefix must be present AND case-sensitive ---
  it('classifies an empty model response as GENERATION_FAILED', () => {
    expect(quarantineState('generation failed: empty model response')).toBe('GENERATION_FAILED');
  });
  it('still treats a trailing detail after "empty model response" as GENERATION_FAILED (prefix match)', () => {
    expect(quarantineState('generation failed: empty model response after 3 retries')).toBe('GENERATION_FAILED');
  });
  it('treats the plural / continued form of the empty-response text as GENERATION_FAILED', () => {
    expect(quarantineState('generation failed: empty model responses were observed')).toBe('GENERATION_FAILED');
  });
  it('classifies a non-empty generation failure as INFRA_FAILED', () => {
    expect(quarantineState('generation failed: connection reset by peer')).toBe('INFRA_FAILED');
  });
  it('classifies a provider-error generation failure as INFRA_FAILED', () => {
    expect(quarantineState('generation failed: provider returned 500')).toBe('INFRA_FAILED');
  });

  // The 'generation failed:' prefix is required and case-sensitive; without it the
  // text must fall through to reviewFailureKind → QUARANTINED.
  it('does NOT treat a capitalised "Generation failed:" prefix as a generation failure', () => {
    expect(quarantineState('Generation failed: empty model response')).toBe('QUARANTINED');
  });
  it('does NOT classify bare "empty model response" (no generation-failed prefix) as GENERATION_FAILED', () => {
    expect(quarantineState('empty model response')).toBe('QUARANTINED');
  });
  it('ignores "empty model response" appearing mid-sentence with no prefix', () => {
    expect(quarantineState('we saw an empty model response earlier')).toBe('QUARANTINED');
  });

  // --- parse branch: EXACT match against PARSE_ERRORS, not substring ---
  it('classifies each canonical parse error as PARSE_FAILED', () => {
    expect(quarantineState('no JSON object in the answer')).toBe('PARSE_FAILED');
    expect(quarantineState('answer is not valid JSON')).toBe('PARSE_FAILED');
