    expect(quarantineState('stance must be one of support|oppose|uncertain|needs_evidence (got null)')).toBe('SCHEMA_INVALID');
    expect(quarantineState('confidence must be a number between 0 and 1')).toBe('SCHEMA_INVALID');
    expect(quarantineState('findings must be a non-empty array of strings')).toBe('SCHEMA_INVALID');
    expect(quarantineState('evidence_refs must cite at least one concrete item from the context')).toBe('SCHEMA_INVALID');
  });
  it('does NOT classify an unrecognised leading word before "must" as SCHEMA_INVALID', () => {
    expect(quarantineState('posture must be a string')).toBe('QUARANTINED');
  });
  it('requires the schema regex to be anchored (a bare "it must ..." is QUARANTINED)', () => {
    expect(quarantineState('it must work')).toBe('QUARANTINED');
  });

  // --- fallthrough: cause unknown ---
  it('classifies unrecognised error text as QUARANTINED', () => {
    expect(quarantineState('something completely unexpected happened')).toBe('QUARANTINED');
  });
  it('classifies the empty string as QUARANTINED', () => {
    expect(quarantineState('')).toBe('QUARANTINED');
  });
