describe('ledgerState', () => {
  const allowed = new Set<string>([...ATTEMPT_STATES, PARSE_OR_SCHEMA]);
  const validStates = new Set<string>(['VALID_FIRST_PASS', 'VALID_AFTER_RETRY']);

  it('maps each ledger status to its exact state', () => {
    expect(ledgerState('ok')).toBe('VALID_FIRST_PASS');
    expect(ledgerState('repaired')).toBe('VALID_AFTER_RETRY');
    expect(ledgerState('invalid_parse')).toBe('PARSE_FAILED');
    expect(ledgerState('invalid_schema')).toBe('SCHEMA_INVALID');
    expect(ledgerState('empty')).toBe('GENERATION_FAILED');
    expect(ledgerState('error')).toBe('INFRA_FAILED');
  });

  it('maps legacy "invalid" to the combined class (both the constant and the literal)', () => {
    expect(ledgerState('invalid')).toBe(PARSE_OR_SCHEMA);
    expect(ledgerState('invalid')).toBe('PARSE_FAILED|SCHEMA_INVALID');
  });

  it('treats null / empty / unrecognised statuses as UNKNOWN_FAILURE', () => {
    expect(ledgerState(null)).toBe('UNKNOWN_FAILURE');
    expect(ledgerState('')).toBe('UNKNOWN_FAILURE');
    expect(ledgerState('something-new')).toBe('UNKNOWN_FAILURE');
  });

  // Status matching is an exact, case-sensitive switch — no trim, no lowercasing.
  it('does not normalise case or whitespace on the status', () => {
    expect(ledgerState('OK')).toBe('UNKNOWN_FAILURE');
    expect(ledgerState(' ok ')).toBe('UNKNOWN_FAILURE');
    expect(ledgerState('Empty')).toBe('UNKNOWN_FAILURE');
  });

  it('only ever returns a known state key', () => {
    for (const s of ['ok', 'repaired', 'invalid_parse', 'invalid_schema', 'invalid', 'empty', 'error', '', 'nope']) {
      const r = ledgerState(s);
      expect(allowed.has(r)).toBe(true);
    }
  });

  it('marks only first-pass and after-retry as valid states', () => {
    expect(validStates.has(ledgerState('ok'))).toBe(true);
    expect(validStates.has(ledgerState('repaired'))).toBe(true);
    for (const s of ['invalid_parse', 'invalid_schema', 'invalid', 'empty', 'error', null]) {
      expect(validStates.has(ledgerState(s))).toBe(false);
    }
  });
});

