    expect(out[0].score).toBeNull();
    expect(out[0].evidence[0]).toBe('INSUFFICIENT_EVIDENCE: earlier requeues verified 2/4 (30 d, need 5)');
    db.close();
  });

  it('computes a measured rate at exactly MIN_N settled requeues (n=5, k=2 → 0.4) with exact evidence', () => {
    const db = makeDb();
    insertSettledRequeues(db, 5, 2);
    const rq: InboxRequeue[] = [{ id: 'r1', title: 'T', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' }];
    const out = rankNeedsYou(db, rq, [], [], NOW, { labelled: null, wrong: null });
