    const db = makeDb();
    insertSettledRequeues(db, 5, 3); // rate = 0.6
    const rq: InboxRequeue[] = [
      { id: 'r-a', title: 'First', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' },
      { id: 'r-b', title: 'Second', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' },
    ];
    const mem = [
      { id: 'm-x', title: 'MemX', content: '', memory_type: 'rule', status: 'candidate', created_at: D30_AGO },
      { id: 'm-y', title: 'MemY', content: '', memory_type: 'fact', status: 'review_required', created_at: D30_AGO },
    ];
    const out = rankNeedsYou(db, rq, [], mem, NOW, { labelled: null, wrong: null });
    expect(out).toHaveLength(4);
    // Both requeues share score 0.6; stable sort preserves input order
    expect(out[0].id).toBe('r-a');
    expect(out[1].id).toBe('r-b');
    // Both memories have null score (−1 sentinel); stable sort preserves input order
    expect(out[2].id).toBe('m-x');
    expect(out[3].id).toBe('m-y');
    db.close();
  });

