    const rq: InboxRequeue[] = [
      { id: 'r1', title: 'A', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' },
      { id: 'r2', title: 'B', status: 'infra_failed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' },
