  });

  it('passes through id and title for each kind correctly', () => {
    const db = makeDb();
    insertSettledRequeues(db, 5, 3);
    const rq: InboxRequeue[] = [{ id: 'rq-id-42', title: 'RQ Title', status: 'regressed', updated_at: D30_AGO, requeued_as: null, queue_class: 'operator' }];
    const labels: InboxLabel[] = [{ id: 'lbl-id-99', title: 'LBL Title', status: 'x', reason: '', verdict_at: D30_AGO, label: null }];
    const mem = [{ id: 'mem-id-7', title: 'MEM Title', content: '', memory_type: 'rule', status: 'candidate', created_at: D30_AGO }];
    const out = rankNeedsYou(db, rq, labels, mem, NOW, { labelled: 20, wrong: 1 });
    const byId = Object.fromEntries(out.map((o) => [o.id, o]));
