  it('excludes gym loop_runs that are not in a finished status', () => {
    const db = fresh();
    db.exec(gymCols);
    db.prepare(`INSERT INTO loop_runs VALUES (?, ?, ?, ?, ?, ?)`).run(
      'evolution-gym', 'running',
      JSON.stringify({ gym: { remote_host: 'host-a', species: 'alpha' } }),
      '2026-01-10T00:00:00.000Z', null, '2026-01-10T01:00:00.000Z',
    );
    expect(gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z')).toEqual([]);
    db.close();
  });

  it('excludes gym runs without a remote_host and non-gym loop_names', () => {
    const db = fresh();
    db.exec(gymCols);
    db.prepare(`INSERT INTO loop_runs VALUES (?, ?, ?, ?, ?, ?)`).run(
      'evolution-gym', 'completed', JSON.stringify({}), '2026-01-10T00:00:00.000Z', '2026-01-10T01:00:00.000Z', '2026-01-10T01:00:00.000Z');
    db.prepare(`INSERT INTO loop_runs VALUES (?, ?, ?, ?, ?, ?)`).run(
      'other-loop', 'completed', JSON.stringify({ gym: { remote_host: 'h' } }), '2026-01-10T00:00:00.000Z', '2026-01-10T01:00:00.000Z', '2026-01-10T01:00:00.000Z');
    expect(gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z')).toEqual([]);
    db.close();
  });

  it('excludes jobs outside the time window (upper bound is exclusive)', () => {
    const db = fresh();
    db.exec(`CREATE TABLE committee_jobs (host TEXT, claimed_at TEXT, finished_at TEXT)`);
    // before since
    db.prepare(`INSERT INTO committee_jobs VALUES (?, ?, ?)`).run('h', '2025-06-10T00:00:00.000Z', '2025-06-10T01:00:00.000Z');
    // exactly at until -> excluded because created/claimed < until
    db.prepare(`INSERT INTO committee_jobs VALUES (?, ?, ?)`).run('h', '2026-02-01T00:00:00.000Z', '2026-02-01T01:00:00.000Z');
    expect(gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z')).toEqual([]);
    db.close();
  });

  it('returns remote maker and committee jobs with exact consumers in the window', () => {
    const db = fresh();
    db.exec(`CREATE TABLE remote_maker_jobs (host TEXT, species TEXT, claimed_at TEXT, finished_at TEXT)`);
    db.exec(`CREATE TABLE committee_jobs (host TEXT, claimed_at TEXT, finished_at TEXT)`);
    db.prepare(`INSERT INTO remote_maker_jobs VALUES (?, ?, ?, ?)`).run('host-b', 'gamma', '2026-01-11T00:00:00.000Z', '2026-01-11T00:30:00.000Z');
    db.prepare(`INSERT INTO committee_jobs VALUES (?, ?, ?)`).run('host-c', '2026-01-12T00:00:00.000Z', '2026-01-12T00:15:00.000Z');
    const jobs = gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z');
    expect(jobs).toHaveLength(2);
    expect(jobs.map((j) => j.consumer).sort()).toEqual(['committee', 'maker:remote@host-b/gamma']);
    const maker = jobs.find((j) => j.consumer === 'maker:remote@host-b/gamma')!;
    expect(maker.start).toBe(Date.parse('2026-01-11T00:00:00.000Z'));
    expect(maker.end).toBe(Date.parse('2026-01-11T00:30:00.000Z'));
    db.close();
  });

  it('filters out jobs where end is not greater than start or host/timestamps are invalid', () => {
    const db = fresh();
    db.exec(`CREATE TABLE committee_jobs (host TEXT, claimed_at TEXT, finished_at TEXT)`);
    // equal end/start
    db.prepare(`INSERT INTO committee_jobs VALUES (?, ?, ?)`).run('h', '2026-01-12T00:00:00.000Z', '2026-01-12T00:00:00.000Z');
    // null host
    db.prepare(`INSERT INTO committee_jobs VALUES (?, ?, ?)`).run(null, '2026-01-12T00:00:00.000Z', '2026-01-12T01:00:00.000Z');
    expect(gpuJobs(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z')).toEqual([]);
    db.close();
  });
});

