    expect(maker.day).toBe('2026-01-10');
    const reviewer = rows.find((r) => r.consumer === 'reviewer:checker:opencode')!;
    expect(reviewer.cloud).toBe(200);
    expect(reviewer.local).toBe(0);
    db.close();
  });

  it('maps security_checker to a reviewer consumer and unknown roles to lease:', () => {
    const db = fresh();
    db.exec(leaseCols);
    db.prepare(`INSERT INTO worker_leases VALUES (?, ?, ?, ?)`).run(
      '2026-01-10T12:00:00.000Z', 'security_checker', 'opencode', JSON.stringify({ runtime_usage: { total_tokens: 70 } }),
    );
    db.prepare(`INSERT INTO worker_leases VALUES (?, ?, ?, ?)`).run(
      '2026-01-10T12:30:00.000Z', 'scout', 'opencode', JSON.stringify({ runtime_usage: { total_tokens: 40 } }),
    );
    const rows = tokenLedger(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z');
    expect(rows.find((r) => r.consumer === 'reviewer:security_checker:opencode')!.cloud).toBe(70);
    expect(rows.find((r) => r.consumer === 'lease:scout:opencode')!.cloud).toBe(40);
    db.close();
  });

  it('excludes manual runtime leases and out-of-window leases', () => {
    const db = fresh();
    db.exec(leaseCols);
    db.prepare(`INSERT INTO worker_leases VALUES (?, ?, ?, ?)`).run(
      '2026-01-10T12:00:00.000Z', 'maker', 'manual', JSON.stringify({ runtime_usage: { total_tokens: 999 } }),
    );
    db.prepare(`INSERT INTO worker_leases VALUES (?, ?, ?, ?)`).run(
      '2025-01-10T12:00:00.000Z', 'maker', 'remote', JSON.stringify({ model: 'qwen', runtime_usage: { total_tokens: 888 } }),
    );
    expect(tokenLedger(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z')).toEqual([]);
    db.close();
  });

  it('classifies llm_model_calls by isLocalModel and sums tokens per (day, consumer, model, provider)', () => {
    const db = fresh();
    db.exec(`CREATE TABLE llm_model_calls (created_at TEXT, consumer TEXT, model TEXT, provider TEXT, tokens_in INTEGER, tokens_out INTEGER)`);
    // two local calls in the same group -> summed to 165 local
    db.prepare(`INSERT INTO llm_model_calls VALUES (?, ?, ?, ?, ?, ?)`).run('2026-01-10T10:00:00.000Z', 'agent-1', 'llama3', 'ollama', 100, 50);
    db.prepare(`INSERT INTO llm_model_calls VALUES (?, ?, ?, ?, ?, ?)`).run('2026-01-10T10:30:00.000Z', 'agent-1', 'llama3', 'ollama', 10, 5);
    // one cloud call
    db.prepare(`INSERT INTO llm_model_calls VALUES (?, ?, ?, ?, ?, ?)`).run('2026-01-10T11:00:00.000Z', 'agent-2', 'gpt-4', 'openai', 300, 200);
    const rows = tokenLedger(db, '2026-01-01T00:00:00.000Z', '2026-02-01T00:00:00.000Z');
    expect(rows).toHaveLength(2);
    const local = rows.find((r) => r.consumer === 'llm:agent-1')!;
    expect(local.local).toBe(165);
    expect(local.cloud).toBe(0);
    const cloud = rows.find((r) => r.consumer === 'llm:agent-2')!;
    expect(cloud.cloud).toBe(500);
    expect(cloud.local).toBe(0);
    db.close();
  });
});

