  });

  it('omits the interval (low/high) when n < 5 but still reports value and n', () => {
    expect(valuePer(3, 2, 100)).toEqual({ value: 0.03, low: null, high: null, n: 2 });
  });

  it('reports a Wilson-scaled interval bracketing the point value when n >= 5', () => {
