import { describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import {
  F2_SUSPENDED_ARM,
  FALLBACK_REF,
  FALLBACK_REASON,
  TG_LOOP_NAME,
  applyOutageFallback,
  effectiveFallbackRuntime,
  isFallbackLease,
  notFallbackGoalSql,
  notFallbackOutcomeSql,
  notFallbackRunSql,
  outageFallbackRuntime,
} from '../services/ollama-outage-fallback';

const makeDb = () => {
  const db = new Database(':memory:');
  db.exec(`CREATE TABLE loop_runs (
    id TEXT PRIMARY KEY,
    goal_id TEXT NOT NULL
  )`);
  db.exec(`CREATE TABLE worker_leases (
    id TEXT PRIMARY KEY,
    loop_run_id TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT '',
    runtime TEXT NOT NULL,
    metadata TEXT NOT NULL,
    updated_at TEXT
  )`);
  db.exec(`CREATE TABLE outcomes (
    id TEXT PRIMARY KEY,
    evidence_refs_json TEXT
  )`);
  return db;
};

const fallbackMeta = () => JSON.stringify({ runtime_fallback: { from: 'opencode', to: 'claude' } });
const plainMeta = () => JSON.stringify({});

describe('ollama-outage-fallback exports — pinned constants', () => {
  it('pins the exact string values that other modules and SQL depend on', () => {
    expect(FALLBACK_REASON).toBe('ollama_outage');
    // FALLBACK_REF is embedded in evidence_refs_json and matched by notFallbackOutcomeSql.
    expect(FALLBACK_REF).toBe('runtime_fallback:ollama_outage');
    expect(F2_SUSPENDED_ARM).toBe('fallback_suspended');
    expect(TG_LOOP_NAME).toBe('tg-001');
  });
});

describe('ollama-outage-fallback exports — outageFallbackRuntime', () => {
  it('returns claude only for a trimmed/lowercased claude flag, else null', () => {
    expect(outageFallbackRuntime({ OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' })).toBe('claude');
    expect(outageFallbackRuntime({ OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'Claude' })).toBe('claude');
    expect(outageFallbackRuntime({ OLLAMA_OUTAGE_FALLBACK_RUNTIME: '  CLAUDE  ' })).toBe('claude');
    expect(outageFallbackRuntime({ OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'codex' })).toBeNull();
    expect(outageFallbackRuntime({ OLLAMA_OUTAGE_FALLBACK_RUNTIME: '' })).toBeNull();
    expect(outageFallbackRuntime({})).toBeNull();
  });

  it('effectiveFallbackRuntime short-circuits on the manual flag without consulting the db', () => {
    // Manual flag wins even with a null db (no ollama state to read).
    expect(effectiveFallbackRuntime(null, { OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' })).toBe('claude');
    // No flag and no auto-failover → null regardless of db.
    expect(effectiveFallbackRuntime(makeDb(), {})).toBeNull();
  });
});

describe('ollama-outage-fallback exports — isFallbackLease', () => {
  it('is true only when metadata.runtime_fallback is a non-null object', () => {
    expect(isFallbackLease({ metadata: { runtime_fallback: { from: 'opencode', to: 'claude' } } })).toBe(true);
    expect(isFallbackLease({ metadata: {} })).toBe(false);
    expect(isFallbackLease({ metadata: { runtime_fallback: null } })).toBe(false);
    expect(isFallbackLease({ metadata: { runtime_fallback: 'runtime_fallback:ollama_outage' } })).toBe(false);
  });
});

describe('ollama-outage-fallback exports — applyOutageFallback', () => {
  const manual = { OLLAMA_OUTAGE_FALLBACK_RUNTIME: 'claude' };

  it('leaves the lease untouched when the fallback is off', () => {
    const db = makeDb();
    const lease = { id: 'l1', role: 'maker', runtime: 'opencode', metadata: { model: 'gpt-x' } as Record<string, unknown> };
    const run = { id: 'r1', loop_name: 'some-goal' };
    expect(applyOutageFallback(db, run, lease, 'opencode', {})).toBe('opencode');
    expect(lease.runtime).toBe('opencode');
    expect(lease.metadata).toEqual({ model: 'gpt-x' });
  });

  it('ignores non-opencode runtimes even with the flag on', () => {
    const db = makeDb();
    const lease = { id: 'l2', role: 'maker', runtime: 'codex', metadata: {} as Record<string, unknown> };
    const run = { id: 'r2', loop_name: 'some-goal' };
    expect(applyOutageFallback(db, run, lease, 'codex', manual)).toBe('codex');
    expect(lease.metadata).not.toHaveProperty('runtime_fallback');
  });

  it('never rewrites gym or TG-001 leases even with the flag on', () => {
    for (const loopName of ['evolution-gym', TG_LOOP_NAME]) {
      const db = makeDb();
      const lease = { id: `l-${loopName}`, role: 'maker', runtime: 'opencode', metadata: {} as Record<string, unknown> };
      const run = { id: `r-${loopName}`, loop_name: loopName };
      expect(applyOutageFallback(db, run, lease, 'opencode', manual)).toBe('opencode');
      expect(lease.metadata).not.toHaveProperty('runtime_fallback');
    }
  });

  it('leaves a lease that already carries a subscription_auth marker untouched', () => {
    const db = makeDb();
    const lease = { id: 'l3', role: 'maker', runtime: 'opencode', metadata: { subscription_auth: 'claude' } as Record<string, unknown> };
    const run = { id: 'r3', loop_name: 'some-goal' };
    expect(applyOutageFallback(db, run, lease, 'opencode', manual)).toBe('opencode');
    expect(lease.metadata).not.toHaveProperty('runtime_fallback');
  });

  it('rewrites an opencode production lease to claude and persists the row', () => {
    const db = makeDb();
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, role, runtime, metadata) VALUES (?, ?, ?, ?, ?)`)
      .run('l4', 'r4', 'maker', 'opencode', JSON.stringify({ model: 'gpt-x' }));
    const lease = { id: 'l4', role: 'maker', runtime: 'opencode', metadata: { model: 'gpt-x' } as Record<string, unknown> };
    const run = { id: 'r4', loop_name: 'some-goal' };

    expect(applyOutageFallback(db, run, lease, 'opencode', manual)).toBe('claude');
    // In-place object update.
    expect(lease.runtime).toBe('claude');
    const fb = lease.metadata.runtime_fallback as Record<string, unknown>;
    expect(fb.from).toBe('opencode');
    expect(fb.to).toBe('claude');
    expect(fb.reason).toBe(FALLBACK_REASON);
    expect(fb.from_model).toBe('gpt-x');
    // Manual flag → no auto trigger marker; the opencode model is dropped; subscription marker set.
    expect(fb).not.toHaveProperty('trigger');
    expect(lease.metadata).not.toHaveProperty('model');
    expect(lease.metadata.subscription_auth).toBe('claude');

    // The row was actually rewritten in the db (idempotent source of truth).
    const row = db.prepare(`SELECT runtime, metadata FROM worker_leases WHERE id = ?`).get('l4') as {
      runtime: string; metadata: string;
    };
    expect(row.runtime).toBe('claude');
    const storedMeta = JSON.parse(row.metadata) as Record<string, unknown>;
    expect(storedMeta.model).toBeUndefined();
    expect((storedMeta.runtime_fallback as { to?: string }).to).toBe('claude');
  });

  it('suspends a randomised checker arm and records its origin', () => {
    const db = makeDb();
    const lease = { id: 'l5', role: 'checker', runtime: 'opencode', metadata: { checker_family_arm: 'armA' } as Record<string, unknown> };
    const run = { id: 'r5', loop_name: 'some-goal' };
    expect(applyOutageFallback(db, run, lease, 'opencode', manual)).toBe('claude');
    expect(lease.metadata.checker_family_arm).toBe(F2_SUSPENDED_ARM);
    const fb = lease.metadata.runtime_fallback as Record<string, unknown>;
    expect(fb.from_checker_family_arm).toBe('armA');
  });

  it('is idempotent for a continuation of an already-fallen-back lease (no rewrite)', () => {
    const db = makeDb();
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, role, runtime, metadata) VALUES (?, ?, ?, ?, ?)`)
      .run('l6', 'r6', 'maker', 'claude', fallbackMeta());
    // Continuation from the original opencode runtime keeps the recorded target.
    let lease = { id: 'l6', role: 'maker', runtime: 'opencode', metadata: JSON.parse(fallbackMeta()) as Record<string, unknown> };
    const run = { id: 'r6', loop_name: 'some-goal' };
    expect(applyOutageFallback(db, run, lease, 'opencode', {})).toBe('claude');
    // A non-matching incoming runtime is returned unchanged and nothing is rewritten.
    lease = { id: 'l6', role: 'maker', runtime: 'claude', metadata: JSON.parse(fallbackMeta()) as Record<string, unknown> };
    expect(applyOutageFallback(db, run, lease, 'claude', {})).toBe('claude');
  });
});

describe('ollama-outage-fallback exports — notFallbackOutcomeSql', () => {
  it('emits a SQL fragment that excludes outcomes whose evidence_refs_json contains the fallback ref', () => {
    const db = makeDb();
    const sql = notFallbackOutcomeSql('o');
    expect(sql).toContain('COALESCE(o.evidence_refs_json,');
    expect(sql).toContain(FALLBACK_REF);
    db.prepare(`INSERT INTO outcomes (id, evidence_refs_json) VALUES (?, ?), (?, ?), (?, ?)`).run(
      'out-plain',
      JSON.stringify(['other:ref']),
      'out-fallback',
      JSON.stringify([FALLBACK_REF, 'other:ref']),
      'out-null',
      null,
    );
    const rows = db
      .prepare(`SELECT o.id AS id FROM outcomes o WHERE ${sql} ORDER BY o.id`)
      .all() as { id: string }[];
    // plain and null (COALESCE → '') pass; the fallback outcome is excluded
    expect(rows.map((r) => r.id)).toEqual(['out-null', 'out-plain']);
  });
});

describe('ollama-outage-fallback exports — notFallbackGoalSql', () => {
  it('emits a SQL fragment that is true only for goals with no fallback lease', () => {
    const db = makeDb();
    const sql = notFallbackGoalSql('g.goal_id');
    expect(sql).toContain('loop_runs fr');
    expect(sql).toContain('json_extract(fl.metadata');
    expect(sql).toContain('g.goal_id');
    db.prepare(`INSERT INTO loop_runs (id, goal_id) VALUES (?, ?), (?, ?), (?, ?)`).run(
      'run-clean',
      'goal-clean',
      'run-fallback',
      'goal-fallback',
      'run-mixed',
      'goal-mixed',
    );
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, role, runtime, metadata) VALUES (?, ?, ?, ?, ?), (?, ?, ?, ?, ?), (?, ?, ?, ?, ?)`).run(
      'lease-clean',
      'run-clean',
      'maker',
      'opencode',
      plainMeta(),
      'lease-fallback',
      'run-fallback',
      'maker',
      'claude',
      fallbackMeta(),
      'lease-mixed-plain',
      'run-mixed',
      'maker',
      'opencode',
      plainMeta(),
    );
    db.prepare(`INSERT INTO worker_leases (id, loop_run_id, role, runtime, metadata) VALUES (?, ?, ?, ?, ?)`).run(
      'lease-mixed-fallback',
      'run-mixed',
      'maker',
      'claude',
      fallbackMeta(),
    );
    const goals = db
      .prepare(
        `SELECT g.goal_id AS goal_id, CASE WHEN ${sql} THEN 1 ELSE 0 END AS ok FROM (SELECT 'goal-clean' AS goal_id UNION ALL SELECT 'goal-fallback' UNION ALL SELECT 'goal-mixed') g ORDER BY g.goal_id`,
      )
      .all() as { goal_id: string; ok: number }[];
    const byGoal = new Map(goals.map((g) => [g.goal_id, g.ok]));
    expect(byGoal.get('goal-clean')).toBe(1);
    expect(byGoal.get('goal-fallback')).toBe(0);
    expect(byGoal.get('goal-mixed')).toBe(0);
  });
});

