      expect(ace.ok).toBe(1);
      expect(ace.tokens_in).toBe(100);
      expect(ace.tokens_out).toBe(20);
    });
    it('excludes rows created before the since cutoff', () => {
      db.prepare(`INSERT INTO llm_model_calls (consumer, model, ok, latency_ms, out_chars, shadow, tokens_in, tokens_out, purpose, experiment_id, cost_basis, list_price_cost, marginal_cost, created_at)
        VALUES ('maker','m',1,10,0,0,100,20,'maker:self-improvement','ACE-001:01','metered',0.01,0.01,'2000-06-01T00:00:00.000Z'),
               ('maker','m',1,8,0,0,50,10,'maker:planning',NULL,'local',NULL,0,'2030-01-01T00:00:00.000Z')`).run();
      const totals = ledgerTotals(db, '2020-01-01T00:00:00.000Z');
      // Only the 2030 row is inside the window.
      expect(totals.by_purpose).toHaveLength(1);
      expect((totals.by_purpose[0] as Record<string, unknown>).key).toBe('maker:planning');
      expect(totals.by_experiment).toEqual([]);
    });
    it('returns empty arrays when no rows match the window', () => {
      const totals = ledgerTotals(db, '9999-12-31T00:00:00.000Z');
      expect(totals.by_purpose).toEqual([]);
      expect(totals.by_experiment).toEqual([]);
    });
    it('returns empty arrays when the llm_model_calls table is missing', () => {
      db.exec('DROP TABLE llm_model_calls');
      const totals = ledgerTotals(db, '2000-01-01T00:00:00.000Z');
      expect(totals.by_purpose).toEqual([]);
      expect(totals.by_experiment).toEqual([]);
    });
  });
});

