    } finally {
      db.close();
    }
  });
});

units.retried_test:
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import {
  modelSelectorMode,
  shadowRate,
  costWeight,
  candidates,
  costBasis,
  callCost,
  recordModelCall,
  setLlmLedger,
  getLlmLedger,
  recordLlmCall,
  measured,
  qualifies,
  chooseModel,
  shadowCandidate,
} from '../services/model-selector';

// ─── helpers ────────────────────────────────────────────────────────────────
const D = (days: number): string => new Date(Date.now() - days * 86_400_000).toISOString();
const NOW = () => Date.now();

function makeDb(): InstanceType<typeof Database> {
  const db = new Database(':memory:');
  db.exec(`
    CREATE TABLE IF NOT EXISTS llm_model_calls (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      consumer TEXT NOT NULL,
      model TEXT NOT NULL,
      ok INTEGER NOT NULL,
      latency_ms INTEGER,
      out_chars INTEGER,
      shadow INTEGER NOT NULL DEFAULT 0,
      agree INTEGER,
      provider TEXT,
      tokens_in INTEGER,
      tokens_out INTEGER,
      task_kind TEXT,
      run_id TEXT,
      status TEXT,
      attempts INTEGER,
      purpose TEXT,
      experiment_id TEXT,
      cost_basis TEXT,
      list_price_cost REAL,
      marginal_cost REAL,
      created_at TEXT NOT NULL
    );
  `);
  return db;
}

/** Insert n rows for a consumer/model with given ok/shadow/agree pattern. */
function seed(db: InstanceType<typeof Database>, consumer: string, model: string, opts: { n?: number; ok?: boolean[]; shadow?: (boolean)[]; agree?: (boolean | null)[]; daysAgo?: number }) {
  const n = opts.n ?? 1;
  const ins = db.prepare(
    'INSERT INTO llm_model_calls (consumer, model, ok, latency_ms, out_chars, shadow, agree, created_at) VALUES (?, ?, ?, 10, 5, ?, ?, ?)',
  );
  for (let i = 0; i < n; i++) {
    ins.run(consumer, model, (opts.ok?.[i] ?? true) ? 1 : 0, (opts.shadow?.[i] ?? false) ? 1 : 0, opts.agree?.[i] === null ? null : (opts.agree?.[i] ?? true) ? 1 : 0, D(opts.daysAgo ?? 1));
  }
}

// ─── tests ──────────────────────────────────────────────────────────────────
describe('model-selector exports', () => {
  let db: InstanceType<typeof Database>;

  beforeEach(() => {
    db = makeDb();
  });

  afterEach(() => {
    setLlmLedger(null);
    db.close();
  });

  // ── modelSelectorMode ─────────────────────────────────────────────────────
  describe('modelSelectorMode', () => {
    it('defaults to "off" when env var is absent', () => {
      expect(modelSelectorMode({} as NodeJS.ProcessEnv)).toBe('off');
    });
    it('returns "shadow" for MODEL_SELECTOR_MODE=shadow', () => {
      expect(modelSelectorMode({ MODEL_SELECTOR_MODE: 'shadow' } as NodeJS.ProcessEnv)).toBe('shadow');
    });
    it('returns "enforce" for MODEL_SELECTOR_MODE=enforce', () => {
      expect(modelSelectorMode({ MODEL_SELECTOR_MODE: 'enforce' } as NodeJS.ProcessEnv)).toBe('enforce');
    });
    it('falls back to "off" for any other value', () => {
      expect(modelSelectorMode({ MODEL_SELECTOR_MODE: 'bogus' } as NodeJS.ProcessEnv)).toBe('off');
      expect(modelSelectorMode({ MODEL_SELECTOR_MODE: '' } as NodeJS.ProcessEnv)).toBe('off');
    });
  });

  // ── shadowRate ────────────────────────────────────────────────────────────
  describe('shadowRate', () => {
    it('defaults to 0.1 when env var is absent', () => {
      expect(shadowRate({} as NodeJS.ProcessEnv)).toBe(0.1);
    });
    it('parses a valid rate in [0,1]', () => {
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: '0.5' } as NodeJS.ProcessEnv)).toBe(0.5);
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: '0' } as NodeJS.ProcessEnv)).toBe(0);
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: '1' } as NodeJS.ProcessEnv)).toBe(1);
    });
    it('falls back to 0.1 for out-of-range or non-numeric values', () => {
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: '1.5' } as NodeJS.ProcessEnv)).toBe(0.1);
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: '-0.1' } as NodeJS.ProcessEnv)).toBe(0.1);
      expect(shadowRate({ MODEL_SELECTOR_SHADOW_RATE: 'abc' } as NodeJS.ProcessEnv)).toBe(0.1);
    });
  });

  // ── costWeight ────────────────────────────────────────────────────────────
  describe('costWeight', () => {
    it('returns the default weight for known models (kimi-k3=4, glm-5.3=2, glm-5.3-flash=1)', () => {
      const env = {} as NodeJS.ProcessEnv;
      expect(costWeight('kimi-k3', env)).toBe(4);
      expect(costWeight('glm-5.3', env)).toBe(2);
      expect(costWeight('glm-5.3-flash', env)).toBe(1);
    });
    it('strips ollama: prefix and :cloud suffix before lookup', () => {
      const env = {} as NodeJS.ProcessEnv;
      expect(costWeight('ollama:kimi-k3:cloud', env)).toBe(4);
      expect(costWeight('ollama:glm-5.3:cloud', env)).toBe(2);
    });
    it('returns 2 for unknown models', () => {
      expect(costWeight('unknown-model', {} as NodeJS.ProcessEnv)).toBe(2);
    });
    it('honours MODEL_COST_WEIGHTS override', () => {
      const env = { MODEL_COST_WEIGHTS: 'a=7,b=3' } as NodeJS.ProcessEnv;
      expect(costWeight('a', env)).toBe(7);
      expect(costWeight('b', env)).toBe(3);
      // model not in custom list → default 2
      expect(costWeight('c', env)).toBe(2);
    });
    it('ignores non-positive weights (falls back to 2)', () => {
      const env = { MODEL_COST_WEIGHTS: 'x=0,y=-1' } as NodeJS.ProcessEnv;
      expect(costWeight('x', env)).toBe(2);
      expect(costWeight('y', env)).toBe(2);
    });
  });

  // ── candidates ────────────────────────────────────────────────────────────
  describe('candidates', () => {
    it('returns empty array when no env var is set', () => {
      expect(candidates('myConsumer', {} as NodeJS.ProcessEnv)).toEqual([]);
    });
    it('parses comma-separated, trims whitespace, filters empties', () => {
      const env = { MODEL_CANDIDATES_MYCONSUMER: ' a , b ,, c ' } as unknown as NodeJS.ProcessEnv;
      expect(candidates('myConsumer', env)).toEqual(['a', 'b', 'c']);
    });
    it('uppercases the consumer for the env key lookup', () => {
      const env = { MODEL_CANDIDATES_PANEL: 'x,y' } as unknown as NodeJS.ProcessEnv;
      expect(candidates('panel', env)).toEqual(['x', 'y']);
    });
  });

  // ── costBasis ─────────────────────────────────────────────────────────────
  describe('costBasis', () => {
    it('matches provider substring (ollama → flat_subscription)', () => {
      expect(costBasis('ollama.com', 'some-model', {} as NodeJS.ProcessEnv)).toBe('flat_subscription');
    });
    it('matches :cloud in model name → flat_subscription', () => {
      expect(costBasis(null, 'kimi-k3:cloud', {} as NodeJS.ProcessEnv)).toBe('flat_subscription');
    });
    it('matches localhost/127.0.0.1 → local', () => {
      expect(costBasis('localhost', 'anything', {} as NodeJS.ProcessEnv)).toBe('local');
      expect(costBasis('http://127.0.0.1:8080', 'm', {} as NodeJS.ProcessEnv)).toBe('local');
    });
    it('matches nvidia → free_tier', () => {
      expect(costBasis('nvidia', 'model-x', {} as NodeJS.ProcessEnv)).toBe('free_tier');
    });
    it('matches typesafe → metered', () => {
      expect(costBasis('typesafe', 'gpt-4', {} as NodeJS.ProcessEnv)).toBe('metered');
    });
    it('returns "unknown" when nothing matches', () => {
      expect(costBasis('some-random-provider', 'random-model', {} as NodeJS.ProcessEnv)).toBe('unknown');
    });
    it('honours LLM_COST_BASIS override (first match wins)', () => {
      const env = { LLM_COST_BASIS: 'myprovider=metered' } as unknown as NodeJS.ProcessEnv;
      // custom rule should take precedence over defaults
      expect(costBasis('myprovider', 'ollama-something', env)).toBe('metered');
    });
  });

  // ── callCost ──────────────────────────────────────────────────────────────
  describe('callCost', () => {
    it('flat_subscription → marginal_cost=0, list_price_cost=null without tokens', () => {
      const r = callCost({ model: 'kimi-k3:cloud', provider: 'ollama.com' }, {} as NodeJS.ProcessEnv);
      expect(r.cost_basis).toBe('flat_subscription');
      expect(r.marginal_cost).toBe(0);
      expect(r.list_price_cost).toBeNull();
    });
    it('local → marginal_cost=0', () => {
      const r = callCost({ model: 'm', provider: 'localhost' }, {} as NodeJS.ProcessEnv);
      expect(r.cost_basis).toBe('local');
      expect(r.marginal_cost).toBe(0);
    });
    it('free_tier → marginal_cost=0', () => {
      const r = callCost({ model: 'm', provider: 'nvidia' }, {} as NodeJS.ProcessEnv);
      expect(r.cost_basis).toBe('free_tier');
      expect(r.marginal_cost).toBe(0);
    });
    it('metered with price and tokens computes list_price_cost and marginal_cost=list', () => {
      const env = { LLM_PRICE_PER_MTOK: 'gpt-4=5/15' } as unknown as NodeJS.ProcessEnv;
      // 1M input + 1M output at $5/$15 per MTok → (1*5 + 1*15)/1 = 20
      const r = callCost({ model: 'gpt-4', provider: 'typesafe', tokensIn: 1_000_000, tokensOut: 1_000_000 }, env);
      expect(r.cost_basis).toBe('metered');
      expect(r.list_price_cost).toBeCloseTo(20, 4);
      expect(r.marginal_cost).toBeCloseTo(20, 4);
    });
    it('metered without tokens → list_price_cost=null, marginal_cost=null', () => {
      const env = { LLM_PRICE_PER_MTOK: 'gpt-4=5/15' } as unknown as NodeJS.ProcessEnv;
      const r = callCost({ model: 'gpt-4', provider: 'typesafe' }, env);
      expect(r.cost_basis).toBe('metered');
      expect(r.list_price_cost).toBeNull();
      expect(r.marginal_cost).toBeNull();
    });
    it('unknown basis → marginal_cost=null', () => {
      const r = callCost({ model: 'mystery', provider: 'nope' }, {} as NodeJS.ProcessEnv);
      expect(r.cost_basis).toBe('unknown');
      expect(r.marginal_cost).toBeNull();
    });
  });

  // ── qualifies ─────────────────────────────────────────────────────────────
  describe('qualifies', () => {
    it('returns true when all thresholds are met (n≥20, ok≥95%, wilson≥0.9, compared≥20, agree≥80%)', () => {
      // 40 calls, 40 ok (100%), 25 compared, 25 agreed (100%); wilsonLower(40,40)≈0.912 ≥ 0.9
      expect(qualifies({ n: 40, ok: 40, compared: 25, agreed: 25 })).toBe(true);
    });
    it('returns false when n < 20', () => {
      expect(qualifies({ n: 19, ok: 19, compared: 25, agreed: 25 })).toBe(false);
    });
    it('returns false when ok rate < 95%', () => {
      // 20 calls, 18 ok = 90%
      expect(qualifies({ n: 20, ok: 18, compared: 25, agreed: 25 })).toBe(false);
    });
    it('returns false when Wilson lower bound < 0.9 even if raw rate ≥ 95%', () => {
      // 20 calls, 19 ok = 95%; wilsonLower(19,20) ≈ 0.764 < 0.9
      expect(qualifies({ n: 20, ok: 19, compared: 25, agreed: 25 })).toBe(false);
    });
    it('returns true at the boundary: enough calls for wilson ≥ 0.9 with 100% ok', () => {
      // wilsonLower(n,n) for n=30 → (1 + z²/60 - z*sqrt(z²/(4*30))/30)/(1+z²/30)
      // For n=30, p=1: (1+0.0627-1.96*sqrt(0.0627/30)/30... let's just use a large n where it clearly passes
      // n=50, ok=50: wilson should be well above 0.9
      expect(qualifies({ n: 50, ok: 50, compared: 25, agreed: 25 })).toBe(true);
    });
    it('returns false when compared < 20', () => {
      expect(qualifies({ n: 50, ok: 50, compared: 19, agreed: 19 })).toBe(false);
    });
    it('returns false when agree rate < 80%', () => {
      // 25 compared, 19 agreed = 76%
      expect(qualifies({ n: 50, ok: 50, compared: 25, agreed: 19 })).toBe(false);
    });
    it('returns true at the agree boundary: exactly 80% (16/20)', () => {
      expect(qualifies({ n: 50, ok: 50, compared: 20, agreed: 16 })).toBe(true);
    });
  });

  // ── chooseModel ───────────────────────────────────────────────────────────
  describe('chooseModel', () => {
    const env = { MODEL_CANDIDATES_TESTC: 'glm-5.3-flash,glm-5.3,kimi-k3' } as unknown as NodeJS.ProcessEnv;

    it('returns incumbent when no candidate qualifies', () => {
      expect(chooseModel(db, 'testc', 'kimi-k3', env)).toBe('kimi-k3');
    });
    it('picks the cheapest qualified candidate that is cheaper than incumbent', () => {
      // Seed glm-5.3-flash (weight=1) with qualifying stats; incumbent kimi-k3 (weight=4)
      seed(db, 'testc', 'glm-5.3-flash', { n: 50, ok: new Array(50).fill(true), shadow: new Array(50).fill(true), agree: new Array(50).fill(true) });
      expect(chooseModel(db, 'testc', 'kimi-k3', env)).toBe('glm-5.3-flash');
    });
    it('does not pick a candidate more expensive than the incumbent', () => {
      // Only kimi-k3 (weight=4) qualifies but incumbent is glm-5.3-flash (weight=1); kimi-k3 is NOT cheaper
      seed(db, 'testc', 'kimi-k3', { n: 50, ok: new Array(50).fill(true), shadow: new Array(50).fill(true), agree: new Array(50).fill(true) });
      expect(chooseModel(db, 'testc', 'glm-5.3-flash', env)).toBe('glm-5.3-flash');
    });
    it('skips the incumbent even if it appears in candidates and qualifies', () => {
      // Incumbent glm-5.3 also in list; only glm-5.3-flash qualifies → picks flash
      seed(db, 'testc', 'glm-5.3-flash', { n: 50, ok: new Array(50).fill(true), shadow: new Array(50).fill(true), agree: new Array(50).fill(true) });
      seed(db, 'testc', 'glm-5.3', { n: 50, ok: new Array(50).fill(true), shadow: new Array(50).fill(true), agree: new Array(50).fill(true) });
      expect(chooseModel(db, 'testc', 'kimi-k3', env)).toBe('glm-5.3-flash');
    });
    it('ignores rows outside the 14-day window', () => {
      // Seed qualifying stats but 20 days ago (outside window)
      seed(db, 'testc', 'glm-5.3-flash', { n: 50, ok: new Array(50).fill(true), shadow: new Array(50).fill(true), agree: new Array(50).fill(true), daysAgo: 20 });
      expect(chooseModel(db, 'testc', 'kimi-k3', env)).toBe('kimi-k3');
    });
  });

  // ── shadowCandidate ───────────────────────────────────────────────────────
  describe('shadowCandidate', () => {
    const env = { MODEL_CANDIDATES_TESTC: 'glm-5.3-flash,glm-5.3' } as unknown as NodeJS.ProcessEnv;

    it('returns null when no candidates are configured', () => {
      expect(shadowCandidate(db, 'empty', 'incumbent', {} as NodeJS.ProcessEnv)).toBeNull();
    });
    it('picks the candidate with fewest shadow calls first', () => {
      // glm-5.3 has 1 shadow call; glm-5.3-flash has 0 → flash wins
      seed(db, 'testc', 'glm-5.3', { n: 1, ok: [true], shadow: [true], agree: [null] });
      expect(shadowCandidate(db, 'testc', 'kimi-k3', env)).toBe('glm-5.3-flash');
    });
    it('breaks ties by cost weight (cheapest first)', () => {
      // Both have 0 shadow calls; glm-5.3-flash (w=1) < glm-5.3 (w=2)
      expect(shadowCandidate(db, 'testc', 'kimi-k3', env)).toBe('glm-5.3-flash');
    });
    it('skips the incumbent even if it is in the candidate list', () => {
      const env2 = { MODEL_CANDIDATES_TESTC: 'glm-5.3,kimi-k3' } as unknown as NodeJS.ProcessEnv;
      // kimi-k3 is incumbent and also a candidate; only glm-5.3 should be returned
      expect(shadowCandidate(db, 'testc', 'kimi-k3', env2)).toBe('glm-5.3');
    });
  });

  // ── recordModelCall ───────────────────────────────────────────────────────
  describe('recordModelCall', () => {
    it('inserts a row with correct field mapping', () => {
      const at = new Date('2026-10-01T00:00:00.000Z');
      recordModelCall(db, {
        consumer: 'panel', model: 'kimi-k3', ok: true, latencyMs: 42.7,
        outChars: 128, shadow: 0, agree: null, provider: 'ollama.com',
        tokensIn: 100, tokensOut: 50, taskKind: 'review', runId: 'r1', status: 'ok', attempts: 1,
      }, at);
      const row = db.prepare('SELECT * FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.consumer).toBe('panel');
      expect(row.model).toBe('kimi-k3');
      expect(row.ok).toBe(1);
      expect(row.latency_ms).toBe(43); // Math.round(42.7)
      expect(row.out_chars).toBe(128);
      expect(row.shadow).toBe(0);
      expect(row.agree).toBeNull();
      expect(row.provider).toBe('ollama.com');
      expect(row.tokens_in).toBe(100);
      expect(row.tokens_out).toBe(50);
      expect(row.task_kind).toBe('review');
      expect(row.run_id).toBe('r1');
      expect(row.status).toBe('ok');
      expect(row.attempts).toBe(1);
      expect(row.purpose).toBe('panel:review');
      expect(row.created_at).toBe('2026-10-01T00:00:00.000Z');
    });
    it('defaults purpose to consumer when taskKind is absent', () => {
      recordModelCall(db, { consumer: 'jevs', model: 'm', ok: false, latencyMs: 1, outChars: 0, shadow: 0, agree: null }, new Date());
      const row = db.prepare('SELECT purpose FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.purpose).toBe('jevs');
    });
    it('stores agree=1 for true and agree=0 for false (not null)', () => {
      recordModelCall(db, { consumer: 'c', model: 'm', ok: true, latencyMs: 1, outChars: 0, shadow: 1, agree: true }, new Date());
      recordModelCall(db, { consumer: 'c', model: 'm', ok: true, latencyMs: 1, outChars: 0, shadow: 1, agree: false }, new Date());
      const rows = db.prepare('SELECT agree FROM llm_model_calls ORDER BY id').all() as Array<{ agree: number }>;
      expect(rows[0].agree).toBe(1);
      expect(rows[1].agree).toBe(0);
    });
    it('does not throw when the table is missing', () => {
      db.exec('DROP TABLE llm_model_calls');
      expect(() => recordModelCall(db, { consumer: 'x', model: 'y', ok: true, latencyMs: 1, outChars: 0, shadow: 0, agree: null })).not.toThrow();
    });
  });

  // ── setLlmLedger / getLlmLedger ───────────────────────────────────────────
  describe('setLlmLedger / getLlmLedger', () => {
    it('returns null when no ledger has been registered', () => {
      setLlmLedger(null);
      expect(getLlmLedger()).toBeNull();
    });
    it('returns the database handle registered via setLlmLedger', () => {
      const d2 = new Database(':memory:');
      try {
        setLlmLedger(d2);
        expect(getLlmLedger()).toBe(d2);
      } finally {
        d2.close();
      }
    });
    it('returns null again after resetting with setLlmLedger(null)', () => {
      const d3 = new Database(':memory:');
      try {
        setLlmLedger(d3);
        expect(getLlmLedger()).toBe(d3);
        setLlmLedger(null);
        expect(getLlmLedger()).toBeNull();
      } finally {
        d3.close();
      }
    });
  });

  // ── recordLlmCall ─────────────────────────────────────────────────────────
  describe('recordLlmCall', () => {
    it('records a row through the provided db (shadow=0, agree=null defaults)', () => {
      recordLlmCall({ consumer: 'llm-fallback', model: 'glm-5.3', ok: true, latencyMs: 10, outChars: 42 }, db);
      const row = db.prepare('SELECT * FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.consumer).toBe('llm-fallback');
      expect(row.model).toBe('glm-5.3');
      expect(row.ok).toBe(1);
      expect(row.shadow).toBe(0);
      expect(row.agree).toBeNull();
    });
    it('is a no-op when db is null and no ledger is registered', () => {
      setLlmLedger(null);
      expect(() => recordLlmCall({ consumer: 'x', model: 'y', ok: true, latencyMs: 1, outChars: 0 })).not.toThrow();
    });
    it('uses the global ledger when db arg is omitted', () => {
      setLlmLedger(db);
      recordLlmCall({ consumer: 'global-test', model: 'm', ok: false, latencyMs: 5, outChars: 0 });
      const row = db.prepare('SELECT * FROM llm_model_calls WHERE consumer = ?').get('global-test') as Record<string, unknown>;
      expect(row).toBeDefined();
      expect(row.ok).toBe(0);
    });
  });

  // ── measured ──────────────────────────────────────────────────────────────
  describe('measured', () => {
    it('returns the call result and records an ok row with timing', async () => {
      const result = await measured(
        { consumer: 'meas', model: 'kimi-k3' },
        async () => ({ value: 42 }),
        (r) => ({ outChars: r.value * 2 }),
        db,
      );
      expect(result).toEqual({ value: 42 });
      const row = db.prepare('SELECT * FROM llm_model_calls').get() as Record<string, unknown>;
      expect(row.consumer).toBe('meas');
      expect(row.model).toBe('kimi-k3');
      expect(row.ok).toBe(1);
      expect(row.out_chars).toBe(84);
      expect(typeof row.latency_ms).toBe('number');
      expect((row.latency_ms as number) >= 0).toBe(true);
    });
