    if (sql.includes('FROM worker_leases')) return { all: () => leases };
    return { get: () => undefined, all: () => [] };
  },
});

// Generic router for DB-dependent tests: match SQL by predicate, supply get/all/run per route.
interface Route { match: (sql: string) => boolean; get?: () => unknown; all?: () => unknown[]; run?: (...args: unknown[]) => { changes: number } }
function makeRouter(routes: Route[]) {
  const execs: string[] = [];
  return {
    __execs: execs,
    exec(sql: string) { execs.push(sql); },
    prepare(sql: string) {
      const hit = routes.find((r) => r.match(sql));
      if (!hit) return { get: () => undefined, all: () => [] as unknown[], run: () => ({ changes: 0 }) };
      return {
        get: hit.get ? () => hit.get!() : () => undefined,
        all: hit.all ? () => hit.all!() : () => [] as unknown[],
        run: hit.run ? (...a: unknown[]) => hit.run!(...a) : () => ({ changes: 0 }),
      };
    },
  };
}

