    expect(distillSkills(db, { SKILL_DISTILLATION_MODE: 'off' })).toEqual({ mode: 'off', created: 0, anti_patterns: 0, upgraded: 0 });
  });
});

// --- skillCardsView ---
describe('skillCardsView', () => {
  it('reports unknown (null total) with a reason when the table does not exist', () => {
    const db = makeRouter([{ match: (s) => s.includes('sqlite_master'), get: () => undefined }]);
    const view = skillCardsView(db as never, { SKILL_DISTILLATION_MODE: 'shadow' });
    expect(view.mode).toBe('shadow');
    expect(view.total).toBeNull();
    expect(view.by_lane).toEqual([]);
    expect(view.latest).toEqual([]);
    expect(view.reason).toBe('no cards recorded yet (SKILL_DISTILLATION_MODE has not run)');
    expect(view.note).toBe('record-only: cards are never injected into any maker, checker or panel context');
  });

  it('aggregates by_lane counts and parses latest card_json when the table exists', () => {
    const storedCard: SkillCard = { ...baseCard, lane: 'alpha' };
    const db = makeRouter([
      { match: (s) => s.includes('sqlite_master'), get: () => ({ x: 1 }) },
      { match: (s) => s.includes('COUNT(*) AS n'), all: () => [
        { lane: 'alpha', kind: 'skill', status: 'candidate', n: 2 },
        { lane: 'beta', kind: 'anti_pattern', status: 'regressed', n: 1 },
      ] },
      { match: (s) => s.includes('ORDER BY created_at DESC'), all: () => ([{
        run_id: 'r1', kind: 'skill', status: 'candidate', card_json: JSON.stringify(storedCard),
        content_sha256: 'abc123', created_at: 't1', updated_at: 't2',
      }]) },
    ]);
    const view = skillCardsView(db as never, { SKILL_DISTILLATION_MODE: 'shadow' });
    expect(view.total).toBe(3);
    expect(view.by_lane).toEqual([
      { lane: 'alpha', kind: 'skill', status: 'candidate', n: 2 },
      { lane: 'beta', kind: 'anti_pattern', status: 'regressed', n: 1 },
    ]);
    expect(view.latest).toHaveLength(1);
    expect(view.latest[0].run_id).toBe('r1');
    expect(view.latest[0].content_sha256).toBe('abc123');
    expect(view.latest[0].card).toEqual(storedCard);
    expect(view.reason).toBeNull();
  });
});

// --- startSkillDistillation (lifecycle) ---
describe('startSkillDistillation', () => {
  it('returns null when mode is off', () => {
    expect(startSkillDistillation({} as never, { SKILL_DISTILLATION_MODE: 'off' })).toBeNull();
  });
  it('starts timers in shadow mode and returns a stop function that clears them', () => {
    const stop = startSkillDistillation({} as never, { SKILL_DISTILLATION_MODE: 'shadow' });
    expect(typeof stop).toBe('function');
    stop!(); // must not throw; clears the scheduled timer + interval
  });
});

