import { expect, it } from 'vitest';
import Database from 'better-sqlite3';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  AUTH_MISSING,
  LIMIT_HIT,
  SUBSCRIPTION_ENV_MARKER,
  isBillingKey,
  subscriptionChildEnv,
  parseSubscriptionSpecies,
  subscriptionGymSpecies,
  subscriptionGymMaxPerDay,
  subscriptionLimitBackoffMs,
  codexAuthFile,
  subscriptionAuthPresent,
  isSubscriptionLimit,
  inLimitBackoff,
  subscriptionAttemptsToday,
  subscriptionGymEvidence,
} from '../services/subscription-gym';

const makeDb = () => {
  const db = new Database(':memory:');
  db.exec(`CREATE TABLE loop_runs (
    id TEXT PRIMARY KEY,
    metadata TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL
  )`);
  return db;
};

const insertRun = (db: Database, id: string, species: string, subscription: number, createdAt: string, extra?: Record<string, unknown>) => {
  const metadata = JSON.stringify({ gym: { species, subscription }, ...(extra ?? {}) });
  db.prepare(`INSERT INTO loop_runs (id, metadata, created_at) VALUES (?, ?, ?)`).run(id, metadata, createdAt);
};

// --- constants -------------------------------------------------------------
it('exports the fixed infra reason strings and env marker', () => {
  expect(AUTH_MISSING).toBe('infra: subscription_auth_missing');
  expect(LIMIT_HIT).toBe('infra: subscription_limit');
  expect(SUBSCRIPTION_ENV_MARKER).toBe('DJIMITFLO_SUBSCRIPTION_AUTH');
});

// --- isBillingKey / subscriptionChildEnv -----------------------------------
it('isBillingKey flags every *_API_KEY plus the known billing names only', () => {
  expect(isBillingKey('ANTHROPIC_API_KEY')).toBe(true);
  expect(isBillingKey('OPENAI_API_KEY')).toBe(true);
  expect(isBillingKey('OPENCODE_API_KEY')).toBe(true);
  expect(isBillingKey('MY_CUSTOM_API_KEY')).toBe(true);
  expect(isBillingKey('ANTHROPIC_AUTH_TOKEN')).toBe(true);
  expect(isBillingKey('ANTHROPIC_BASE_URL')).toBe(true);
  expect(isBillingKey('OPENAI_BASE_URL')).toBe(true);
  expect(isBillingKey('AZURE_OPENAI_ENDPOINT')).toBe(true);
  // not a billing key:
  expect(isBillingKey('PATH')).toBe(false);
  expect(isBillingKey('HOME')).toBe(false);
  expect(isBillingKey('CLAUDE_CODE_OAUTH_TOKEN')).toBe(false);
  expect(isBillingKey('CODEX_HOME')).toBe(false);
  expect(isBillingKey('SOME_API_KEYISH')).toBe(false); // must end exactly in _API_KEY
});

it('subscriptionChildEnv drops billing keys and the marker, keeps the rest', () => {
  const base = { ANTHROPIC_API_KEY: 'sk-a', OPENAI_API_KEY: 'sk-o', PATH: '/bin', HOME: '/h' } as NodeJS.ProcessEnv;
  const out = subscriptionChildEnv(base, undefined, {});
  expect(out.ANTHROPIC_API_KEY).toBeUndefined();
  expect(out.OPENAI_API_KEY).toBeUndefined();
  expect(out.PATH).toBe('/bin');
  expect(out.HOME).toBe('/h');
});

it('subscriptionChildEnv adds the claude OAuth token from the server env only when present', () => {
  const base = { ANTHROPIC_API_KEY: 'sk-a', PATH: '/bin' } as NodeJS.ProcessEnv;
  const withTok = subscriptionChildEnv(base, 'claude', { CLAUDE_CODE_OAUTH_TOKEN: 'tok-123' });
  expect(withTok.CLAUDE_CODE_OAUTH_TOKEN).toBe('tok-123');
  expect(withTok.ANTHROPIC_API_KEY).toBeUndefined();
  // no token in server env → not injected
  const without = subscriptionChildEnv(base, 'claude', {});
  expect(without.CLAUDE_CODE_OAUTH_TOKEN).toBeUndefined();
});

it('subscriptionChildEnv adds CODEX_HOME for codex and injects nothing for opencode', () => {
  const base = { OPENAI_API_KEY: 'sk-o', HOME: '/h' } as NodeJS.ProcessEnv;
  const codex = subscriptionChildEnv(base, 'codex', { CODEX_HOME: '/ch' });
  expect(codex.CODEX_HOME).toBe('/ch');
  expect(codex.OPENAI_API_KEY).toBeUndefined();
  const open = subscriptionChildEnv({ OPENCODE_API_KEY: 'k' } as NodeJS.ProcessEnv, 'opencode', {});
  expect(open.OPENCODE_API_KEY).toBeUndefined();
});

// --- parseSubscriptionSpecies ----------------------------------------------
it('parseSubscriptionSpecies returns empty for unset/blank env', () => {
  expect(parseSubscriptionSpecies({})).toEqual({ species: [], refused: [] });
  expect(parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: '' })).toEqual({ species: [], refused: [] });
  expect(parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: ' , ' })).toEqual({ species: [], refused: [] });
});

it('parseSubscriptionSpecies accepts the flat runtimes case-insensitively and dedupes by key', () => {
  const r = parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: 'CLAUDE, claude ,codex,CODEX' });
  expect(r.refused).toEqual([]);
  expect(r.species.map((s) => s.key)).toEqual(['claude', 'codex']);
  expect(r.species[0]).toMatchObject({ name: 'claude', runtime: 'claude', key: 'claude' });
  expect(r.species[1].runtime).toBe('codex');
});

it('parseSubscriptionSpecies refuses unknown values without running them', () => {
  const r = parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: 'gpt-5,claude' });
  expect(r.refused).toEqual(['gpt-5']);
  expect(r.species.map((s) => s.key)).toEqual(['claude']);
});

it('parseSubscriptionSpecies only accepts opencode-free:<model> when the model ends in -free', () => {
  const ok = parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: 'opencode-free:deepseek-v4.1-flash-free' });
  expect(ok.refused).toEqual([]);
  expect(ok.species).toHaveLength(1);
  expect(ok.species[0]).toEqual({
    name: 'opencode-free:deepseek-v4.1-flash-free',
    runtime: 'opencode',
    model: 'opencode/deepseek-v4.1-flash-free',
    key: 'opencode@opencode/deepseek-v4.1-flash-free',
    freeTier: true,
  });
  // a non-free model is refused
  const bad = parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: 'opencode-free:gpt-5' });
  expect(bad.species).toEqual([]);
  expect(bad.refused).toEqual(['opencode-free:gpt-5']);
  // empty model after prefix is refused
  const empty = parseSubscriptionSpecies({ SUBSCRIPTION_GYM_SPECIES: 'opencode-free:' });
  expect(empty.species).toEqual([]);
  expect(empty.refused).toEqual(['opencode-free:']);
});

it('subscriptionGymSpecies returns only the accepted species list', () => {
  expect(subscriptionGymSpecies({ SUBSCRIPTION_GYM_SPECIES: 'claude,codex' })).toHaveLength(2);
  expect(subscriptionGymSpecies({})).toEqual([]);
});

// --- numeric defaults ------------------------------------------------------
it('subscriptionGymMaxPerDay defaults to 5 and honours valid overrides, falling back on garbage', () => {
  expect(subscriptionGymMaxPerDay({})).toBe(5);
  expect(subscriptionGymMaxPerDay({ SUBSCRIPTION_GYM_MAX_PER_DAY: '3' })).toBe(3);
  expect(subscriptionGymMaxPerDay({ SUBSCRIPTION_GYM_MAX_PER_DAY: 'not-a-number' })).toBe(5);
  expect(subscriptionGymMaxPerDay({ SUBSCRIPTION_GYM_MAX_PER_DAY: '' })).toBe(5);
});

it('subscriptionLimitBackoffMs defaults to 5 h and honours a valid override', () => {
  expect(subscriptionLimitBackoffMs({})).toBe(5 * 3_600_000);
  expect(subscriptionLimitBackoffMs({ SUBSCRIPTION_GYM_LIMIT_BACKOFF_MS: '1800000' })).toBe(1_800_000);
  expect(subscriptionLimitBackoffMs({ SUBSCRIPTION_GYM_LIMIT_BACKOFF_MS: 'x' })).toBe(5 * 3_600_000);
});

// --- codexAuthFile ---------------------------------------------------------
it('codexAuthFile resolves under CODEX_HOME, else $HOME/.codex', () => {
  expect(codexAuthFile({ CODEX_HOME: '/custom/codex' } as NodeJS.ProcessEnv)).toBe(path.join('/custom/codex', 'auth.json'));
  expect(codexAuthFile({ HOME: '/home/u' } as NodeJS.ProcessEnv)).toBe(path.join('/home/u', '.codex', 'auth.json'));
  // CODEX_HOME wins over HOME
  expect(codexAuthFile({ CODEX_HOME: '/c', HOME: '/h' } as NodeJS.ProcessEnv)).toBe(path.join('/c', 'auth.json'));
});

// --- subscriptionAuthPresent -----------------------------------------------
it('subscriptionAuthPresent is always true for opencode (free tier needs no login)', () => {
  expect(subscriptionAuthPresent('opencode', {})).toBe(true);
});

it('subscriptionAuthPresent for claude requires a non-blank OAuth token', () => {
  expect(subscriptionAuthPresent('claude', { CLAUDE_CODE_OAUTH_TOKEN: 'tok' })).toBe(true);
  expect(subscriptionAuthPresent('claude', { CLAUDE_CODE_OAUTH_TOKEN: '   ' })).toBe(false);
  expect(subscriptionAuthPresent('claude', {})).toBe(false);
});

it('subscriptionAuthPresent for codex requires tokens and rejects an API-key login or missing file', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-auth-'));
  try {
    // valid ChatGPT login: has tokens, no OPENAI_API_KEY
    fs.writeFileSync(path.join(dir, 'auth.json'), JSON.stringify({ tokens: { id_token: 'x' } }));
    expect(subscriptionAuthPresent('codex', { CODEX_HOME: dir } as NodeJS.ProcessEnv)).toBe(true);
    // API-key login counts as missing
    fs.writeFileSync(path.join(dir, 'auth.json'), JSON.stringify({ OPENAI_API_KEY: 'sk-o', tokens: {} }));
    expect(subscriptionAuthPresent('codex', { CODEX_HOME: dir } as NodeJS.ProcessEnv)).toBe(false);
    // no tokens object → missing
    fs.writeFileSync(path.join(dir, 'auth.json'), JSON.stringify({}));
    expect(subscriptionAuthPresent('codex', { CODEX_HOME: dir } as NodeJS.ProcessEnv)).toBe(false);
    // malformed json → missing (fail-soft)
    fs.writeFileSync(path.join(dir, 'auth.json'), '{not-json');
    expect(subscriptionAuthPresent('codex', { CODEX_HOME: dir } as NodeJS.ProcessEnv)).toBe(false);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
  // file absent entirely → missing
  const empty = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-none-'));
  try {
    expect(subscriptionAuthPresent('codex', { CODEX_HOME: empty } as NodeJS.ProcessEnv)).toBe(false);
  } finally {
    fs.rmSync(empty, { recursive: true, force: true });
  }
});

// --- isSubscriptionLimit ---------------------------------------------------
it('isSubscriptionLimit never fires for a successful run even if the text mentions limits', () => {
  expect(isSubscriptionLimit(0, '', 'rate limit reached')).toBe(false);
  expect(isSubscriptionLimit(0, 'you hit your limit', '')).toBe(false);
});

it('isSubscriptionLimit detects limit phrasing in stderr and in the stdout tail on failed runs', () => {
  expect(isSubscriptionLimit(1, '', 'FreeUsageLimitError: free usage exceeded')).toBe(true);
  expect(isSubscriptionLimit(2, '', 'HTTP 429 too many requests')).toBe(true);
  expect(isSubscriptionLimit(3, '', 'quota exceeded')).toBe(true);
  expect(isSubscriptionLimit(4, '', 'usage_limit_reached')).toBe(true);
  // matched from the last 4000 chars of stdout
  const pad = 'x'.repeat(5_000);
  expect(isSubscriptionLimit(5, `${pad}hit your limit`, '')).toBe(true);
  // no match → false
  expect(isSubscriptionLimit(6, '', 'some unrelated error output')).toBe(false);
  expect(isSubscriptionLimit(7, 'all good here', 'nothing to see')).toBe(false);
});

// --- inLimitBackoff --------------------------------------------------------
it('inLimitBackoff is true only for a LIMIT_HIT within the backoff window for that species key', () => {
  const db = makeDb();
  const now = Date.parse('2026-10-18T12:00:00Z');
  const defaultWindowMs = 5 * 3_600_000;
  insertRun(db, 'a', 'claude', 1, new Date(now - 1_000).toISOString(), { gym_result: { reason: LIMIT_HIT } });
  expect(inLimitBackoff(db, 'claude', now)).toBe(true);
  // outside the window (older than 5 h) → false
  const db2 = makeDb();
  insertRun(db2, 'b', 'claude', 1, new Date(now - (defaultWindowMs + 1_000)).toISOString(), { gym_result: { reason: LIMIT_HIT } });
  expect(inLimitBackoff(db2, 'claude', now)).toBe(false);
  // different reason → not a limit hit
  const db3 = makeDb();
  insertRun(db3, 'c', 'claude', 1, new Date(now - 1_000).toISOString(), { gym_result: { reason: AUTH_MISSING } });
  expect(inLimitBackoff(db3, 'claude', now)).toBe(false);
  // different species key → false
  expect(inLimitBackoff(db, 'codex', now)).toBe(false);
});

// --- subscriptionAttemptsToday --------------------------------------------
it('returns 0 when no matching rows exist', () => {
  const db = makeDb();
  expect(subscriptionAttemptsToday(db, 'claude')).toBe(0);
});

it('counts only rows within the 24 h window for the given species key', () => {
  const db = makeDb();
  const now = Date.parse('2026-10-18T12:00:00Z');
  insertRun(db, 'r1', 'claude', 1, new Date(now - 3 * 3_600_000).toISOString());
  insertRun(db, 'r2', 'claude', 1, new Date(now - 30 * 3_600_000).toISOString());
  expect(subscriptionAttemptsToday(db, 'claude', now)).toBe(1);
});

it('excludes rows where gym.subscription is not 1 and rows with a different species key', () => {
  const db = makeDb();
  const now = Date.parse('2026-10-18T12:00:00Z');
  insertRun(db, 'r1', 'codex', 1, new Date(now - 1_000).toISOString());
  insertRun(db, 'r2', 'codex', 0, new Date(now - 2_000).toISOString());
  insertRun(db, 'r3', 'opencode@opencode/deepseek-v4.1-flash-free', 1, new Date(now - 3_000).toISOString());
  expect(subscriptionAttemptsToday(db, 'codex', now)).toBe(1);
  expect(subscriptionAttemptsToday(db, 'opencode@opencode/deepseek-v4.1-flash-free', now)).toBe(1);
  expect(subscriptionAttemptsToday(db, 'claude', now)).toBe(0);
});

it('respects the custom now parameter for window boundaries (inclusive start)', () => {
  const db = makeDb();
  insertRun(db, 'r1', 'claude', 1, '2026-10-17T00:00:00.000Z');
  // now = 2026-10-17T12:00 → window starts 2026-10-16T12:00 → inside
  expect(subscriptionAttemptsToday(db, 'claude', Date.parse('2026-10-17T12:00:00Z'))).toBe(1);
  // now = 2026-10-18T12:00 → window starts 2026-10-17T12:00 → outside
  expect(subscriptionAttemptsToday(db, 'claude', Date.parse('2026-10-18T12:00:00Z'))).toBe(0);
});

// --- subscriptionGymEvidence -----------------------------------------------
it('subscriptionGymEvidence reports structure, enabled/refused species and insufficient stats on an empty window', () => {
  const db = makeDb();
  const env = { SUBSCRIPTION_GYM_SPECIES: 'claude,gpt-5' } as NodeJS.ProcessEnv;
  const ev = subscriptionGymEvidence(db, '2026-01-01T00:00:00.000Z', env);
  expect(ev.enabled).toEqual(['claude']);
  expect(ev.refused).toEqual(['gpt-5']);
  expect(ev.max_per_day).toBe(5);
  expect(typeof ev.note).toBe('string');
  // claude + codex are always listed; free-tier species only when enabled
  const keys = ev.species.map((s) => s.key);
  expect(keys).toContain('claude');
  expect(keys).toContain('codex');
  const claude = ev.species.find((s) => s.key === 'claude')!;
  expect(claude.enabled).toBe(true);
  expect(claude.cost_basis).toBe('flat_subscription');
  expect(claude.attempts).toBe(0);
  expect(claude.rate).toBeNull();
  expect(claude.ci).toBeNull();
  expect(claude.status).toBe('insufficient');
});

it('subscriptionGymEvidence computes rate and a Wilson CI once >= 10 attempts are scored', () => {
  const db = makeDb();
  const since = '2026-01-01T00:00:00.000Z';
  for (let i = 0; i < 10; i++) {
    insertRun(db, `s${i}`, 'claude', 1, '2026-09-01T00:00:00.000Z', { gym_result: { status: 'success' } });
  }
  const ev = subscriptionGymEvidence(db, since, {} as NodeJS.ProcessEnv);
  const claude = ev.species.find((s) => s.key === 'claude')!;
  expect(claude.attempts).toBe(10);
  expect(claude.scored).toBe(10);
  expect(claude.successes).toBe(10);
  expect(claude.rate).toBe(1);
  expect(claude.status).toBe('ok');
  expect(Array.isArray(claude.ci)).toBe(true);
  if (Array.isArray(claude.ci)) {
    expect(claude.ci).toHaveLength(2);
    expect(claude.ci[0]).toBeGreaterThanOrEqual(0);
    expect(claude.ci[1]).toBeLessThanOrEqual(1);
    expect(claude.ci[0]).toBeLessThan(claude.ci[1]);
  }
});

