  memory_holdout: { rules: { n: 0 }, holdout: { n: 0 } },
};

// minimal signature factory — recurrence only reads `.signature`
const sig = (s: string): FailureSignature => ({ signature: s, key: '', lane: '', gate: null, error_class: null });
const unit = (at: string, lane: string, failed: boolean, signature: FailureSignature | null): FailureUnit => ({ at, lane, failed, signature });

const insertOutcome = (db: Database.Database, id: string, skill: string, success: number, refs: string[], domain = 'production', task = `run-${id}`, at = now) =>
  db.prepare(`INSERT INTO skill_outcomes (id, skill_id, success, domain, task_id, evidence_refs_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)`)
    .run(id, skill, success, domain, task, JSON.stringify(refs), at);

let db: Database.Database;
beforeEach(() => { db = createTestDb(); });
afterEach(() => { db.close(); });

describe('normaliseErrorClass', () => {
  it('returns null for non-string and blank input', () => {
    expect(normaliseErrorClass(null)).toBeNull();
    expect(normaliseErrorClass(undefined as unknown as string)).toBeNull();
    expect(normaliseErrorClass(42 as unknown as string)).toBeNull();
    expect(normaliseErrorClass('')).toBeNull();
    expect(normaliseErrorClass('   ')).toBeNull();
  });

  it('lowercases and strips numbers into <n>', () => {
    expect(normaliseErrorClass('Timeout after 30s at /app/x.ts')).toBe('timeout after <n>s at <path>');
  });

  it('replaces urls with <url>', () => {
    expect(normaliseErrorClass('see https://example.com/a/b?c=1 for details')).toBe('see <url> for details');
  });

  it('replaces uuids with <id>', () => {
    expect(normaliseErrorClass('failed id 123e4567-e89b-12d3-a456-426614174000 done')).toBe('failed id <id> done');
  });

  it('collapses whitespace to single spaces', () => {
    expect(normaliseErrorClass('a\t b \n c')).toBe('a b c');
  });

  it('truncates the normalised string to 160 chars', () => {
    const out = normaliseErrorClass('word '.repeat(50));
    expect(out).not.toBeNull();
    expect(out!.length).toBe(160);
  });
});

describe('failureSignature', () => {
