  });

  it('detects a repeat within the same lane and reports ok at lowered thresholds', () => {
    const units = [
      unit('2026-01-05T00:00:00Z', 'L', true, sig('A')),
      unit('2026-01-06T00:00:00Z', 'L', true, sig('B')),
      unit('2026-01-07T00:00:00Z', 'L', true, sig('A')), // A already seen in L -> repeat
    ];
    const m = failureRecurrence(units, { failures: 2, signatures: 2 });
    expect(m.status).toBe('ok');
    expect(m.value).toBe(0.5); // repeats/exposed = 1/2
    expect(m.ci).toEqual(wilson(1, 2));
    expect(m.n).toBe(2); // exposed
