      unit('2026-01-05T02:00:00Z', 'L', true, sig('A')), // repeat of A
      unit('2026-01-05T03:00:00Z', 'L', true, null), // missing
      unit('2026-01-05T04:00:00Z', 'L', true, sig('B')),
      unit('2026-01-05T05:00:00Z', 'L', true, null), // missing
    ];
    const m = failureRecurrence(units, { failures: 2, signatures: 2 });
    expect(m.status).toBe('INSUFFICIENT_EVIDENCE'); // 3/6 = 50% > 20% missing
    expect(m.value).toBeNull();
    expect(m.detail.failures).toBe(6);
