describe('readTargetExcerpt', () => {
  let tmpDir: string;

  beforeAll(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'review-excerpt-'));
  });

  afterAll(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('reads a small text file and returns a formatted excerpt with line count', () => {
    fs.writeFileSync(path.join(tmpDir, 'hello.txt'), 'line1\nline2');
    const result = readTargetExcerpt('hello.txt', tmpDir);
    expect(result).not.toBeNull();
    expect(result!).toContain('Target file hello.txt');
    expect(result!).toContain('(2 lines)');
    expect(result!).toContain('line1');
    expect(result!).toContain('line2');
  });

  it('returns null for path traversal attempts', () => {
    expect(readTargetExcerpt('../etc/passwd', tmpDir)).toBeNull();
    expect(readTargetExcerpt('../../secret', tmpDir)).toBeNull();
    expect(readTargetExcerpt('a/../b', tmpDir)).toBeNull();
  });

  it('returns null for absolute paths', () => {
    expect(readTargetExcerpt('/etc/passwd', tmpDir)).toBeNull();
  });

  it('returns null for sensitive file names', () => {
    expect(readTargetExcerpt('.env', tmpDir)).toBeNull();
    expect(readTargetExcerpt('.git/config', tmpDir)).toBeNull();
    expect(readTargetExcerpt('node_modules/pkg/index.js', tmpDir)).toBeNull();
    expect(readTargetExcerpt('secrets/credentials.json', tmpDir)).toBeNull();
    expect(readTargetExcerpt('key.pem', tmpDir)).toBeNull();
    expect(readTargetExcerpt('id_rsa', tmpDir)).toBeNull();
    expect(readTargetExcerpt('api.key', tmpDir)).toBeNull();
  });

  it('returns null for non-existent files', () => {
    expect(readTargetExcerpt('nonexistent.txt', tmpDir)).toBeNull();
  });

  it('returns null when target is a directory', () => {
    fs.mkdirSync(path.join(tmpDir, 'subdir'));
    expect(readTargetExcerpt('subdir', tmpDir)).toBeNull();
  });

  it('returns null for invalid target types (number, null, undefined, object)', () => {
    expect(readTargetExcerpt(42, tmpDir)).toBeNull();
    expect(readTargetExcerpt(null, tmpDir)).toBeNull();
    expect(readTargetExcerpt(undefined, tmpDir)).toBeNull();
    expect(readTargetExcerpt({ path: 'x' }, tmpDir)).toBeNull();
  });

  it('truncates content longer than 6000 characters and notes the truncation', () => {
    const bigContent = 'a'.repeat(7000);
    fs.writeFileSync(path.join(tmpDir, 'big.txt'), bigContent);
    const result = readTargetExcerpt('big.txt', tmpDir);
    expect(result).not.toBeNull();
    expect(result!).toContain('first 6000 characters');
    // The returned string should contain at most 6000 chars of file content plus header
    expect((result! as string).length).toBeLessThan(6500);
  });

  it('does not include the full content when truncated', () => {
    const marker = 'UNIQUE_MARKER_AT_END';
    const content = 'b'.repeat(6500) + '\n' + marker;
    fs.writeFileSync(path.join(tmpDir, 'trunc.txt'), content);
    const result = readTargetExcerpt('trunc.txt', tmpDir);
    expect(result).not.toBeNull();
    expect(result!).not.toContain(marker);
  });
});

