  });
});

// ─── probability (2PL) ──────────────────────────────────────────────────────────
describe('probability', () => {
  it('returns exactly 0.5 when theta equals b (regardless of a)', () => {
    expect(probability(3, 2, 2)).toBeCloseTo(0.5, 12);
    expect(probability(-1, -4, -4)).toBeCloseTo(0.5, 12);
  });

  it('computes sigmoid(a*(theta-b)) correctly for positive a, theta > b', () => {
    // sigmoid(2*(3-1)) = sigmoid(4) ≈ 0.98201379
    expect(probability(2, 1, 3)).toBeCloseTo(0.98201379, 6);
  });

  it('computes sigmoid(a*(theta-b)) correctly for a=1, b=0, theta=1', () => {
    // sigmoid(1) ≈ 0.73105858
    expect(probability(1, 0, 1)).toBeCloseTo(0.73105858, 6);
  });

  it('gives < 0.5 when theta < b and a > 0 (not inverted)', () => {
    // sigmoid(1*(-1)) = sigmoid(-1) ≈ 0.26894142
    expect(probability(1, 0, -1)).toBeCloseTo(0.26894142, 6);
  });

  it('handles negative discrimination (a < 0)', () => {
    // sigmoid(-1*(1-0)) = sigmoid(-1) ≈ 0.26894142
    expect(probability(-1, 0, 1)).toBeCloseTo(0.26894142, 6);
  });

  it('returns 0.5 for any theta when a = 0', () => {
    expect(probability(0, 5, 3)).toBeCloseTo(0.5, 12);
  });

  it('is symmetric: p(a,b,t) + p(a,b, 2b-t) = 1', () => {
    const t = 1.7; const b = 0.3;
    expect(probability(2, b, t) + probability(2, b, 2 * b - t)).toBeCloseTo(1, 10);
  });
});

// ─── fisherInformation ──────────────────────────────────────────────────────────
describe('fisherInformation', () => {
  it('equals a²/4 at the item difficulty (theta = b)', () => {
    // a=2 → 4*0.25 = 1
    expect(fisherInformation(2, 0, 0)).toBeCloseTo(1, 10);
    // a=3 → 9*0.25 = 2.25
    expect(fisherInformation(3, 1, 1)).toBeCloseTo(2.25, 10);
    // a=1 → 0.25
    expect(fisherInformation(1, -2, -2)).toBeCloseTo(0.25, 10);
  });

  it('uses a squared (not linear) in the formula', () => {
    // At theta=b: FI = a²·p(1-p) = a²·0.25. If bug used a instead of a²:
    //   correct for a=2: 4*0.25=1; buggy would give 2*0.25=0.5
    expect(fisherInformation(2, 0, 0)).not.toBeCloseTo(0.5, 6);
    expect(fisherInformation(2, 0, 0)).toBeCloseTo(1, 6);
  });

  it('is non-negative for all inputs', () => {
    expect(fisherInformation(1, 0, 5)).toBeGreaterThanOrEqual(0);
    expect(fisherInformation(-2, 3, -7)).toBeGreaterThanOrEqual(0);
  });

  it('decreases as |theta - b| grows (for positive a)', () => {
    const atB = fisherInformation(2, 0, 0);
    const near = fisherInformation(2, 0, 0.5);
    const far = fisherInformation(2, 0, 2);
    expect(atB).toBeGreaterThan(near);
    expect(near).toBeGreaterThan(far);
  });

  it('matches manual computation away from the peak', () => {
    // p = sigmoid(2*(1-0)) = sigmoid(2) ≈ 0.88079708
    // FI = 4 * 0.88079708 * 0.11920292 ≈ 0.41997
    expect(fisherInformation(2, 0, 1)).toBeCloseTo(0.41997, 4);
  });
});

// ─── fitIrt ─────────────────────────────────────────────────────────────────────
describe('fitIrt', () => {
  it('returns empty items and abilities for no observations', () => {
    const fit = fitIrt([]);
    expect(fit.items).toEqual([]);
    expect(fit.abilities).toEqual({});
  });

  it('flags a single observation as insufficient (n < 2)', () => {
    const obs: Observation[] = [{ item: 'X', respondent: 'R', y: 1 }];
    const fit = fitIrt(obs);
    expect(fit.items).toHaveLength(1);
    expect(fit.items[0].key).toBe('X');
    expect(fit.items[0].n).toBe(1);
    expect(fit.items[0].flag).toBe('insufficient');
  });

  it('flags an item with all successes (n ≥ 2) as non_discriminating', () => {
    const obs: Observation[] = [
      { item: 'A', respondent: 'R1', y: 1 },
      { item: 'A', respondent: 'R1', y: 1 },
      { item: 'A', respondent: 'R2', y: 1 },
    ];
    const fit = fitIrt(obs);
    const itemA = fit.items.find((i) => i.key === 'A')!;
    expect(itemA.n).toBe(3);
    expect(itemA.pass_rate).toBeCloseTo(1, 4);
    expect(itemA.flag).toBe('non_discriminating');
  });

  it('flags an item with all failures (n ≥ 2) as non_discriminating', () => {
    const obs: Observation[] = [
      { item: 'B', respondent: 'R1', y: 0 },
      { item: 'B', respondent: 'R2', y: 0 },
    ];
    const fit = fitIrt(obs);
    const itemB = fit.items.find((i) => i.key === 'B')!;
    expect(itemB.n).toBe(2);
    expect(itemB.pass_rate).toBeCloseTo(0, 4);
    expect(itemB.flag).toBe('non_discriminating');
  });

  it('computes correct n and pass_rate for mixed outcomes', () => {
    const obs: Observation[] = [
      { item: 'T', respondent: 'P', y: 1 },
      { item: 'T', respondent: 'P', y: 0 },
      { item: 'T', respondent: 'Q', y: 1 },
      { item: 'T', respondent: 'Q', y: 1 },
    ];
    const fit = fitIrt(obs);
    const t = fit.items.find((i) => i.key === 'T')!;
    expect(t.n).toBe(4);
    expect(t.pass_rate).toBeCloseTo(0.75, 4); // 3/4
  });

  it('produces one ability entry per unique respondent', () => {
    const obs: Observation[] = [
      { item: 'A', respondent: 'R1', y: 1 },
      { item: 'A', respondent: 'R2', y: 0 },
      { item: 'B', respondent: 'R3', y: 1 },
    ];
    const fit = fitIrt(obs);
    expect(Object.keys(fit.abilities).sort()).toEqual(['R1', 'R2', 'R3']);
  });

  it('is deterministic (same input → same output)', () => {
    const obs: Observation[] = [
      { item: 'X', respondent: 'A', y: 1 },
      { item: 'X', respondent: 'B', y: 0 },
      { item: 'Y', respondent: 'A', y: 0 },
      { item: 'Y', respondent: 'B', y: 1 },
    ];
    const f1 = fitIrt(obs);
    const f2 = fitIrt(obs);
    expect(f1.items).toEqual(f2.items);
    expect(f1.abilities).toEqual(f2.abilities);
  });

  it('gives a higher-ability estimate to the respondent who passes more items', () => {
    // R_good passes both; R_bad fails both.
    const obs: Observation[] = [
      { item: 'I1', respondent: 'R_good', y: 1 },
      { item: 'I1', respondent: 'R_bad', y: 0 },
      { item: 'I2', respondent: 'R_good', y: 1 },
      { item: 'I2', respondent: 'R_bad', y: 0 },
    ];
    const fit = fitIrt(obs, 800);
    expect(fit.abilities['R_good']).toBeGreaterThan(fit.abilities['R_bad']);
  });

  it('sorts items by key alphabetically in output', () => {
    const obs: Observation[] = [
      { item: 'zeta', respondent: 'R', y: 1 },
      { item: 'alpha', respondent: 'R', y: 0 },
      { item: 'mid', respondent: 'R', y: 1 },
    ];
    const fit = fitIrt(obs);
    expect(fit.items.map((i) => i.key)).toEqual(['alpha', 'mid', 'zeta']);
  });
});

// ─── pickInformativeItems ──────────────────────────────────────────────────────
describe('pickInformativeItems', () => {
  const mkItem = (key: string, a: number, b: number, flag: IrtItem['flag'] = 'ok'): IrtItem => ({
    key, n: 20, pass_rate: 0.5, a, b, flag,
  });

  it('returns only items with flag "ok"', () => {
    const items = [mkItem('good', 2, 0), mkItem('bad', 3, 0, 'non_discriminating')];
    const picked = pickInformativeItems(items, 0, 10);
    expect(picked.map((p) => p.key)).toEqual(['good']);
  });

  it('excludes keys in the exclude set even if they are ok and high-info', () => {
    const items = [mkItem('a', 5, 0), mkItem('b', 4, 0)];
    const picked = pickInformativeItems(items, 0, 10, ['a']);
    expect(picked.map((p) => p.key)).toEqual(['b']);
  });

  it('sorts by Fisher information descending at the given theta', () => {
    // At theta=0, b=0: FI = a²/4 → higher a wins.
    const items = [mkItem('low', 0.5, 0), mkItem('high', 3, 0), mkItem('mid', 1.5, 0)];
    const picked = pickInformativeItems(items, 0, 3);
    expect(picked.map((p) => p.key)).toEqual(['high', 'mid', 'low']);
  });

  it('breaks ties by key alphabetically (ascending)', () => {
    const items = [mkItem('zeta', 2, 0), mkItem('alpha', 2, 0), mkItem('mid', 2, 0)];
    const picked = pickInformativeItems(items, 0, 3);
    expect(picked.map((p) => p.key)).toEqual(['alpha', 'mid', 'zeta']);
  });

  it('returns at most k items', () => {
    const items = [mkItem('a', 1, 0), mkItem('b', 2, 0), mkItem('c', 3, 0)];
    expect(pickInformativeItems(items, 0, 2)).toHaveLength(2);
    expect(pickInformativeItems(items, 0, 1)).toHaveLength(1);
  });

  it('returns empty array when k is 0 or negative', () => {
    const items = [mkItem('a', 1, 0)];
    expect(pickInformativeItems(items, 0, 0)).toEqual([]);
    expect(pickInformativeItems(items, 0, -5)).toEqual([]);
  });

  it('respects theta in the Fisher information calculation (not just a)', () => {
    // Item A: a=2, b=0 → FI at θ=0 is 1; at θ=3 is much lower.
    // Item B: a=1, b=3 → FI at θ=3 is 0.25; at θ=0 is very low.
    // At θ=3, B should rank above A even though A has larger a.
    const A = mkItem('A', 2, 0);
    const B = mkItem('B', 1, 3);
    const pickedAt3 = pickInformativeItems([A, B], 3, 2);
    expect(pickedAt3[0].key).toBe('B');
  });
});

// ─── irtSelectionEnabled ────────────────────────────────────────────────────────
describe('irtSelectionEnabled', () => {
  it('returns true only for the exact string "true"', () => {
    expect(irtSelectionEnabled({ GYM_IRT_SELECTION: 'true' })).toBe(true);
  });
  it('returns false for other values', () => {
    expect(irtSelectionEnabled({ GYM_IRT_SELECTION: 'false' })).toBe(false);
    expect(irtSelectionEnabled({ GYM_IRT_SELECTION: '' })).toBe(false);
    expect(irtSelectionEnabled({})).toBe(false);
    expect(irtSelectionEnabled({ GYM_IRT_SELECTION: 'TRUE' })).toBe(false);
    expect(irtSelectionEnabled({ GYM_IRT_SELECTION: '1' })).toBe(false);
  });
});

// ─── gymObservations (real in-memory DB) ───────────────────────────────────────
describe('gymObservations', () => {
  const makeDb = (): Database.Database => {
    const db = new Database(':memory:');
    db.exec(`CREATE TABLE loop_runs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      loop_name TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      metadata TEXT
    )`);
    return db;
  };

  const insertRun = (db: Database.Database, meta: Record<string, unknown>, createdAt = '2025-06-01T00:00:00') => {
    db.prepare('INSERT INTO loop_runs (loop_name, created_at, metadata) VALUES (?, ?, ?)').run(
      'evolution-gym', createdAt, JSON.stringify(meta),
    );
  };

  it('returns empty array for a database with no matching rows', () => {
    const db = makeDb();
    expect(gymObservations(db)).toEqual([]);
  });

  it('extracts item, respondent key, and y from valid gym runs', () => {
    const db = makeDb();
    insertRun(db, { gym: { commit: 'abc123', species: 'sp1', genome: 'g1' }, gym_result: { status: 'success' } });
    insertRun(db, { gym: { commit: 'def456', species: 'sp1', genome: null }, gym_result: { status: 'failure' } });

    const obs = gymObservations(db);
    expect(obs).toHaveLength(2);
    expect(obs[0]).toEqual({ item: 'abc123', respondent: 'sp1|g1', y: 1 });
    expect(obs[1]).toEqual({ item: 'def456', respondent: 'sp1|baseline', y: 0 });
  });

  it('excludes canary and probe runs', () => {
    const db = makeDb();
    insertRun(db, { gym: { commit: 'c1', species: 's', genome: 'g' }, gym_result: { status: 'success' }, canary: true });
    insertRun(db, { gym: { commit: 'c2', species: 's', genome: 'g' }, gym_result: { status: 'success' }, probe: true });
    // The metadata path is $.gym.canary / $.gym.probe per the SQL
    // Re-insert with correct nesting:
    const db2 = makeDb();
    insertRun(db2, { gym: { commit: 'c1', species: 's', genome: 'g', canary: true }, gym_result: { status: 'success' } });
    insertRun(db2, { gym: { commit: 'c2', species: 's', genome: 'g', probe: true }, gym_result: { status: 'success' } });
    expect(gymObservations(db2)).toEqual([]);
  });

  it('excludes rows from other loop names', () => {
    const db = makeDb();
    db.prepare("INSERT INTO loop_runs (loop_name, created_at, metadata) VALUES ('other-loop', '2025-06-01T00:00:00', ?)")
      .run(JSON.stringify({ gym: { commit: 'x', species: 's', genome: 'g' }, gym_result: { status: 'success' } }));
    expect(gymObservations(db)).toEqual([]);
  });

  it('respects the sinceIso filter', () => {
    const db = makeDb();
    insertRun(db, { gym: { commit: 'old', species: 's', genome: 'g' }, gym_result: { status: 'success' } }, '2024-01-01T00:00:00');
    insertRun(db, { gym: { commit: 'new', species: 's', genome: 'g' }, gym_result: { status: 'failure' } }, '2025-07-01T00:00:00');

    const all = gymObservations(db);
    expect(all).toHaveLength(2);

    const recent = gymObservations(db, '2025-01-01');
    expect(recent).toHaveLength(1);
    expect(recent[0].item).toBe('new');
  });

  it('excludes rows with missing gym.commit or gym.species', () => {
    const db = makeDb();
    insertRun(db, { gym: { species: 's', genome: 'g' }, gym_result: { status: 'success' } }); // no commit
    insertRun(db, { gym: { commit: 'c' }, gym_result: { status: 'success' } }); // no species
    expect(gymObservations(db)).toEqual([]);
  });
});

