// ─── flag gates ──────────────────────────────────────────────────────────────
it('flag gates read the exact env spellings', () => {
  expect(pushEnabled({ TELEGRAM_PUSH_ENABLED: 'true' })).toBe(true);
  expect(pushEnabled({ TELEGRAM_PUSH_ENABLED: 'false' })).toBe(false);
  expect(pushEnabled({})).toBe(false);
  // triage is a strict sub-flag of push: both must be on
  expect(triageEnabled({ TELEGRAM_TRIAGE_ENABLED: 'true' })).toBe(false);
  expect(triageEnabled({ TELEGRAM_PUSH_ENABLED: 'true', TELEGRAM_TRIAGE_ENABLED: 'true' })).toBe(true);
  expect(digestEnabled({ OPERATOR_DIGEST_ENABLED: 'true' })).toBe(true);
  expect(digestEnabled({ OPERATOR_DIGEST_ENABLED: '1' })).toBe(false);
  expect(digestEnabled({})).toBe(false);
});

it('OPERATOR_PUSH_FLAGS documents every switch and CALLBACK_DATA_MAX_BYTES is Telegram\'s limit', () => {
  for (const f of [
    'TELEGRAM_PUSH_ENABLED', 'TELEGRAM_PUSH_MAX_PER_HOUR', 'TELEGRAM_QUIET_HOURS',
    'TELEGRAM_TRIAGE_ENABLED', 'TELEGRAM_TRIAGE_MAX_PER_PUSH',
    'OPERATOR_DIGEST_ENABLED', 'OPERATOR_DIGEST_HOUR',
  ]) expect(OPERATOR_PUSH_FLAGS).toContain(f as never);
  expect(CALLBACK_DATA_MAX_BYTES).toBe(64);
});

// ─── inQuietHours: wrapping, non-wrapping, malformed, degenerate ─────────────
it('inQuietHours handles wrap-midnight, normal ranges, malformed and equal bounds', () => {
  const at = (h: number) => new Date(Date.UTC(2026, 9, 6, h));
  // wraps midnight: 22:00..06:59
  expect(inQuietHours('22-7', at(23))).toBe(true);
  expect(inQuietHours('22-7', at(6))).toBe(true);
  expect(inQuietHours('22-7', at(7))).toBe(false);
  expect(inQuietHours('22-7', at(8))).toBe(false);
  expect(inQuietHours('22-7', at(21))).toBe(false);
  // normal range 09:00..16:59
  expect(inQuietHours('9-17', at(10))).toBe(true);
  expect(inQuietHours('9-17', at(16))).toBe(true);
  expect(inQuietHours('9-17', at(17))).toBe(false);
  expect(inQuietHours('9-17', at(8))).toBe(false);
  // whitespace tolerated
  expect(inQuietHours(' 9 - 17 ', at(10))).toBe(true);
  // malformed / empty / undefined → no quiet hours
  expect(inQuietHours('', at(10))).toBe(false);
  expect(inQuietHours(undefined, at(10))).toBe(false);
  expect(inQuietHours('abc', at(10))).toBe(false);
  expect(inQuietHours('9-', at(10))).toBe(false);
  // equal bounds is a degenerate (empty) window, never quiet
  expect(inQuietHours('5-5', at(5))).toBe(false);
});

// ─── approvalMessage: structure, redaction, File vs Scope label ──────────────
it('approvalMessage renders the decision fields and labels scope without context', () => {
  const msg = approvalMessage({
    id: 'appr-1', title: 'Do the thing', risk_level: 'high', action_type: 'file_write',
