  expect(msg).toContain('Expires: 2026-10-07T00:00:00Z');
  expect(msg).toContain('Id: appr-1');
});

it('approvalMessage uses a File label when context supplies files and shows +N overflow', () => {
  const ctx = { lane: null, proposal: null, files: ['a.ts', 'b.ts', 'c.ts', 'd.ts', 'e.ts', 'f.ts'], run_id: null, role: null, why: null };
  const msg = approvalMessage({ id: 'appr-2', title: 't' }, ctx);
