it('approvalMessage redacts secrets out of the rendered text', () => {
  const token = `ghp_${'a'.repeat(36)}`;
  const msg = approvalMessage({ id: 'appr-4', title: `Deploy ${token}`, risk_level: 'low' });
  expect(msg).toContain('[REDACTED:GitHub PAT]');
  expect(msg).not.toContain(token);
});

// ─── triageMessages: ordering, button payloads, callback_data byte cap ───────
it('triageMessages lists unlabelled pre-screen first then memory, with one-tap payloads', () => {
  const inbox = {
    requeue: [],
    prescreen: { items: [
      { id: 'p1', title: 'T1', status: 'rejected', reason: 'r', verdict_at: '', label: null },
      { id: 'p2', title: 'T2', status: 'rejected', reason: 'r', verdict_at: '', label: 'ok' },
