  expect(msgs[1].key).toBe('triage:memory:m1');
  expect(msgs[1].buttons.map((b) => b.data)).toEqual(['mp:m1', 'mr:m1']);
});

it('triageMessages drops any message whose button payload exceeds the callback_data byte cap', () => {
  const longId = `x${'y'.repeat(70)}`; // pl:<id>:o far over 64 bytes
  const inbox = {
    requeue: [],
    prescreen: { items: [
      { id: 'ok', title: 'T', status: 'rejected', reason: 'r', verdict_at: '', label: null },
