describe('scanPackage', () => {
  function buildPkg(): string {
    const dir = mkdtempSync(path.join(tmpdir(), 'scs-'));
    writeFileSync(path.join(dir, 'package.json'), JSON.stringify({
      name: 'demo-pkg', version: '1.2.3', bin: { demo: 'bin/demo.js' },
      scripts: { preinstall: 'node pre.js', postinstall: 'echo hi' },
    }));
    mkdirSync(path.join(dir, 'bin'));
    writeFileSync(path.join(dir, 'bin', 'demo.js'), '#!/usr/bin/env node\nconsole.log(1);\n');
    writeFileSync(path.join(dir, 'index.js'), [
      "const cp = require('child_process');",
      "import http from 'http';",
      "eval('x');",
      "new Function('a','return a');",
      'const k = process.env.API_KEY;',
      "require('fs').writeFileSync(require('os').homedir() + '/f', 'x');",
      "fetch('https://evil.example.com/a');",
      '',
    ].join('\n'));
    // A real ELF binary (magic 0x7f454c46).
    writeFileSync(path.join(dir, 'native.so'), Buffer.from([0x7f, 0x45, 0x4c, 0x46, 0x02, 0x00, 0x00, 0x00]));
    // A symlink that must be listed but never followed.
    symlinkSync('target', path.join(dir, 'link'));
    // A nested dependency with its own lifecycle script.
    mkdirSync(path.join(dir, 'node_modules', 'dep'), { recursive: true });
    writeFileSync(path.join(dir, 'node_modules', 'dep', 'package.json'), JSON.stringify({ name: 'dep', version: '2.0.0', scripts: { install: 'node setup.js' } }));
    return dir;
  }

  it('produces a deterministic, self-consistent report for a crafted package', async () => {
    const dir = buildPkg();
    try {
      const r1 = await scanPackage(dir);
      const r2 = await scanPackage(dir);

      expect(r1.schema).toBe('shipped-code-scan/v1');
      expect(r1.package).toEqual({ name: 'demo-pkg', version: '1.2.3' });
      // Deterministic across runs.
      expect(r2.report_hash).toBe(r1.report_hash);
      // Self-consistent hash over the body (report_hash excluded).
      const { report_hash: _omit, ...body } = r1;
      expect(reportHash(body)).toBe(r1.report_hash);
      expect(r1.report_hash).toMatch(/^[0-9a-f]{64}$/);

      // Lifecycle scripts from the root package.json, in canonical order.
      expect(r1.lifecycle.map((l) => l.script)).toEqual(['preinstall', 'postinstall']);
      expect(r1.lifecycle.find((l) => l.script === 'postinstall')?.command).toBe('echo hi');

      // Nested dependency lifecycle captured with its path and identity.
      expect(r1.nested_lifecycle).toContainEqual({ package: 'dep@2.0.0', path: 'node_modules/dep', script: 'install', command: 'node setup.js' });

      // Declared bin normalized and present.
      expect(r1.bin).toContainEqual({ name: 'demo', path: 'bin/demo.js' });

      // ELF binary detected by magic bytes.
      expect(r1.binaries.some((b) => b.path === 'native.so' && b.format === 'elf')).toBe(true);

      // Symlink listed (not followed), target recorded.
      expect(r1.symlinks.some((s) => s.path === 'link' && s.target === 'target')).toBe(true);

      // Every regular file is hashed; big.js exists but was skipped for parsing.
      const paths = r1.files.map((f) => f.path);
      expect(paths).toContain('index.js');
      expect(paths).toContain('native.so');
      expect(r1.files.every((f) => typeof f.size === 'number' && (f.sha256 === null || /^[0-9a-f]{64}$/.test(f.sha256)))).toBe(true);
      expect(r1.js.parsed).toBeGreaterThanOrEqual(1); // index.js parsed successfully
      expect(r1.js.skipped).toEqual([]); // nothing skipped under default limits

      // Hosts extracted from URLs in scanned code.
      expect(r1.hosts).toContain('evil.example.com');

      // Findings: the parser must have caught each planted behaviour, attributed to index.js.
      const kinds = new Set(r1.findings.filter((f) => f.file === 'index.js').map((f) => f.kind));
      expect(kinds.has('eval')).toBe(true);
      expect(kinds.has('new_function')).toBe(true);
      expect(kinds.has('env_token_read')).toBe(true);
      expect(kinds.has('home_write')).toBe(true);
      expect(kinds.has('endpoint')).toBe(true);
      expect(kinds.has('module_import')).toBe(true);
      // Specific details for the sensitive reads/writes.
      expect(r1.findings.some((f) => f.kind === 'env_token_read' && f.detail === 'API_KEY')).toBe(true);
      expect(r1.findings.some((f) => f.kind === 'home_write' && f.detail === 'writeFileSync')).toBe(true);
      expect(r1.findings.some((f) => f.kind === 'endpoint' && /fetch https:\/\/evil\.example\.com/.test(f.detail))).toBe(true);
      // Network + process module imports classified by category.
      expect(r1.findings.some((f) => f.kind === 'module_import' && /^network:/.test(f.detail))).toBe(true);
      expect(r1.findings.some((f) => f.kind === 'module_import' && /^process:/.test(f.detail))).toBe(true);

      // Findings are deterministically sorted (file, line, kind, detail).
      const fs = r1.findings;
      for (let i = 1; i < fs.length; i++) {
        const a = fs[i - 1], b = fs[i];
        expect(a.file <= b.file).toBe(true);
      }
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('skips a JS file larger than maxParseBytes as too_large', async () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'scs-big-'));
    try {
      writeFileSync(path.join(dir, 'package.json'), JSON.stringify({ name: 'p', version: '1.0.0' }));
      writeFileSync(path.join(dir, 'big.js'), 'x'.repeat(500));
      const r = await scanPackage(dir, { maxParseBytes: 100 });
      expect(r.js.skipped).toContainEqual({ path: 'big.js', reason: 'too_large' });
      expect(r.js.parsed).toBe(0);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('records js_parser_unavailable when no parser is supplied', async () => {
    const dir = buildPkg();
    try {
      const r = await scanPackage(dir, { maxParseBytes: 100, parser: null });
      expect(r.parser).toBeNull();
      expect(r.truncated).toContain('js_parser_unavailable');
      // Without a parser nothing is parsed and no JS findings exist.
      expect(r.js.parsed).toBe(0);
      expect(r.findings.filter((f) => f.file.endsWith('.js'))).toEqual([]);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('refuses to follow a symlinked root and rejects non-directories', async () => {
    const real = mkdtempSync(path.join(tmpdir(), 'scs-real-'));
    const link = path.join(real, 'link-root');
    symlinkSync('.', link);
    const file = path.join(real, 'afile.txt');
    writeFileSync(file, 'x');
    try {
      await expect(scanPackage(link)).rejects.toThrow(/symlink/);
      await expect(scanPackage(file)).rejects.toThrow(/not a directory/);
    } finally {
      rmSync(real, { recursive: true, force: true });
    }
  });
});

