it('ste001Evidence correctly aggregates per-arm statistics', () => {
  // Arm 0: 4 outcomes, 3 verified, 1 out_of_scope, tokens [100,200,300,400]
  // Arm 1: 2 outcomes, 1 verified, 0 out_of_scope, tokens [50,150]
  const rows: EvidenceRow[] = [
    { arm: '0', success: 1, tokens: 100, out_of_scope: 0 },
    { arm: '0', success: 1, tokens: 200, out_of_scope: 1 },
    { arm: '0', success: 1, tokens: 300, out_of_scope: 0 },
    { arm: '0', success: 0, tokens: 400, out_of_scope: 0 },
    { arm: '1', success: 1, tokens: 50, out_of_scope: 0 },
    { arm: '1', success: 0, tokens: 150, out_of_scope: 0 },
  ];
  const result = ste001Evidence(makeEvidenceDb(rows), '2025-01-01T00:00:00Z', {});

  // Arm 0
  expect(result.arms['0'].n).toBe(4);
  expect(result.arms['0'].verified).toBe(3);
  expect(result.arms['0'].verified_rate).toBe(0.75);
  expect(result.arms['0'].out_of_scope).toBe(1);
  expect(result.arms['0'].out_of_scope_share).toBe(0.25);
  expect(result.arms['0'].tokens_mean).toBe(250);
  // CI should be a [number, number] tuple within [0,1]
  expect(Array.isArray(result.arms['0'].ci)).toBe(true);
  if (Array.isArray(result.arms['0'].ci)) {
    expect(result.arms['0'].ci[0]).toBeGreaterThanOrEqual(0);
    expect(result.arms['0'].ci[1]).toBeLessThanOrEqual(1);
    expect(result.arms['0'].ci[0]).toBeLessThan(result.arms['0'].ci[1]);
    // The point estimate must lie inside the interval
    expect(result.arms['0'].ci[0]).toBeLessThanOrEqual(0.75);
    expect(result.arms['0'].ci[1]).toBeGreaterThanOrEqual(0.75);
  }

  // Arm 1
  expect(result.arms['1'].n).toBe(2);
  expect(result.arms['1'].verified).toBe(1);
  expect(result.arms['1'].verified_rate).toBe(0.5);
  expect(result.arms['1'].out_of_scope).toBe(0);
  expect(result.arms['1'].out_of_scope_share).toBe(0);
  expect(result.arms['1'].tokens_mean).toBe(100);

  // diff = arm1.rate - arm0.rate = 0.5 - 0.75 = -0.25
  expect(result.diff).toBe(-0.25);
  expect(result.status).toBe('collecting');
});

it('ste001Evidence computes diff as arm1 minus arm0 (direction matters)', () => {
  // Arm 0: 1 outcome, 0 verified → rate 0
  // Arm 1: 1 outcome, 1 verified → rate 1
  const rows: EvidenceRow[] = [
    { arm: '0', success: 0, tokens: 10, out_of_scope: 0 },
    { arm: '1', success: 1, tokens: 20, out_of_scope: 0 },
  ];
  const result = ste001Evidence(makeEvidenceDb(rows), '2025-01-01T00:00:00Z', {});
  // diff should be +1.0 (arm1 better than arm0)
  expect(result.diff).toBe(1);
});

it('ste001Evidence reports analysable status when both arms reach the target', () => {
  // Generate exactly STE_001_TARGET_PER_ARM rows per arm
  const n = STE_001_TARGET_PER_ARM;
  const rows: EvidenceRow[] = [];
  for (let i = 0; i < n; i++) {
    rows.push({ arm: '0', success: i % 2 === 0 ? 1 : 0, tokens: 100, out_of_scope: 0 });
    rows.push({ arm: '1', success: i % 3 === 0 ? 1 : 0, tokens: 200, out_of_scope: 0 });
  }
  const result = ste001Evidence(makeEvidenceDb(rows), '2025-01-01T00:00:00Z', {});
  expect(result.arms['0'].n).toBe(n);
  expect(result.arms['1'].n).toBe(n);
  expect(result.status).toBe('analysable');
});

it('ste001Evidence stays collecting when only one arm reaches the target', () => {
  const n = STE_001_TARGET_PER_ARM;
  const rows: EvidenceRow[] = [];
  for (let i = 0; i < n; i++) {
    rows.push({ arm: '0', success: 1, tokens: 100, out_of_scope: 0 });
  }
  // Arm 1 has only 99 (one short)
  for (let i = 0; i < n - 1; i++) {
    rows.push({ arm: '1', success: 1, tokens: 100, out_of_scope: 0 });
  }
  const result = ste001Evidence(makeEvidenceDb(rows), '2025-01-01T00:00:00Z', {});
  expect(result.arms['0'].n).toBe(n);
  expect(result.arms['1'].n).toBe(n - 1);
  expect(result.status).toBe('collecting');
});

it('ste001Evidence passes through mode from env and includes note field', () => {
  const result = ste001Evidence(makeEvidenceDb([]), '2025-01-01T00:00:00Z', { STE_001_MODE: 'on' } as NodeJS.ProcessEnv);
  expect(result.mode).toBe('on');
  expect(typeof result.note).toBe('string');
  expect(result.note.length).toBeGreaterThan(0);
});

