    expect(() => parseArtefact({ kind: 'test', test_file: 'a/../b.test.ts', command: 'x' })).toThrow('EVIDENCE_ARTEFACT_TEST_FILE_INVALID');
  });
  it('rejects a test artefact with no/invalid extension', () => {
