describe('provenanceDag invariants that catch subtle breakage', () => {
  it('never infers an operator edge from a non-human requeue actor', () => {
    // An autonomy requeue must keep only the requeue_of edge — no operator source.
    proposal('p0', { status: 'verified', refs: [], source: 'reflection' });
    proposal('pa', { status: 'verified', refs: ['requeue-of:p0'], source: 'reflection' });
    proposal('pb', { status: 'verified', refs: ['requeue-by:autonomy-bot'], source: 'reflection' });
    const dag = provenanceDag(db, NOW);
    expect(findEdge(dag, 'requeue_of', 'pa')).toBeTruthy();
    expect(findEdge(dag, 'requeued_by', 'pb')).toBeUndefined();
    expect(dag.edge_counts['requeued_by'] ?? 0).toBe(0);
    const byKind = answer(dag, 'sources_by_kind').value as Record<string, { sources: number; proposals: number }>;
    expect(byKind.operator.sources).toBe(0);
  });

  it('a human requeue actor does produce a requeued_by operator edge', () => {
    proposal('pc', { status: 'verified', refs: ['requeue-by:hana.dev'], source: 'reflection' });
    const dag = provenanceDag(db, NOW);
    const e = findEdge(dag, 'requeued_by', 'pc')!;
    expect(e.source).toEqual({ kind: 'operator', id: 'hana.dev' });
    expect(e.target).toEqual({ kind: 'proposal', id: 'pc' });
    const byKind = answer(dag, 'sources_by_kind').value as Record<string, { sources: number; proposals: number }>;
    expect(byKind.operator).toEqual({ sources: 1, proposals: 1 });
  });

  it('near-duplicate verdicts become edges but are never traversed for source attribution', () => {
    fixture();
    db.prepare(`INSERT INTO judgments (id, judgment, subject_type, subject_id, state_hash, mode, decision, reason, created_at) VALUES ('j1','proposal_near_duplicate','self_improvement','p2','h','shadow','yes','similar_to=p1',?)`).run(iso(24 * 5));
    const dag = provenanceDag(db, NOW);
    // the near-dup edge exists…
    expect(findEdge(dag, 'near_duplicate_of', 'p2')).toBeTruthy();
    // …but p2's source is still only its own discovery citation, not inherited from p1 via the dup link.
    const survFromDisc = answer(dag, 'survived_from_discovery');
    // p2 has no run so it does not affect survived counts; assert tracing did not merge nodes:
    expect(survFromDisc.value).toMatchObject({ count: 1, of_survived: 2 });
  });

  it('windowDays restricts both proposals and runs to the window', () => {
    proposal('old', { status: 'verified', refs: ['knowledge-gap:x'], at: iso(24 * 30) });
    proposal('new', { status: 'verified', refs: ['knowledge-gap:y'], at: iso(24 * 2) });
    goal('new'); run('rn', 'new', survivedPr(99));
    const full = provenanceDag(db, NOW);
    const win = provenanceDag(db, NOW, { windowDays: 7 });
    expect(full.proposals).toBe(2);
    expect(win.proposals).toBe(1);
    expect(win.edges.some((e) => e.target.id === 'old' || e.source.id === 'old')).toBe(false);
    expect(win.window_days).toBe(7);
  });

  it('edgeLimit truncates the edge list but keeps edges_total honest', () => {
    fixture();
    const dag = provenanceDag(db, NOW, { edgeLimit: 3 });
    expect(dag.edges.length).toBe(3);
    expect(dag.edges_truncated).toBe(true);
    expect(dag.edges_total).toBe(EXPECTED_EDGE_SIGS.length);
  });
});

