import { describe, expect, it } from 'vitest';
import {
  speciesKey,
  banditSpecies,
  chooseSpecies,
  PROMOTE_AFTER,
  UNFAIR_ZERO_SQL,
} from '../services/runtime-bandit';
import type { Species } from '../services/evolve-selection';

// ─── helpers ────────────────────────────────────────────────────────────────

/** Minimal fake better-sqlite3 Database: prepare() once, get() N times in order. */
function makeFakeDb(results: Array<{ runs: number; ok: number }>) {
  return {
    prepare(_sql: string) {
      let idx = 0;
      return {
        get(..._params: unknown[]) {
          return results[idx++] ?? { runs: 0, ok: 0 };
        },
      };
    },
  } as any;
}

/** Deterministic LCG so betaSample is reproducible across runs. */
function lcg(seed: number): () => number {
  let s = seed % 2147483647;
  if (s <= 0) s += 2147483646;
  return () => {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

// ─── speciesKey ─────────────────────────────────────────────────────────────

describe('speciesKey', () => {
  it('returns runtime only when model is absent', () => {
    const s: Species = { runtime: 'opencode' };
    expect(speciesKey(s)).toBe('opencode');
  });

  it('returns runtime only when model is undefined', () => {
    const s: Species = { runtime: 'codex', model: undefined };
    expect(speciesKey(s)).toBe('codex');
  });

  it('joins runtime and model with @ when model is present', () => {
    const s: Species = { runtime: 'opencode', model: 'ollama/kimi-k2.6:cloud' };
    expect(speciesKey(s)).toBe('opencode@ollama/kimi-k2.6:cloud');
  });

  it('preserves runtime and model exactly, including special characters', () => {
    const s: Species = { runtime: 'claude', model: 'anthropic/claude-sonnet-4.5' };
    expect(speciesKey(s)).toBe('claude@anthropic/claude-sonnet-4.5');
  });

  it('produces the same key format used by chooseSpecies posterior', () => {
    const incumbent: Species = { runtime: 'opencode' };
    const challenger: Species = { runtime: 'opencode', model: 'ollama/kimi-k2.6:cloud' };
    expect(speciesKey(incumbent)).toBe('opencode');
    expect(speciesKey(challenger)).toBe('opencode@ollama/kimi-k2.6:cloud');
    expect(speciesKey(incumbent)).not.toBe(speciesKey(challenger));
  });

  it('treats empty-string model as absent (falsy), returning runtime only', () => {
    const s: Species = { runtime: 'hermes', model: '' };
    expect(speciesKey(s)).toBe('hermes');
  });

  it('handles a model containing @ characters after the first @', () => {
    // banditSpecies splits on FIRST '@'; speciesKey must rejoin with '@'
    const s: Species = { runtime: 'rt', model: 'a@b' };
    expect(speciesKey(s)).toBe('rt@a@b');
  });
});

// ─── banditSpecies ──────────────────────────────────────────────────────────

describe('banditSpecies', () => {
  it('returns [] when LOOP_BANDIT_ENABLED is not "true"', () => {
    expect(banditSpecies({} as NodeJS.ProcessEnv)).toEqual([]);
    expect(banditSpecies({ LOOP_BANDIT_ENABLED: 'false' } as NodeJS.ProcessEnv)).toEqual([]);
    expect(banditSpecies({ LOOP_BANDIT_ENABLED: '1' } as NodeJS.ProcessEnv)).toEqual([]);
    expect(banditSpecies({ LOOP_BANDIT_ENABLED: '' } as NodeJS.ProcessEnv)).toEqual([]);
  });

  it('parses comma-separated runtimes without models', () => {
    const env = { LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: 'opencode,codex,claude' } as NodeJS.ProcessEnv;
    expect(banditSpecies(env)).toEqual([
      { runtime: 'opencode' },
      { runtime: 'codex' },
      { runtime: 'claude' },
    ]);
  });

  it('splits on the first @ to separate runtime and model', () => {
    const env = { LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: 'opencode@ollama/kimi-k2.6:cloud' } as NodeJS.ProcessEnv;
    expect(banditSpecies(env)).toEqual([{ runtime: 'opencode', model: 'ollama/kimi-k2.6:cloud' }]);
  });

  it('trims whitespace around each entry', () => {
    const env = { LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: ' opencode , codex@model-x ' } as NodeJS.ProcessEnv;
    expect(banditSpecies(env)).toEqual([
      { runtime: 'opencode' },
      { runtime: 'codex', model: 'model-x' },
    ]);
  });

  it('filters out empty entries from consecutive or trailing commas', () => {
    const env = { LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: 'opencode,,codex,' } as NodeJS.ProcessEnv;
    expect(banditSpecies(env)).toEqual([
      { runtime: 'opencode' },
      { runtime: 'codex' },
    ]);
  });

  it('returns [] when enabled but species list is empty/whitespace-only', () => {
    expect(banditSpecies({ LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: '' } as NodeJS.ProcessEnv)).toEqual([]);
    expect(banditSpecies({ LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: '   ' } as NodeJS.ProcessEnv)).toEqual([]);
  });

  it('handles a model that itself contains @ (splits on first @ only)', () => {
    const env = { LOOP_BANDIT_ENABLED: 'true', LOOP_BANDIT_SPECIES: 'rt@a@b' } as NodeJS.ProcessEnv;
    expect(banditSpecies(env)).toEqual([{ runtime: 'rt', model: 'a@b' }]);
  });
});

// ─── constants ──────────────────────────────────────────────────────────────

describe('PROMOTE_AFTER', () => {
  it('is exactly 20', () => {
    expect(PROMOTE_AFTER).toBe(20);
  });
});

describe('UNFAIR_ZERO_SQL', () => {
  it('contains all three outcome_class / evolve clauses', () => {
    expect(UNFAIR_ZERO_SQL).toContain('outcome_class:infra_failed');
    expect(UNFAIR_ZERO_SQL).toContain('outcome_class:no_change');
    expect(UNFAIR_ZERO_SQL).toContain('evolve:lost_eligible');
  });

  it('uses LIKE with evidence_refs_json for each clause', () => {
    expect(UNFAIR_ZERO_SQL).toMatch(/evidence_refs_json\s+LIKE/);
  });

  it('is a parenthesised OR-group (starts and ends with parens)', () => {
    expect(UNFAIR_ZERO_SQL.trimStart().startsWith('(')).toBe(true);
    expect(UNFAIR_ZERO_SQL.trimEnd().endsWith(')')).toBe(true);
  });
});

// ─── chooseSpecies ──────────────────────────────────────────────────────────

describe('chooseSpecies', () => {
  const sA: Species = { runtime: 'opencode' };
  const sB: Species = { runtime: 'codex', model: 'gpt-4o' };

  it('returns null when fewer than 2 species are given', () => {
    const db = makeFakeDb([{ runs: 10, ok: 5 }]);
    expect(chooseSpecies(db, 'loop-x', [sA], lcg(42))).toBeNull();
    expect(chooseSpecies(db, 'loop-x', [], lcg(42))).toBeNull();
  });

  it('returns null when the database query throws (lazy table creation)', () => {
    const badDb = { prepare() { throw new Error('no such table'); } } as any;
    expect(chooseSpecies(badDb, 'loop-x', [sA, sB], lcg(7))).toBeNull();
  });

  it('posterior has one entry per species with correct key and stats', () => {
    const db = makeFakeDb([{ runs: 33, ok: 28 }, { runs: 12, ok: 9 }]);
    const result = chooseSpecies(db, 'my-loop', [sA, sB], lcg(99));
    expect(result).not.toBeNull();
    expect(result!.posterior).toHaveLength(2);
    expect(result!.posterior[0].species).toBe(speciesKey(sA)); // 'opencode'
    expect(result!.posterior[0].runs).toBe(33);
    expect(result!.posterior[0].ok).toBe(28);
    expect(result!.posterior[1].species).toBe(speciesKey(sB)); // 'codex@gpt-4o'
    expect(result!.posterior[1].runs).toBe(12);
    expect(result!.posterior[1].ok).toBe(9);
    // sample must be a finite number in (0,1)
    for (const p of result!.posterior) {
      expect(p.sample).toBeGreaterThan(0);
      expect(p.sample).toBeLessThan(1);
      expect(Number.isFinite(p.sample)).toBe(true);
    }
  });

  it('selects the incumbent when its posterior sample is highest (extreme prior)', () => {
    // Incumbent: 500 runs, 490 ok → beta(491,11), mean ≈ 0.978
    // Challenger: 500 runs, 10 ok → beta(11,491), mean ≈ 0.022
    const db = makeFakeDb([{ runs: 500, ok: 490 }, { runs: 500, ok: 10 }]);
    const result = chooseSpecies(db, 'loop-y', [sA, sB], lcg(1));
    expect(result).not.toBeNull();
    expect(result!.species).toEqual(sA);
    expect(result!.reason).toContain('incumbent');
  });

  it('promotes a challenger that has ≥ PROMOTE_AFTER outcomes and samples best', () => {
    // Incumbent: 30 runs, 6 ok → beta(7,25), mean ≈ 0.219
    // Challenger: 25 runs, 23 ok → beta(24,3), mean ≈ 0.889 (runs=25 ≥ 20)
    const db = makeFakeDb([{ runs: 30, ok: 6 }, { runs: 25, ok: 23 }]);
    const result = chooseSpecies(db, 'loop-z', [sA, sB], lcg(2));
    expect(result).not.toBeNull();
    expect(result!.species).toEqual(sB);
    expect(result!.reason).toContain('challenger sampled best');
    expect(result!.reason).toContain(String(PROMOTE_AFTER - 1 + 1)); // mentions the run count
  });

  it('caps or explores a challenger with < PROMOTE_AFTER outcomes (never promotes)', () => {
    // Challenger clearly better but only 5 outcomes (< 20)
    const db = makeFakeDb([{ runs: 100, ok: 20 }, { runs: 5, ok: 5 }]);
    // Run multiple seeds; the reason must NEVER say "challenger sampled best"
    for (let seed = 1; seed <= 20; seed++) {
      const result = chooseSpecies(db, 'loop-cap', [sA, sB], lcg(seed * 7919));
      expect(result).not.toBeNull();
      if (result!.species === sB) {
        // explored path
        expect(result!.reason).toContain('explored');
        expect(result!.reason).toContain('<');
        expect(result!.reason).toContain(String(PROMOTE_AFTER));
      } else {
        // capped → incumbent returned
        expect(result!.species).toEqual(sA);
        expect(result!.reason).toMatch(/incumbent|capped/);
      }
    }
  });

  it('passes skill_id as loop-maker:<loopName>:<runtime> and model as empty string when absent', () => {
    let capturedParams: unknown[][] = [];
    const db = {
      prepare(_sql: string) {
        return {
          get(...params: unknown[]) {
            capturedParams.push(params);
            return { runs: 1, ok: 1 };
          },
        };
      },
    } as any;
    chooseSpecies(db, 'my-loop', [{ runtime: 'rt-a' }, { runtime: 'rt-b', model: 'm-1' }], lcg(5));
    expect(capturedParams).toHaveLength(2);
    expect(capturedParams[0]).toEqual(['loop-maker:my-loop:rt-a', '']);
    expect(capturedParams[1]).toEqual(['loop-maker:my-loop:rt-b', 'm-1']);
  });
});

