import { describe, expect, it } from 'vitest';
import {
  caseOutcome,
  clopperPearsonUpper,
  D5NO_ANALYSIS_N,
  D5NO_CUTOFF,
  D5NO_DEADLINE_DAYS,
  D5NO_MAX_RISK,
  D5NO_PREREG_SHA256,
  isConfidentNo,
  maxErrorsAllowed,
  minClustersForBound,
} from '../services/d5-no';

// ── Frozen protocol constants ────────────────────────────────────────────────
describe('frozen protocol constants', () => {
  it('D5NO_CUTOFF is the exact frozen ISO timestamp', () => {
    expect(D5NO_CUTOFF).toBe('2026-10-11T21:00:00.000Z');
  });
  it('D5NO_PREREG_SHA256 is the exact preregistration hash', () => {
    expect(D5NO_PREREG_SHA256).toBe('2730c749acd68599e779ecbeac9016bca9d3800f5f8b81f2cc196eaa3c314b0e');
  });
  it('D5NO_ANALYSIS_N is 100 (single efficacy analysis size)', () => {
    expect(D5NO_ANALYSIS_N).toBe(100);
  });
  it('D5NO_MAX_RISK is one-sided 95 % bound threshold 0.05', () => {
    expect(D5NO_MAX_RISK).toBe(0.05);
  });
  it('D5NO_DEADLINE_DAYS is 90', () => {
    expect(D5NO_DEADLINE_DAYS).toBe(90);
  });
});

// ── isConfidentNo ────────────────────────────────────────────────────────────
describe('isConfidentNo', () => {
  it("returns true only for the exact string 'no'", () => {
    expect(isConfidentNo('no')).toBe(true);
  });
  it('returns false for other decisions and null/undefined', () => {
    expect(isConfidentNo('yes')).toBe(false);
    expect(isConfidentNo('uncertain')).toBe(false);
    expect(isConfidentNo(null)).toBe(false);
    expect(isConfidentNo(undefined)).toBe(false);
    expect(isConfidentNo('')).toBe(false);
    // case-sensitive: protocol decision is lowercase
    expect(isConfidentNo('NO')).toBe(false);
    expect(isConfidentNo(' No')).toBe(false);
  });
});

// ── clopperPearsonUpper (exact one-sided CP upper bound) ─────────────────────
describe('clopperPearsonUpper', () => {
  it('returns null when n ≤ 0', () => {
    expect(clopperPearsonUpper(0, 0)).toBeNull();
    expect(clopperPearsonUpper(1, -5)).toBeNull();
  });
  it('returns 1 when k ≥ n (all events)', () => {
    expect(clopperPearsonUpper(5, 5)).toBe(1);
    expect(clopperPearsonUpper(7, 3)).toBe(1);
  });
  it('cp(0,1) ≈ 0.95 (single trial, zero events → 95 % upper = 0.95)', () => {
    expect(clopperPearsonUpper(0, 1)).toBeCloseTo(0.95, 4);
  });
  it('cp(0,100) ≈ 0.0295 (zero false rejections in 100 resolved cases)', () => {
    expect(clopperPearsonUpper(0, 100)).toBeCloseTo(0.029513, 4);
  });
  it('cp(1,100) ≈ 0.0466 (one false rejection in 100 — still below 0.05)', () => {
    expect(clopperPearsonUpper(1, 100)).toBeCloseTo(0.046560, 4);
  });
  it('cp(2,100) ≈ 0.0616 (two false rejections in 100 — exceeds 0.05)', () => {
    expect(clopperPearsonUpper(2, 100)).toBeCloseTo(0.061619, 4);
  });
  it('is monotonically increasing in k for fixed n', () => {
    const vals = [0, 1, 2, 3].map((k) => clopperPearsonUpper(k, 50)!);
    for (let i = 1; i < vals.length; i++) {
      expect(vals[i]).toBeGreaterThan(vals[i - 1]);
    }
  });
  it('decreases toward the true rate as n grows (zero events)', () => {
    const small = clopperPearsonUpper(0, 10)!;
    const large = clopperPearsonUpper(0, 200)!;
    expect(large).toBeLessThan(small);
  });
  it('respects custom alpha: cp(0,1,0.01) > cp(0,1,0.05) (tighter bound at lower alpha)', () => {
    // Wait — lower alpha means a WIDER confidence interval, so upper is HIGHER.
    // Actually CP upper with smaller alpha → larger p* because we need binomCdf ≤ smaller alpha
    // which requires larger p. So cp(0,1,0.01) should be > cp(0,1,0.05).
    expect(clopperPearsonUpper(0, 1, 0.01)).toBeGreaterThan(clopperPearsonUpper(0, 1, 0.05));
  });
});

// ── maxErrorsAllowed ─────────────────────────────────────────────────────────
describe('maxErrorsAllowed', () => {
  it('at n=100 allows exactly 1 error (cp(1,100)<0.05 but cp(2,100)≥0.05)', () => {
    expect(maxErrorsAllowed(D5NO_ANALYSIS_N)).toBe(1);
  });
  it('returns -1 when even zero errors cannot reach the threshold (very small n)', () => {
    // For very small n, cp(0,n) ≥ 0.05 always, so no k works → -1
    expect(maxErrorsAllowed(1)).toBe(-1);
    expect(maxErrorsAllowed(10)).toBe(-1);
  });
  it('is non-decreasing in n', () => {
    const a = maxErrorsAllowed(60);
    const b = maxErrorsAllowed(100);
    expect(b).toBeGreaterThanOrEqual(a);
  });
});

// ── minClustersForBound ──────────────────────────────────────────────────────
describe('minClustersForBound', () => {
  it('requires at least 59 independent clusters for the bound to fall below 0.05 with 0 errors', () => {
    expect(minClustersForBound()).toBe(59);
  });
  it('the returned n satisfies cp(0,n) < D5NO_MAX_RISK and cp(0,n-1) ≥ D5NO_MAX_RISK', () => {
    const n = minClustersForBound();
    expect(clopperPearsonUpper(0, n)!).toBeLessThan(D5NO_MAX_RISK);
    expect(clopperPearsonUpper(0, n - 1)!).toBeGreaterThanOrEqual(D5NO_MAX_RISK);
  });
});

// ── caseOutcome (cluster outcome classification) ────────────────────────────
describe('caseOutcome', () => {
