    expect(prepareState('ghp_abcdef1234567890')).toBe('[redacted]');
    expect(prepareState('bot SLACK_TOKEN_FIXTURE_REDACTED')).not.toContain('SLACK_TOKEN_FIXTURE_REDACTED');
    expect(prepareState('aws AWS_KEY_FIXTURE_REDACTED key')).not.toContain('AWS_KEY_FIXTURE_REDACTED');
  });

  it('redacts password/passwd/secret/token/api_key assignment patterns', () => {
    const out = prepareState({ creds: 'password=hunter2' }) as { creds: string };
    expect(out.creds).toContain('[redacted]');
    expect(out.creds).not.toContain('hunter2');
    const out2 = prepareState('api_key: abcdef123') as string;
    expect(out2).toContain('[redacted]');
    expect(out2).not.toContain('abcdef123');
  });

  it('leaves ordinary strings untouched', () => {
    expect(prepareState('hello world, nothing secret here')).toBe('hello world, nothing secret here');
  });

  it('caps a single string at the state budget (60_000 chars)', () => {
    const big = 'a'.repeat(70_000);
    const out = prepareState(big) as string;
    expect(out.length).toBe(60_000);
  });

  it('truncates arrays to at most 200 entries and scrubs their items', () => {
    const arr = Array.from({ length: 250 }, (_, i) => `item-${i}`);
    const out = prepareState(arr) as unknown[];
    expect(out.length).toBe(200);
    const withSecret = prepareState(['ok', 'ghp_abcdef1234567890']) as string[];
    expect(withSecret[1]).toBe('[redacted]');
  });

  it('scrubs secrets nested inside objects while preserving structure', () => {
    const out = prepareState({ meta: { key: 'ghp_abcdef1234567890', name: 'x' } }) as {
      meta: { key: string; name: string };
    };
    expect(out.meta.key).toBe('[redacted]');
    expect(out.meta.name).toBe('x');
  });

  it('passes non-string primitives through unchanged', () => {
    expect(prepareState(42)).toBe(42);
    expect(prepareState(true)).toBe(true);
    expect(prepareState(null)).toBeNull();
    expect(prepareState(undefined)).toBeUndefined();
  });
});

