describe('TypeSafeClient.systemOne', () => {
  beforeEach(() => {
    resetTypesafeBreaker();
    resetTypesafeLimiter();
    process.env.TYPESAFE_API_KEY = 'test-key';
    delete process.env.TYPESAFE_BASE_URL;
    delete process.env.TYPESAFE_MODEL;
    delete process.env.TYPESAFE_MAX_CONCURRENCY;
    delete process.env.TYPESAFE_MAX_QUEUE;
  });
  afterEach(() => {
    delete process.env.TYPESAFE_API_KEY;
    delete process.env.TYPESAFE_BASE_URL;
    delete process.env.TYPESAFE_MODEL;
    delete process.env.TYPESAFE_MAX_CONCURRENCY;
    delete process.env.TYPESAFE_MAX_QUEUE;
  });

  it('throws TYPESAFE_NOT_CONFIGURED and never calls fetch without a key', async () => {
    delete process.env.TYPESAFE_API_KEY;
    const fetchFn = vi.fn().mockImplementation(() => { throw new Error('fetch should not be called'); }) as unknown as typeof fetch;
    const client = new TypeSafeClient(fetchFn);
    await expect(client.systemOne({}, {}, {})).rejects.toThrow('TYPESAFE_NOT_CONFIGURED');
    expect(fetchFn).not.toHaveBeenCalled();
  });

  it('returns the parsed payload on success and records one attempt', async () => {
    const payload = { model: 'jev-1.13.0', answers: { q: { type: 'noul', noul: 0.7 } } };
    const fetchFn = vi.fn().mockResolvedValue(okResponse(payload)) as unknown as typeof fetch;
    const client = new TypeSafeClient(fetchFn);
    const out = await client.systemOne({ state: 1 }, { q: { type: 'noul', instructions: 'i' } }, { retries: 0 });
    expect(out).toEqual(payload);
    expect(fetchFn).toHaveBeenCalledTimes(1);
  });

  it('posts to <base>/v1/systemone with auth + content-type headers and a prepared body', async () => {
    const fetchFn = vi.fn().mockResolvedValue(okResponse({ model: 'm', answers: {} })) as unknown as typeof fetch;
    const client = new TypeSafeClient(fetchFn);
    await client.systemOne({ secret: 'ghp_abcdef1234567890' }, { q: { type: 'choice', instructions: 'pick' } }, { retries: 0 });

    expect(fetchFn).toHaveBeenCalledTimes(1);
    const [url, init] = fetchFn.mock.calls[0] as [string, RequestInit];
    expect(url).toBe('https://api.typesafe.ai/v1/systemone');
    expect(init.method).toBe('POST');
    const headers = init.headers as Record<string, string>;
    expect(headers['Content-Type']).toBe('application/json');
    expect(headers.Authorization).toBe('Bearer test-key');
    expect(init.signal).toBeInstanceOf(AbortSignal);

    const body = JSON.parse(String(init.body)) as { state: { secret: string }; model: string; questions: Record<string, unknown> };
    expect(body.state.secret).toBe('[redacted]'); // prepareState applied to the outgoing state
    expect(body.model).toBe('jev-1.13.0'); // default pinned model
    expect(body.questions.q.type).toBe('choice');
  });

  it('honours a custom TYPESAFE_BASE_URL (trailing slash stripped) and TYPESAFE_MODEL override', async () => {
    process.env.TYPESAFE_BASE_URL = 'https://custom.example/';
    process.env.TYPESAFE_MODEL = 'jev-9.9.9';
    const fetchFn = vi.fn().mockResolvedValue(okResponse({ model: 'jev-9.9.9', answers: {} })) as unknown as typeof fetch;
    const client = new TypeSafeClient(fetchFn);
    await client.systemOne({}, {}, { retries: 0 });
    const [url, init] = fetchFn.mock.calls[0] as [string, RequestInit];
    expect(url).toBe('https://custom.example/v1/systemone');
    const body = JSON.parse(String(init.body)) as { model: string };
    expect(body.model).toBe('jev-9.9.9');
  });

  it('does not retry on 401 or 422 even when retries are allowed', async () => {
    for (const status of [401, 422]) {
      resetTypesafeBreaker();
      const fetchFn = vi.fn().mockResolvedValue(errResponse(status)) as unknown as typeof fetch;
      const client = new TypeSafeClient(fetchFn);
      await expect(client.systemOne({}, {}, { retries: 3 })).rejects.toThrow(`TYPESAFE_FAILED: http_${status}`);
      expect(fetchFn).toHaveBeenCalledTimes(1); // single attempt, no backoff
    }
  });

  it('retries transient 5xx responses up to the configured attempts then fails with the last status', async () => {
    const fetchFn = vi.fn().mockResolvedValue(errResponse(500)) as unknown as typeof fetch;
    const client = new TypeSafeClient(fetchFn);
    await expect(client.systemOne({}, {}, { retries: 1 })).rejects.toThrow('TYPESAFE_FAILED: http_500');
    expect(fetchFn).toHaveBeenCalledTimes(2); // initial + one retry
  });

  it('resets the failure counter on success so a later short burst does not open the breaker', async () => {
    const failFetch = vi.fn().mockResolvedValue(errResponse(500)) as unknown as typeof fetch;
    const okFetch = vi.fn().mockResolvedValue(okResponse({ model: 'm', answers: {} })) as unknown as typeof fetch;
    const failing = new TypeSafeClient(failFetch);
    const succeeding = new TypeSafeClient(okFetch);

    for (let i = 0; i < 2; i += 1) await expect(failing.systemOne({}, {}, { retries: 0 })).rejects.toThrow();
    expect(typesafeBusy()).toBe(false); // 2 failures, below threshold
    await succeeding.systemOne({}, {}, { retries: 0 }); // success resets failures to 0
    for (let i = 0; i < 2; i += 1) await expect(failing.systemOne({}, {}, { retries: 0 })).rejects.toThrow();
    expect(typesafeBusy()).toBe(false); // would be true if the reset were missing (4 total failures)
  });

  it('opens the breaker after 3 consecutive failures and then refuses without calling fetch', async () => {
    const failFetch = vi.fn().mockResolvedValue(errResponse(500)) as unknown as typeof fetch;
    const client = new TypeSafeClient(failFetch);
    for (let i = 0; i < 3; i += 1) {
      await expect(client.systemOne({}, {}, { retries: 0 })).rejects.toThrow('TYPESAFE_FAILED');
    }
    expect(typesafeBusy()).toBe(true);
    await expect(client.systemOne({}, {}, { retries: 0 })).rejects.toThrow('TYPESAFE_BREAKER_OPEN');
    expect(failFetch).toHaveBeenCalledTimes(3); // the open-breaker call must not reach fetch
  });

  it('fails fast with TYPESAFE_QUEUE_FULL once the wait queue is full', async () => {
    process.env.TYPESAFE_MAX_CONCURRENCY = '1';
    process.env.TYPESAFE_MAX_QUEUE = '1';
    const hangingFetch = vi.fn().mockImplementation(() => new Promise<never>(() => {})) as unknown as typeof fetch;
    const client = new TypeSafeClient(hangingFetch);
    void client.systemOne({}, {}, { retries: 0 }); // holds the only slot
    void client.systemOne({}, {}, { retries: 0 }); // occupies the single waiting slot
    await Promise.resolve();
    const third = client.systemOne({}, {}, { retries: 0 });
    await expect(third).rejects.toThrow('TYPESAFE_QUEUE_FULL');
    expect(typesafeBusy()).toBe(true); // a call is queued behind the limiter
  });
});

describe('typesafeBusy', () => {
  beforeEach(() => {
    resetTypesafeBreaker();
    resetTypesafeLimiter();
    process.env.TYPESAFE_API_KEY = 'test-key';
  });
  afterEach(() => {
    delete process.env.TYPESAFE_API_KEY;
    delete process.env.TYPESAFE_MAX_CONCURRENCY;
    delete process.env.TYPESAFE_MAX_QUEUE;
  });

  it('is false when the breaker is closed and nothing is queued', () => {
    expect(typesafeBusy()).toBe(false);
  });

  it('is true while the breaker is open, and false again after reset', async () => {
    const failFetch = vi.fn().mockResolvedValue(errResponse(500)) as unknown as typeof fetch;
    const client = new TypeSafeClient(failFetch);
    for (let i = 0; i < 3; i += 1) await expect(client.systemOne({}, {}, { retries: 0 })).rejects.toThrow();
    expect(typesafeBusy()).toBe(true);
    resetTypesafeBreaker();
    expect(typesafeBusy()).toBe(false);
  });
});

