    recordFleetVerdict(db, 'evt-dup', v, mode, now);
    // second insert with same event_id but different verdict should be ignored
    recordFleetVerdict(db, 'evt-dup', { ...v, verdict: 'replay' }, 'enforce', now + 1000);
    const rows = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').all('evt-dup') as Array<Record<string, unknown>>;
    expect(rows.length).toBe(1);
    expect(rows[0].verdict).toBe('verified');
  });
  it('stores null host and key_id when verification has no host/key', () => {
    ensureFleetSignatureTables(db);
    const unsigned: FleetVerification = { verdict: 'unsigned', host: null, key_id: null };
    recordFleetVerdict(db, 'evt-ns', unsigned, 'off', now);
    const row = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id = ?').get('evt-ns') as Record<string, unknown> | undefined;
    expect(row!.host).toBeNull();
    expect(row!.key_id).toBeNull();
    expect(row!.verdict).toBe('unsigned');
  });
});

describe('fleetSignatureMode', () => {
  it('defaults to off when unset or unrecognized', () => {
    expect(fleetSignatureMode({})).toBe('off');
    expect(fleetSignatureMode({ FLEET_EVENT_SIGNATURES: '' })).toBe('off');
    expect(fleetSignatureMode({ FLEET_EVENT_SIGNATURES: 'bogus' })).toBe('off');
    expect(fleetSignatureMode({ FLEET_EVENT_SIGNATURES: 'OFF' })).toBe('off');
  });
  it('parses shadow and enforce exactly', () => {
    expect(fleetSignatureMode({ FLEET_EVENT_SIGNATURES: 'shadow' })).toBe('shadow');
    expect(fleetSignatureMode({ FLEET_EVENT_SIGNATURES: 'enforce' })).toBe('enforce');
  });
});

describe('canonicalJson', () => {
  it('sorts object keys recursively with no whitespace', () => {
    expect(canonicalJson({ b: 1, a: 2 })).toBe('{"a":2,"b":1}');
    expect(canonicalJson({ x: { z: 0, y: 'q' }, w: true })).toBe('{"w":true,"x":{"y":"q","z":0}}');
  });
  it('handles arrays (order preserved) and nested objects inside them', () => {
    expect(canonicalJson([1, { d: 2, c: [3] }])).toBe('[1,{"c":[3],"d":2}]');
    expect(canonicalJson([])).toBe('[]');
    expect(canonicalJson({})).toBe('{}');
  });
  it('serializes scalars via JSON.stringify', () => {
    expect(canonicalJson('hi')).toBe('"hi"');
    expect(canonicalJson(null)).toBe('null');
    expect(canonicalJson(true)).toBe('true');
    expect(canonicalJson(42)).toBe('42');
  });
});

describe('fleetSignedBody', () => {
  const nowIso = '2025-06-01T00:00:00Z';
  it('builds the exact canonical signed body with an independently computed payload_sha256', () => {
    const event = {
      agent: 'a', event_id: 'e1', host: 'h', success: true, task_kind: 't', occurred_at: nowIso,
      duration_ms: '120', model: 'm',
    };
    // only present optional fields go into the payload; strings are the stable form
    const expectedPayloadSha = sha256hex('{"duration_ms":"120","model":"m"}');
    const expected = `{"agent":"a","event_id":"e1","host":"h","payload_sha256":"${expectedPayloadSha}","success":true,"task_kind":"t","ts":"${nowIso}"}`;
    expect(fleetSignedBody(event)).toBe(expected);
  });
  it('coerces string booleans and omits absent/null optional fields from the payload hash', () => {
    const base = { agent: 'a', event_id: 'e1', host: 'h', task_kind: 't', occurred_at: nowIso };
    const withTrueStr = { ...base, success: 'true' };
    expect(fleetSignedBody(withTrueStr)).toContain('"success":true');
    const withFalseStr = { ...base, success: 'false' };
    expect(fleetSignedBody(withFalseStr)).toContain('"success":false');
    // no optional fields → empty object payload
    const expectedEmpty = sha256hex('{}');
    expect(fleetSignedBody(base)).toContain(`"payload_sha256":"${expectedEmpty}"`);
    // null optional field is treated as absent
    const withNullRef = { ...base, ref: null };
    expect(fleetSignedBody(withNullRef)).toContain(`"payload_sha256":"${expectedEmpty}"`);
  });
});

describe('signFleetEventHmac', () => {
  it('produces a base64url HMAC over the signed body that matches an independent computation', () => {
    const key = deriveFleetHmacKey('M', 'host1', 'abcd1234');
    const event = { agent: 'a', event_id: 'e9', host: 'host1', success: false, task_kind: 't', occurred_at: '2025-06-01T00:00:00Z' };
    const expected = createHmac('sha256', key).update(fleetSignedBody(event), 'utf8').digest('base64url');
    expect(signFleetEventHmac(key, event)).toBe(expected);
    expect(signFleetEventHmac(key, event)).toMatch(/^[A-Za-z0-9_-]+$/);
  });
});

describe('registerFleetHostKey / revokeFleetHostKey', () => {
  it('rejects invalid hosts', () => {
    expect(() => registerFleetHostKey(db, 'bad host!')).toThrow('FLEET_HOST_INVALID');
  });
  it('requires a public key for ed25519 and validates its type', () => {
    expect(() => registerFleetHostKey(db, 'h-ed', { alg: 'ed25519' })).toThrow('FLEET_PUBLIC_KEY_REQUIRED');
    const rsa = generateKeyPairSync('rsa', { modulusLength: 2048 });
    const rsaPem = rsa.publicKey.export({ type: 'spki', format: 'pem' }) as string;
    expect(() => registerFleetHostKey(db, 'h-ed', { alg: 'ed25519', publicKey: rsaPem })).toThrow('FLEET_PUBLIC_KEY_NOT_ED25519');
  });
  it('registers an active hmac key with a derived secret and stores no public_key', () => {
    const res = registerFleetHostKey(db, 'host-a', { alg: 'hmac-sha256', master: 'M', now: Date.parse('2025-06-01T00:00:00Z') });
    expect(res.host).toBe('host-a');
    expect(res.alg).toBe('hmac-sha256');
    expect(res.key_id).toMatch(/^[a-f0-9]{8,32}$/);
    expect(res.secret).toBe(deriveFleetHmacKey('M', 'host-a', res.key_id));
    const row = db.prepare('SELECT * FROM fleet_event_keys WHERE host=? AND key_id=?').get('host-a', res.key_id) as Record<string, unknown> | undefined;
    expect(row).toBeDefined();
    expect(row!.status).toBe('active');
    expect(row!.public_key).toBeNull();
  });
  it('revokes one specific key then the remainder of a host', () => {
    const k1 = registerFleetHostKey(db, 'host-b', { alg: 'hmac-sha256', master: 'M' });
    const k2 = registerFleetHostKey(db, 'host-b', { alg: 'hmac-sha256', master: 'M' });
    expect(revokeFleetHostKey(db, 'host-b', k1.key_id)).toBe(1);
    const s1 = (db.prepare("SELECT status FROM fleet_event_keys WHERE host='host-b' AND key_id=?").get(k1.key_id) as { status: string }).status;
    const s2 = (db.prepare("SELECT status FROM fleet_event_keys WHERE host='host-b' AND key_id=?").get(k2.key_id) as { status: string }).status;
    expect(s1).toBe('revoked');
    expect(s2).toBe('active');
    // revoking without a key id takes every remaining active key
    expect(revokeFleetHostKey(db, 'host-b')).toBe(1);
    const all = db.prepare("SELECT status FROM fleet_event_keys WHERE host='host-b'").all() as Array<{ status: string }>;
    expect(all.every((r) => r.status === 'revoked')).toBe(true);
  });
});

describe('verifyFleetEvent', () => {
  const now = Date.parse('2025-06-01T00:00:00Z');
  const mkEvent = (over: Record<string, unknown> = {}): Record<string, unknown> => ({
    agent: 'a', event_id: 'evt-abc', host: 'vh', success: true, task_kind: 't', occurred_at: new Date(now).toISOString(), ...over,
  });

  it('verifies a correctly signed hmac event and rejects its replay', () => {
    const reg = registerFleetHostKey(db, 'vh', { alg: 'hmac-sha256', master: 'M', now });
    const ev = mkEvent({ key_id: reg.key_id, sig_alg: 'hmac-sha256' });
    ev.sig = signFleetEventHmac(reg.secret!, ev);
    const first = verifyFleetEvent(db, ev, { master: 'M', now });
    expect(first).toEqual({ verdict: 'verified', host: 'vh', key_id: reg.key_id });
    // identical second submission is a nonce replay
    const second = verifyFleetEvent(db, ev, { master: 'M', now });
    expect(second.verdict).toBe('replay');
  });

  it('returns unsigned when no signature is present (and does not consume the nonce)', () => {
    registerFleetHostKey(db, 'vh', { alg: 'hmac-sha256', master: 'M', now });
    const v = verifyFleetEvent(db, mkEvent(), { master: 'M', now });
    expect(v.verdict).toBe('unsigned');
  });

  it('returns unknown_host for an unregistered host/key pair', () => {
    // tables must exist so the registry lookup runs (an empty registry yields unknown_host,
    // whereas a missing table is swallowed by the catch path)
    ensureFleetSignatureTables(db);
    const ev = mkEvent({ key_id: 'abcd1234', sig_alg: 'hmac-sha256', sig: createHmac('sha256', 'x').update('y').digest('base64url') });
    expect(verifyFleetEvent(db, ev, { master: 'M', now }).verdict).toBe('unknown_host');
  });

  it('returns revoked once the key has been revoked', () => {
    const reg = registerFleetHostKey(db, 'vh', { alg: 'hmac-sha256', master: 'M', now });
    revokeFleetHostKey(db, 'vh', reg.key_id);
    const ev = mkEvent({ key_id: reg.key_id, sig_alg: 'hmac-sha256' });
    ev.sig = signFleetEventHmac(reg.secret!, ev);
    expect(verifyFleetEvent(db, ev, { master: 'M', now }).verdict).toBe('revoked');
  });

  it('returns bad_signature when the signature does not match (wrong secret)', () => {
    const reg = registerFleetHostKey(db, 'vh', { alg: 'hmac-sha256', master: 'M', now });
    const ev = mkEvent({ key_id: reg.key_id, sig_alg: 'hmac-sha256' });
    // signed with a different derived key → mismatch
    ev.sig = signFleetEventHmac(deriveFleetHmacKey('WRONG', 'vh', reg.key_id), ev);
    expect(verifyFleetEvent(db, ev, { master: 'M', now }).verdict).toBe('bad_signature');
  });

  it('returns replay when ts is outside the window even if correctly signed', () => {
    const reg = registerFleetHostKey(db, 'vh', { alg: 'hmac-sha256', master: 'M', now });
    const oldTs = new Date(now - FLEET_EVENT_WINDOW_MS - 1000).toISOString();
    const ev = mkEvent({ key_id: reg.key_id, sig_alg: 'hmac-sha256', occurred_at: oldTs });
    ev.sig = signFleetEventHmac(reg.secret!, ev);
    expect(verifyFleetEvent(db, ev, { master: 'M', now }).verdict).toBe('replay');
  });

  it('accepts an ed25519 signature and rejects a tampered one', () => {
    const pair = generateKeyPairSync('ed25519');
    const pubPem = pair.publicKey.export({ type: 'spki', format: 'pem' }) as string;
    const reg = registerFleetHostKey(db, 'vhe', { alg: 'ed25519', publicKey: pubPem, now });
    const ev = mkEvent({ host: 'vhe', event_id: 'evt-ed', key_id: reg.key_id, sig_alg: 'ed25519' });
    const goodSig = cryptoSign(null, Buffer.from(fleetSignedBody(ev), 'utf8'), pair.privateKey).toString('base64url');
    ev.sig = goodSig;
    expect(verifyFleetEvent(db, ev, { now })).toEqual({ verdict: 'verified', host: 'vhe', key_id: reg.key_id });
    // tamper the payload after signing → bad_signature
    const ev2 = mkEvent({ host: 'vhe', event_id: 'evt-ed2', key_id: reg.key_id, sig_alg: 'ed25519', task_kind: 'tampered' });
    ev2.sig = goodSig;
    expect(verifyFleetEvent(db, ev2, { now }).verdict).toBe('bad_signature');
  });
});

describe('pruneFleetNonces', () => {
  it('deletes only nonces older than two windows', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2025-06-01T00:00:00Z');
    db.prepare('INSERT INTO fleet_event_nonces (event_id, host, seen_at) VALUES (?, ?, ?)').run('old', 'h', now - 3 * FLEET_EVENT_WINDOW_MS);
    db.prepare('INSERT INTO fleet_event_nonces (event_id, host, seen_at) VALUES (?, ?, ?)').run('new', 'h', now - FLEET_EVENT_WINDOW_MS);
    expect(pruneFleetNonces(db, now)).toBe(1);
    const remaining = db.prepare('SELECT event_id FROM fleet_event_nonces').all() as Array<{ event_id: string }>;
    expect(remaining.map((r) => r.event_id)).toEqual(['new']);
  });
});

describe('fleetSignatureEvidence', () => {
  it('reports mode, per-host verdict counts and the key list without secrets', () => {
    ensureFleetSignatureTables(db);
    registerFleetHostKey(db, 'ev-h', { alg: 'hmac-sha256', master: 'M' });
    recordFleetVerdict(db, 'e-1', { verdict: 'verified', host: 'ev-h', key_id: 'abcd1234' }, 'shadow');
    recordFleetVerdict(db, 'e-2', { verdict: 'replay', host: 'ev-h', key_id: 'abcd1234' }, 'shadow');
    const ev = fleetSignatureEvidence(db, { FLEET_EVENT_SIGNATURES: 'shadow' }) as
      { mode: FleetSignatureMode; by_host: Array<{ host: string; verdict: string; n: number }>; keys: Array<Record<string, unknown>> };
    expect(ev.mode).toBe('shadow');
    expect(ev.by_host).toContainEqual({ host: 'ev-h', verdict: 'verified', n: 1 });
    expect(ev.by_host).toContainEqual({ host: 'ev-h', verdict: 'replay', n: 1 });
    expect(ev.keys.length).toBe(1);
    expect(ev.keys[0].host).toBe('ev-h');
    // no secret material leaks into evidence
    expect(JSON.stringify(ev)).not.toContain('secret');
  });
});

describe('constants', () => {
  it('exposes the full verdict set and a 24h window', () => {
    expect([...FLEET_SIGNATURE_VERDICTS]).toEqual(['verified', 'unsigned', 'bad_signature', 'replay', 'unknown_host', 'revoked']);
    expect(FLEET_EVENT_WINDOW_MS).toBe(86_400_000);
  });
});

