  const outcome = (arm: string, success: number, tokens: number, graded?: string) =>
    db.prepare(`INSERT INTO skill_outcomes (id, skill_id, evidence_refs_json, success, tokens_used, created_at)
      VALUES (?, 'maker', ?, ?, ?, ?)`)
      .run(`${arm}-${success}`, JSON.stringify(graded ? [`ace-001-arm:${arm}`, `graded:${graded}`] : [`ace-001-arm:${arm}`]), success, tokens, now);
