    expect(ev.mode).toBe('on');
    expect(ev.target_per_arm).toBe(ACE_001_TARGET_PER_ARM);
    expect(ev.status).toBe('collecting');

    const a10 = ev.arms['10'];
    expect(a10.n).toBe(2); expect(a10.verified).toBe(1);
    expect(a10.verified_rate).toBeCloseTo(0.5, 3);
    expect(a10.ci).toHaveLength(2);
    expect(a10.ci![0]).toBeCloseTo(0.0945, 2);
    expect(a10.ci![1]).toBeCloseTo(0.9055, 2);
    expect(a10.graded_n).toBe(1); expect(a10.graded_mean).toBeCloseTo(0.8, 3);
    expect(a10.tokens_mean).toBe(150);

    const a00 = ev.arms['00'];
    expect(a00.n).toBe(1); expect(a00.verified).toBe(1);
    expect(a00.verified_rate).toBeCloseTo(1, 3);
    expect(a00.graded_n).toBe(0); expect(a00.graded_mean).toBeNull();
    expect(a00.tokens_mean).toBe(50);

    // empty arms stay null-valued
    for (const arm of ['01', '11'] as const) {
      expect(ev.arms[arm].n).toBe(0);
      expect(ev.arms[arm].verified_rate).toBeNull();
      expect(ev.arms[arm].ci).toBeNull();
      expect(ev.arms[arm].tokens_mean).toBeNull();
    }

    // retrieval main effect: on={10,11} p=1/2=.5 ; off={00,01} p=1/1=1 → diff -.5
    expect(ev.main_effects.retrieval.on_n).toBe(2);
    expect(ev.main_effects.retrieval.off_n).toBe(1);
    expect(ev.main_effects.retrieval.diff).toBeCloseTo(-0.5, 3);
    // examples main effect: on={01,11} has no data → diff is null
    expect(ev.main_effects.examples.on_n).toBe(0);
    expect(ev.main_effects.examples.off_n).toBe(3);
    expect(ev.main_effects.examples.diff).toBeNull();
  });
});

