        { id: 'r1', content, status: 'candidate', source_ref: null, metadata: null, created_at: '2026-01-01T00:00:00Z' },
        { id: 'r2', content: 'Loop ffffff999 closed with score 42', status: 'promoted', source_ref: null, metadata: null, created_at: '2026-01-02T00:00:00Z' },
        { id: 'r3', content: 'Completely different text here', status: 'candidate', source_ref: null, metadata: null, created_at: '2026-01-03T00:00:00Z' },
      ],
    });
    const result = findTemplateMatches(db, fp);
    expect(result).toHaveLength(2);
    expect(result.map((r) => r.id)).toEqual(['r1', 'r2']);
    expect(result[0].status).toBe('candidate');
    expect(result[1].status).toBe('promoted');
  });

  it('returns empty array when no rows match', () => {
    const db = makeDb({
      rows: [
        { id: 'x', content: 'unique text alpha', status: 'candidate', source_ref: null, metadata: null, created_at: '2026-01-01T00:00:00Z' },
      ],
    });
    const result = findTemplateMatches(db, templateFingerprint('totally unrelated')); 
    expect(result).toEqual([]);
  });

  it('returns empty array when scan returns no rows', () => {
    const db = makeDb({ rows: [] });
    expect(findTemplateMatches(db, 'abcdef0123456789')).toEqual([]);
  });
});

// ─── recordTemplateDuplicate ────────────────────────────────────────────────
describe('recordTemplateDuplicate', () => {
  function captureRun() {
    const run = vi.fn();
    const prepare = vi.fn().mockReturnValue({ run });
