      sourceRef: 'loop:run-1',
    });
    expect(run).toHaveBeenCalledTimes(1);
    const args = run.mock.calls[0];
    // arg layout: (id, subjectId, stateHash, mode, decision, reason, answersJson, createdAt)
    expect(args[1]).toBe('cand-new');
    expect(args[2]).toBe('tpl:aabbccdd00112233');
    expect(args[3]).toBe('enforce');
    expect(args[4]).toBe('skipped');
    expect(args[5]).toContain('matches 2 existing memory row(s)');
  });

  it('inserts a judgment with decision "would_skip" in shadow mode', () => {
    const { db, run } = captureRun();
    recordTemplateDuplicate(db, {
      subjectId: 'cand-x', fingerprint: 'ffeeddccbbaa9988', mode: 'shadow',
      matches: [{ id: 'only', status: 'candidate' }],
      sourceRef: null,
    });
    const args = run.mock.calls[0];
    expect(args[3]).toBe('shadow');
