// ─── recordTemplateDedupError ───────────────────────────────────────────────
describe('recordTemplateDedupError', () => {
  function makeDb(shouldThrow = false) {
    return {
      prepare: vi.fn().mockReturnValue({
        run: vi.fn(() => { if (shouldThrow) throw new Error('no table'); }),
      }),
    };
  }

  it('does not throw when the judgments insert succeeds', () => {
    const db = makeDb(false);
    expect(() => recordTemplateDedupError(db as any, {
      mode: 'shadow', stage: 'lookup', error: new Error('boom'), sourceRef: null,
    })).not.toThrow();
  });

  it('does not throw when the judgments table is absent (insert throws)', () => {
    const db = makeDb(true);
    expect(() => recordTemplateDedupError(db as any, {
      mode: 'enforce', stage: 'record', error: new Error('missing table'), sourceRef: 'loop:abc123',
    })).not.toThrow();
  });

  it('logs a warning containing the stage and mode', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    try {
      recordTemplateDedupError(makeDb() as any, {
        mode: 'shadow', stage: 'enforce', error: new Error('db down'), sourceRef: null,
      });
      expect(warn).toHaveBeenCalledTimes(1);
      expect(warn.mock.calls[0][0]).toContain('enforce');
      expect(warn.mock.calls[0][0]).toContain('shadow');
    } finally { warn.mockRestore(); }
  });

  it('stringifies non-Error values for the log message', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    try {
      recordTemplateDedupError(makeDb() as any, {
        mode: 'off', stage: 'lookup', error: 'raw string failure', sourceRef: null,
      });
      expect(warn.mock.calls[0][0]).toContain('raw string failure');
    } finally { warn.mockRestore(); }
  });

  it('uses "pending" when subjectId is omitted', () => {
    const db = makeDb(false) as any;
    recordTemplateDedupError(db, {
      mode: 'shadow', stage: 'record', error: new Error('x'), sourceRef: null,
    });
    const runArgs = db.prepare().run.mock.calls[0];
    expect(runArgs[1]).toBe('pending');
  });

  it('passes through an explicit subjectId', () => {
    const db = makeDb(false) as any;
    recordTemplateDedupError(db, {
      mode: 'enforce', stage: 'lookup', error: new Error('y'), subjectId: 'cand-42', sourceRef: null,
    });
    const runArgs = db.prepare().run.mock.calls[0];
    expect(runArgs[1]).toBe('cand-42');
  });

  it('truncates the error message to 500 chars in the judgment row', () => {
    const longMsg = 'e'.repeat(600);
    const db = makeDb(false) as any;
    recordTemplateDedupError(db, {
      mode: 'off', stage: 'lookup', error: new Error(longMsg), sourceRef: null,
    });
    const runArgs = db.prepare().run.mock.calls[0];
    // arg layout: [0]=id, [1]=subjectId/pending, [2]=mode, [3]=reason, [4]=error(msg), [5]=answers_json, [6]=created_at
    expect(runArgs[4]).toHaveLength(500);
    expect(runArgs[4]).toBe(longMsg.slice(0, 500));
  });
});

// ─── memoryTemplateAnalysis ─────────────────────────────────────────────────
describe('memoryTemplateAnalysis', () => {
  function rows(
    ...items: Array<[string, string, string, string | null, string | null, string]>
  ) {
    return items.map(([id, content, status, source_ref, metadata, created_at]) => ({
      id, content, status, source_ref, metadata, created_at,
    }));
  }

  it('groups rows by fingerprint and reports size ≥ minSize only', () => {
    const a1 = 'Loop abcdef123 closed with score 95';
    const a2 = 'Loop ffffff999 closed with score 42';
    const b1 = 'Unique text that appears once';
    const db = makeDb({
      rows: rows(
        ['r1', a1, 'candidate', null, null, '2026-01-01T00:00:00Z'],
        ['r2', a2, 'promoted', null, null, '2026-01-02T00:00:00Z'],
        ['r3', b1, 'candidate', null, null, '2026-01-03T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    expect(result.group_count).toBe(1);
    expect(result.rows_in_groups).toBe(2);
    expect(result.groups[0].size).toBe(2);
    expect(result.groups[0].ids.sort()).toEqual(['r1', 'r2']);
  });

  it('sorts groups by size descending', () => {
    // Group A: 3 rows; Group B: 2 rows
    const a = (i: number) => `Loop abc${i}def closed with score ${i}`;
    const b = (i: number) => `Run xyz${i}ghi failed at step ${i}`;
    const db = makeDb({
      rows: rows(
        ['a1', a(1), 'candidate', null, null, '2026-01-01T00:00:00Z'],
        ['a2', a(2), 'candidate', null, null, '2026-01-02T00:00:00Z'],
        ['a3', a(3), 'promoted', null, null, '2026-01-03T00:00:00Z'],
        ['b1', b(1), 'candidate', null, null, '2026-01-04T00:00:00Z'],
        ['b2', b(2), 'candidate', null, null, '2026-01-05T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    expect(result.group_count).toBe(2);
    expect(result.groups[0].size).toBe(3); // largest first
    expect(result.groups[1].size).toBe(2);
  });

  it('respects minSize option (excludes groups smaller than threshold)', () => {
    const a = (i: number) => `Loop abc${i}def closed with score ${i}`;
    const db = makeDb({
      rows: rows(
        ['a1', a(1), 'candidate', null, null, '2026-01-01T00:00:00Z'],
        ['a2', a(2), 'candidate', null, null, '2026-01-02T00:00:00Z'],
      ),
    });
    // minSize=3 → the group of 2 is excluded
    const result = memoryTemplateAnalysis(db, { minSize: 3 });
    expect(result.group_count).toBe(0);
    expect(result.rows_in_groups).toBe(0);
  });

  it('applies limit to the returned groups array', () => {
    // Distinct groups must differ by a NON-digit token (the number regex strips digits,
    // so digit-only differences would collapse into one fingerprint).
    const labels = ['Alpha', 'Beta', 'Gamma', 'Delta'];
    const mk = (label: string, i: number) => `${label} run abc${i}def scored ${i}`;
    const tuples: Array<[string, string, string, null, null, string]> = [];
    for (let g = 0; g < 4; g++) {
      for (let i = 0; i < 2; i++) {
        tuples.push(['id' + g + i, mk(labels[g], i), 'candidate', null, null, `2026-01-${String(g * 2 + i + 1).padStart(2, '0')}T00:00:00Z`]);
      }
    }
    const db = makeDb({ rows: rows(...tuples) });
    const result = memoryTemplateAnalysis(db, { limit: 2 });
    expect(result.groups).toHaveLength(2);
    // group_count still reflects ALL qualifying groups
    expect(result.group_count).toBe(4);
  });

  it('extracts source runs from metadata.loop_run_id and strips loop: prefix from source_ref', () => {
    const content = 'Loop abcdef123 closed with score 95';
    const db = makeDb({
      rows: rows(
        ['r1', content, 'candidate', 'loop:run-alpha', JSON.stringify({ loop_run_id: 'meta-run-1' }), '2026-01-01T00:00:00Z'],
        ['r2', content.replace('abcdef123', 'fffff999').replace('95', '80'), 'candidate', null, null, '2026-01-02T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    expect(result.group_count).toBe(1);
    const g = result.groups[0];
    // r1 has metadata.loop_run_id → "meta-run-1"; r2 has no run info → excluded
    expect(g.distinct_source_runs).toBe(1);
    expect(g.proposal.supporting_runs).toEqual(['meta-run-1']);
  });

  it('strips the loop: prefix from source_ref when metadata is absent', () => {
    const c1 = 'Loop abcdef123 closed with score 95';
    const c2 = 'Loop ffffff999 closed with score 42';
    const db = makeDb({
      rows: rows(
        ['r1', c1, 'candidate', 'loop:run-beta', null, '2026-01-01T00:00:00Z'],
        ['r2', c2, 'candidate', 'loop:run-gamma', null, '2026-01-02T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    const g = result.groups[0];
    expect(g.distinct_source_runs).toBe(2);
    expect(g.proposal.supporting_runs.sort()).toEqual(['run-beta', 'run-gamma']);
  });

  it('builds a proposal with applied=false and correct consolidated_text format', () => {
    const c1 = 'Loop abcdef123 closed with score 95';
    const c2 = 'Loop ffffff999 closed with score 42';
    const db = makeDb({
      rows: rows(
        ['r1', c1, 'candidate', null, null, '2026-01-01T00:00:00Z'],
        ['r2', c2, 'promoted', null, null, '2026-02-15T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    const p = result.groups[0].proposal;
    expect(p.applied).toBe(false);
    expect(p.consolidated_text).toContain('Recurring lesson (2 occurrences');
    expect(p.consolidated_text).toContain('2026-01-01 to 2026-02-15');
    expect(p.evidence_ids.sort()).toEqual(['r1', 'r2']);
  });

  it('separates promoted and candidate ids correctly', () => {
    const c1 = 'Loop abcdef123 closed with score 95';
    const c2 = 'Loop ffffff999 closed with score 42';
    const db = makeDb({
      rows: rows(
        ['p1', c1, 'promoted', null, null, '2026-01-01T00:00:00Z'],
        ['c1', c2, 'candidate', null, null, '2026-01-02T00:00:00Z'],
      ),
    });
    const result = memoryTemplateAnalysis(db);
    const g = result.groups[0];
    expect(g.promoted_ids).toEqual(['p1']);
    expect(g.candidate_ids).toEqual(['c1']);
    expect(g.by_status).toEqual({ promoted: 1, candidate: 1 });
  });

  it('reports scanned count and scan_limit', () => {
    const db = makeDb({
      rows: [
        { id: 'x', content: 'a b c', status: 'candidate', source_ref: null, metadata: null, created_at: '2026-01-01T00:00:00Z' },
        { id: 'y', content: 'd e f', status: 'candidate', source_ref: null, metadata: null, created_at: '2026-01-02T00:00:00Z' },
      ],
    });
    const result = memoryTemplateAnalysis(db);
    expect(result.scanned).toBe(2);
    expect(result.scan_limit).toBe(5000);
  });

  it('handles empty database gracefully (no groups)', () => {
    const db = makeDb({ rows: [] });
    const result = memoryTemplateAnalysis(db);
    expect(result.group_count).toBe(0);
    expect(result.groups).toEqual([]);
    expect(result.rows_in_groups).toBe(0);
  });

  it('does not throw when scan fails (table absent)', () => {
    const db = makeDb({ shouldThrowOnAll: true, shouldThrowOnGet: true });
    expect(() => memoryTemplateAnalysis(db)).not.toThrow();
    const result = memoryTemplateAnalysis(db);
    expect(result.scanned).toBe(0);
    expect(result.group_count).toBe(0);
  });
});

