// ─── canonicalJson ────────────────────────────────────────────────────────────
describe('canonicalJson', () => {
  it('sorts object keys recursively and emits no whitespace', () => {
    const input = { b: 1, a: [{ z: 0, y: 'x' }], c: null, d: true, e: 'héllo', f: 3.5 };
    expect(canonicalJson(input)).toBe('{"a":[{"y":"x","z":0}],"b":1,"c":null,"d":true,"e":"héllo","f":3.5}');
  });
  it('preserves array element order (does not sort arrays)', () => {
    expect(canonicalJson([3, 1, 2])).toBe('[3,1,2]');
  });
  it('handles empty objects and arrays', () => {
    expect(canonicalJson({})).toBe('{}');
    expect(canonicalJson([])).toBe('[]');
  });
  it('serialises primitives via JSON.stringify (strings get quotes, numbers bare)', () => {
    expect(canonicalJson('hello')).toBe('"hello"');
    expect(canonicalJson(42)).toBe('42');
    expect(canonicalJson(null)).toBe('null');
    expect(canonicalJson(true)).toBe('true');
  });
  it('escapes special characters in strings per JSON rules', () => {
    expect(canonicalJson({ s: 'a\nb"c' })).toBe('{"s":"a\\nb\\"c"}');
  });
  it('produces the same output regardless of insertion key order', () => {
    const a = canonicalJson({ x: 1, y: 2, z: 3 });
    const b = canonicalJson({ z: 3, x: 1, y: 2 });
    expect(a).toBe(b);
  });
});

// ─── fleetSignedBody ──────────────────────────────────────────────────────────
describe('fleetSignedBody', () => {
  it('produces the exact canonical JSON with sorted keys and computed payload_sha256 (golden)', () => {
    // All four optional payload fields present as strings (Redis bus form)
    const event = {
      agent: 'agent-x',
      event_id: 'evt-abc123',
      host: 'host-1',
      success: true,
      task_kind: 'build',
      occurred_at: '2026-10-22T12:00:00Z',
      duration_ms: '1200',
      model: 'gpt-4o-mini',
      ref: 'task/42',
      tokens: '87',
    };
    // Expected payload_sha256: sha256 of canonicalJson({duration_ms:"1200",model:"gpt-4o-mini",ref:"task/42",tokens:"87"})
    const expectedPsha = createHash('sha256').update('{"duration_ms":"1200","model":"gpt-4o-mini","ref":"task/42","tokens":"87"}', 'utf8').digest('hex');
    expect(expectedPsha).toBe('e3469170128d7548f95b81b665ce41aef54bbb5c71b17904826cc9bb2dde521c');

    const body = fleetSignedBody(event);
    expect(body).toBe(
      '{"agent":"agent-x","event_id":"evt-abc123","host":"host-1","payload_sha256":"' + expectedPsha + '","success":true,"task_kind":"build","ts":"2026-10-22T12:00:00Z"}',
    );
  });

  it('includes only the present optional payload fields (omits undefined/null)', () => {
    const event = {
      agent: 'a', event_id: 'e1', host: 'h', success: false, task_kind: 't',
      occurred_at: '2026-01-01T00:00:00Z', duration_ms: '100', model: null,
    };
    // Only duration_ms is present and non-null → payload = {duration_ms:"100"}
    const expectedPsha = createHash('sha256').update('{"duration_ms":"100"}', 'utf8').digest('hex');
    const body = fleetSignedBody(event);
    expect(body).toContain(`"payload_sha256":"${expectedPsha}"`);
    // The signed body itself must NOT contain a "model" key at top level
    expect(body).not.toContain('"model"');
  });

  it('stringifies numeric/boolean payload field values to their string form', () => {
    const event = {
      agent: 'a', event_id: 'e2', host: 'h', success: true, task_kind: 't',
      occurred_at: '2026-01-01T00:00:00Z', tokens: 999,
    };
    // tokens=999 (number) should be String(999)="999"
    const expectedPsha = createHash('sha256').update('{"tokens":"999"}', 'utf8').digest('hex');
    const body = fleetSignedBody(event);
    expect(body).toContain(`"payload_sha256":"${expectedPsha}"`);
  });

  it('coerces success to boolean true/false and omits when unrecognised', () => {
    const evTrue = { agent: 'a', event_id: 'e3', host: 'h', success: 'true', task_kind: 't', occurred_at: '2026-01-01T00:00:00Z' };
    const bodyTrue = fleetSignedBody(evTrue);
    expect(bodyTrue).toContain('"success":true');

    const evFalse = { agent: 'a', event_id: 'e4', host: 'h', success: 'false', task_kind: 't', occurred_at: '2026-01-01T00:00:00Z' };
    const bodyFalse = fleetSignedBody(evFalse);
    expect(bodyFalse).toContain('"success":false');

    // Unrecognised success → null in JSON
    const evNull = { agent: 'a', event_id: 'e5', host: 'h', success: 'maybe', task_kind: 't', occurred_at: '2026-01-01T00:00:00Z' };
    const bodyNull = fleetSignedBody(evNull);
    expect(bodyNull).toContain('"success":null');
  });

  it('defaults missing required fields to empty string', () => {
    const event = { occurred_at: '2026-01-01T00:00:00Z' }; // no agent, event_id, host, etc.
    const body = fleetSignedBody(event);
    expect(body).toContain('"agent":""');
    expect(body).toContain('"event_id":""');
    expect(body).toContain('"host":""');
    expect(body).toContain('"task_kind":""');
    expect(body).toContain('"ts":"2026-01-01T00:00:00Z"');
  });
});

// ─── deriveFleetHmacKey ───────────────────────────────────────────────────────
describe('deriveFleetHmacKey', () => {
  it('returns the exact base64url HMAC-SHA256(master, "fleet-event-key|v1|<host>|<keyId>") (golden)', () => {
    const expected = createHmac('sha256', 'test-master-secret').update('fleet-event-key|v1|host-1|deadbeef').digest('base64url');
    expect(expected).toBe('mofkmJj0bRT5hpKIl2HUGcGACzuCBcyPfzQATPktPBQ');
    expect(deriveFleetHmacKey('test-master-secret', 'host-1', 'deadbeef')).toBe(expected);
  });
  it('produces different keys for different hosts or key ids', () => {
    const a = deriveFleetHmacKey('m', 'host-a', 'aaaaaaaa');
    const b = deriveFleetHmacKey('m', 'host-b', 'aaaaaaaa');
    const c = deriveFleetHmacKey('m', 'host-a', 'bbbbbbbb');
    expect(a).not.toBe(b);
    expect(a).not.toBe(c);
    expect(b).not.toBe(c);
  });
  it('is deterministic: same inputs → same key', () => {
    expect(deriveFleetHmacKey('m', 'h', '1234abcd')).toBe(deriveFleetHmacKey('m', 'h', '1234abcd'));
  });
  it('changes when the master secret changes (rotation invalidates fleet keys)', () => {
    expect(deriveFleetHmacKey('master-1', 'h', 'k')).not.toBe(deriveFleetHmacKey('master-2', 'h', 'k'));
  });
});

// ─── signFleetEventHmac ───────────────────────────────────────────────────────
