// ─── ensureFleetSignatureTables ───────────────────────────────────────────────
describe('ensureFleetSignatureTables', () => {
  it('creates fleet_event_keys, fleet_event_nonces and fleet_event_signatures tables', () => {
    ensureFleetSignatureTables(db);
    const tables = db.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('fleet_event_keys','fleet_event_nonces','fleet_event_signatures') ORDER BY name",
    ).all() as Array<{ name: string }>;
    expect(tables.map((t) => t.name)).toEqual(['fleet_event_keys', 'fleet_event_nonces', 'fleet_event_signatures']);
  });
  it('creates idx_fleet_event_nonces_seen on fleet_event_nonces(seen_at)', () => {
    ensureFleetSignatureTables(db);
    const idx = db.prepare("SELECT name FROM sqlite_master WHERE type='index' AND name='idx_fleet_event_nonces_seen'").get();
    expect(idx).toBeDefined();
  });
  it('is idempotent (calling twice does not throw or duplicate tables)', () => {
    expect(() => { ensureFleetSignatureTables(db); ensureFleetSignatureTables(db); }).not.toThrow();
    const count = db.prepare("SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table' AND name='fleet_event_signatures'").get() as { n: number };
    expect(count.n).toBe(1);
  });
  it('makes fleet_event_signatures.event_id the primary key (duplicate inserts ignored)', () => {
    ensureFleetSignatureTables(db);
    const info = db.prepare('PRAGMA table_info(fleet_event_signatures)').all() as Array<{ name: string; pk: number }>;
    const eventId = info.find((c) => c.name === 'event_id');
    expect(eventId?.pk).toBeGreaterThan(0);
  });
  it('makes fleet_event_keys composite PK on (host, key_id)', () => {
    ensureFleetSignatureTables(db);
    const info = db.prepare('PRAGMA table_info(fleet_event_keys)').all() as Array<{ name: string; pk: number }>;
    const hostPk = info.find((c) => c.name === 'host')?.pk ?? 0;
    const keyIdPk = info.find((c) => c.name === 'key_id')?.pk ?? 0;
    expect(hostPk).toBeGreaterThan(0);
    expect(keyIdPk).toBeGreaterThan(0);
  });
});

// ─── registerFleetHostKey ─────────────────────────────────────────────────────
describe('registerFleetHostKey', () => {
  it('registers an hmac-sha256 key and returns a 16-char hex key_id plus derived secret', () => {
    const master = 'my-master';
    const res = registerFleetHostKey(db, 'host-1', { alg: 'hmac-sha256', master });
    expect(res.host).toBe('host-1');
    expect(res.alg).toBe('hmac-sha256');
    expect(res.key_id).toMatch(/^[a-f0-9]{16}$/); // randomBytes(8).toString('hex')
    expect(res.secret).toBeDefined();
    expect(res.secret).toBe(deriveFleetHmacKey(master, 'host-1', res.key_id));

    const row = db.prepare('SELECT * FROM fleet_event_keys WHERE host=? AND key_id=?').get('host-1', res.key_id) as Record<string, unknown>;
    expect(row.status).toBe('active');
    expect(row.public_key).toBeNull();
    expect(typeof row.created_at).toBe('string');
  });

  it('rejects invalid host names (throws FLEET_HOST_INVALID)', () => {
    expect(() => registerFleetHostKey(db, 'bad host!')).toThrow('FLEET_HOST_INVALID');
    expect(() => registerFleetHostKey(db, '')).toThrow('FLEET_HOST_INVALID');
  });

  it('requires a public key for ed25519 and validates the algorithm', () => {
    expect(() => registerFleetHostKey(db, 'h1', { alg: 'ed25519' })).toThrow('FLEET_PUBLIC_KEY_REQUIRED');
    // A non-ed25519 PEM should be rejected
    const rsaPair = generateKeyPairSync('rsa', { modulusLength: 2048, publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    expect(() => registerFleetHostKey(db, 'h1', { alg: 'ed25519', publicKey: rsaPair.publicKey })).toThrow('FLEET_PUBLIC_KEY_NOT_ED25519');
  });

  it('stores an ed25519 public key in the registry (no secret returned)', () => {
    const pair = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const res = registerFleetHostKey(db, 'host-ed', { alg: 'ed25519', publicKey: pair.publicKey });
    expect(res.alg).toBe('ed25519');
    expect(res.secret).toBeUndefined();
    const row = db.prepare('SELECT public_key FROM fleet_event_keys WHERE host=? AND key_id=?').get('host-ed', res.key_id) as { public_key: string };
    expect(row.public_key).toBe(pair.publicKey);
  });
});

// ─── revokeFleetHostKey ───────────────────────────────────────────────────────
describe('revokeFleetHostKey', () => {
  it('revokes a specific key and returns count=1', () => {
    const r1 = registerFleetHostKey(db, 'h1', { master: 'm' });
    const r2 = registerFleetHostKey(db, 'h1', { master: 'm' });
    const n = revokeFleetHostKey(db, 'h1', r1.key_id, 1000);
    expect(n).toBe(1);
    const row1 = db.prepare("SELECT status, revoked_at FROM fleet_event_keys WHERE host='h1' AND key_id=?").get(r1.key_id) as Record<string, unknown>;
    expect(row1.status).toBe('revoked');
    expect(row1.revoked_at).toBe(new Date(1000).toISOString());
    // The other key is still active
    const row2 = db.prepare("SELECT status FROM fleet_event_keys WHERE host='h1' AND key_id=?").get(r2.key_id) as { status: string };
    expect(row2.status).toBe('active');
  });

  it('revokes ALL active keys of a host when keyId is omitted', () => {
    registerFleetHostKey(db, 'h2', { master: 'm' });
    registerFleetHostKey(db, 'h2', { master: 'm' });
    const n = revokeFleetHostKey(db, 'h2', undefined, 2000);
    expect(n).toBe(2);
    const remaining = db.prepare("SELECT COUNT(*) AS n FROM fleet_event_keys WHERE host='h2' AND status='active'").get() as { n: number };
    expect(remaining.n).toBe(0);
  });

  it('returns 0 when no active keys match (already revoked or unknown)', () => {
    const r = registerFleetHostKey(db, 'h3', { master: 'm' });
    revokeFleetHostKey(db, 'h3', r.key_id);
    expect(revokeFleetHostKey(db, 'h3', r.key_id)).toBe(0);
    expect(revokeFleetHostKey(db, 'nonexistent-host')).toBe(0);
  });
});

// ─── verifyFleetEvent ─────────────────────────────────────────────────────────
describe('verifyFleetEvent', () => {
  const MASTER = 'test-master';
  const NOW = Date.parse('2026-10-22T12:00:00Z');

  function makeHmacEvent(overrides: Record<string, unknown> = {}): Record<string, unknown> {
    return {
      agent: 'agent-x', event_id: 'evt-vfy-1', host: 'host-1', success: true,
      task_kind: 'build', occurred_at: new Date(NOW).toISOString(), sig_alg: 'hmac-sha256', ...overrides,
    };
  }

  it('returns "unsigned" when no signature is present (never throws)', () => {
    ensureFleetSignatureTables(db);
    const v = verifyFleetEvent(db, { agent: 'a', event_id: 'e', host: 'h' }, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('unsigned');
    expect(v.host).toBe('h'); // 'h' matches HOST_RE
    expect(v.key_id).toBeNull(); // no key_id field
  });

  it('returns "unknown_host" when sig is present but host/key_id are missing or invalid', () => {
    ensureFleetSignatureTables(db);
    const v = verifyFleetEvent(db, makeHmacEvent({ sig: 'abc', host: undefined }), { master: MASTER, now: NOW });
    expect(v.verdict).toBe('unknown_host');
  });

  it('returns "unknown_host" when the (host,key_id) pair is not in the registry', () => {
    ensureFleetSignatureTables(db);
    const ev = makeHmacEvent({ sig: 'fakesig', host: 'ghost-host', key_id: 'aaaaaaaa' });
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('unknown_host');
    expect(v.host).toBe('ghost-host');
    expect(v.key_id).toBe('aaaaaaaa');
  });

  it('returns "revoked" for a revoked key even if the signature would otherwise verify', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-rev', { master: MASTER });
    revokeFleetHostKey(db, 'h-rev', reg.key_id, NOW);
    const ev = makeHmacEvent({ host: 'h-rev', key_id: reg.key_id, event_id: 'evt-rev-1' });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-rev', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('revoked');
  });

  it('returns "bad_signature" when the HMAC does not match (tampered body)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-bad', { master: MASTER });
    const ev = makeHmacEvent({ host: 'h-bad', key_id: reg.key_id, event_id: 'evt-bad-1' });
    // Sign with a different key → mismatch
    ev.sig = createHmac('sha256', 'wrong-key').update(fleetSignedBody(ev), 'utf8').digest('base64url');
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('bad_signature');
  });

  it('returns "bad_signature" when sig_alg mismatches the registered algorithm', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-alg', { master: MASTER }); // hmac-sha256
    const ev = makeHmacEvent({ host: 'h-alg', key_id: reg.key_id, event_id: 'evt-alg-1', sig_alg: 'ed25519' });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-alg', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('bad_signature');
  });

  it('returns "bad_signature" when event_id is missing (cannot be replay-protected)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-noid', { master: MASTER });
    const ev = makeHmacEvent({ host: 'h-noid', key_id: reg.key_id, event_id: '' });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-noid', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('bad_signature');
  });

  it('returns "replay" when the timestamp is outside the 24 h window', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-old', { master: MASTER });
    const oldTs = new Date(NOW - FLEET_EVENT_WINDOW_MS - 1000).toISOString(); // just past the window
    const ev = makeHmacEvent({ host: 'h-old', key_id: reg.key_id, event_id: 'evt-old-1', occurred_at: oldTs });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-old', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('replay');
  });

  it('accepts a timestamp exactly at the window boundary (|now-ts| == WINDOW)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-edge', { master: MASTER });
    const edgeTs = new Date(NOW - FLEET_EVENT_WINDOW_MS).toISOString(); // exactly at boundary
    const ev = makeHmacEvent({ host: 'h-edge', key_id: reg.key_id, event_id: 'evt-edge-1', occurred_at: edgeTs });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-edge', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    // Math.abs(now - ts) > WINDOW → at exact boundary abs == WINDOW which is NOT > WINDOW → passes
    expect(v.verdict).toBe('verified');
  });

  it('returns "verified" for a correctly signed fresh event and records the nonce', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-ok', { master: MASTER });
    const ev = makeHmacEvent({ host: 'h-ok', key_id: reg.key_id, event_id: 'evt-ok-1' });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-ok', reg.key_id), ev);
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v).toEqual({ verdict: 'verified', host: 'h-ok', key_id: reg.key_id });
    // Nonce was consumed
    const nonce = db.prepare('SELECT * FROM fleet_event_nonces WHERE event_id=?').get('evt-ok-1') as Record<string, unknown>;
    expect(nonce).toBeDefined();
    expect(nonce.host).toBe('h-ok');
    expect(nonce.seen_at).toBe(NOW);
  });

  it('returns "replay" when the same event_id is verified twice (nonce already consumed)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-rp', { master: MASTER });
    const ev = makeHmacEvent({ host: 'h-rp', key_id: reg.key_id, event_id: 'evt-rp-1' });
    ev.sig = signFleetEventHmac(deriveFleetHmacKey(MASTER, 'h-rp', reg.key_id), ev);
    const v1 = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v1.verdict).toBe('verified');
    const v2 = verifyFleetEvent(db, ev, { master: MASTER, now: NOW + 5000 });
    expect(v2.verdict).toBe('replay');
  });

  it('does NOT consume the nonce for a bad_signature event (only verified events do)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-nonce', { master: MASTER });
    const ev = makeHmacEvent({ host: 'h-nonce', key_id: reg.key_id, event_id: 'evt-nonce-1' });
    // Deliberately wrong signature
    ev.sig = 'not-a-valid-sig';
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('bad_signature');
    // Nonce must NOT have been inserted
    const nonce = db.prepare('SELECT * FROM fleet_event_nonces WHERE event_id=?').get('evt-nonce-1');
    expect(nonce).toBeUndefined();
  });

  it('verifies an ed25519-signed event end-to-end', () => {
    ensureFleetSignatureTables(db);
    const pair = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const reg = registerFleetHostKey(db, 'h-ed', { alg: 'ed25519', publicKey: pair.publicKey });
    const ev = makeHmacEvent({ host: 'h-ed', key_id: reg.key_id, event_id: 'evt-ed-1', sig_alg: 'ed25519' });
    const body = fleetSignedBody(ev);
    const sigBuf = cryptoSign(null, Buffer.from(body, 'utf8'), pair.privateKey);
    ev.sig = sigBuf.toString('base64url');
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('verified');
  });

  it('returns "bad_signature" for a tampered ed25519 signature', () => {
    ensureFleetSignatureTables(db);
    const pair = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const reg = registerFleetHostKey(db, 'h-ed2', { alg: 'ed25519', publicKey: pair.publicKey });
    // Sign with a DIFFERENT key pair → verification must fail
    const otherPair = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const ev = makeHmacEvent({ host: 'h-ed2', key_id: reg.key_id, event_id: 'evt-ed2-1', sig_alg: 'ed25519' });
    const body = fleetSignedBody(ev);
    const sigBuf = cryptoSign(null, Buffer.from(body, 'utf8'), otherPair.privateKey);
    ev.sig = sigBuf.toString('base64url');
    const v = verifyFleetEvent(db, ev, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('bad_signature');
  });

  it('handles an event with non-string sig gracefully (treats as empty → unsigned)', () => {
    ensureFleetSignatureTables(db);
    const v = verifyFleetEvent(db, { agent: 'a', event_id: 'e', host: 'h', sig: 12345 }, { master: MASTER, now: NOW });
    expect(v.verdict).toBe('unsigned');
  });
});

// ─── recordFleetVerdict ───────────────────────────────────────────────────────
describe('recordFleetVerdict', () => {
  const mkVerdict = (over: Partial<FleetVerification> = {}): FleetVerification => ({
    verdict: 'verified', host: 'host-1', key_id: 'deadbeef', ...over,
  });

  it('inserts a row with all fields and an ISO timestamp', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2024-06-01T00:00:00Z');
    recordFleetVerdict(db, 'evt-1', mkVerdict(), 'shadow', now);
    const row = db.prepare('SELECT * FROM fleet_event_signatures WHERE event_id=?').get('evt-1') as Record<string, unknown>;
    expect(row).toEqual({
      event_id: 'evt-1', host: 'host-1', key_id: 'deadbeef',
      verdict: 'verified', mode: 'shadow', at: new Date(now).toISOString(),
    });
  });

  it('persists null host/key_id for unsigned or unknown_host verdicts', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'evt-2', mkVerdict({ verdict: 'unsigned', host: null, key_id: null }), 'off');
    const row = db.prepare('SELECT host, key_id, verdict, mode FROM fleet_event_signatures WHERE event_id=?').get('evt-2') as Record<string, unknown>;
    expect(row).toEqual({ host: null, key_id: null, verdict: 'unsigned', mode: 'off' });
  });

  it('uses INSERT OR IGNORE so a second write does not overwrite the first verdict', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2024-06-01T00:00:00Z');
    recordFleetVerdict(db, 'evt-3', mkVerdict({ verdict: 'verified' }), 'shadow', now);
    recordFleetVerdict(db, 'evt-3', mkVerdict({ verdict: 'bad_signature' }), 'enforce', now + 1000);
    const rows = db.prepare('SELECT verdict, mode FROM fleet_event_signatures WHERE event_id=?').all('evt-3') as Array<Record<string, string>>;
    expect(rows).toEqual([{ verdict: 'verified', mode: 'shadow' }]);
  });

  it('stores distinct rows for distinct event ids', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'a', mkVerdict(), 'shadow');
    recordFleetVerdict(db, 'b', mkVerdict({ verdict: 'replay', host: 'host-2', key_id: 'cafef00d' }), 'enforce');
    const rows = db.prepare('SELECT event_id, verdict, host FROM fleet_event_signatures ORDER BY event_id').all() as Array<Record<string, string | null>>;
    expect(rows).toEqual([
      { event_id: 'a', verdict: 'verified', host: 'host-1' },
      { event_id: 'b', verdict: 'replay', host: 'host-2' },
    ]);
  });

  it('throws when the table does not exist', () => {
    expect(() => recordFleetVerdict(db, 'evt-x', mkVerdict(), 'shadow')).toThrow();
  });
});

// ─── pruneFleetNonces ─────────────────────────────────────────────────────────
describe('pruneFleetNonces', () => {
  it('deletes nonces older than 2×window and keeps recent ones; returns count deleted', () => {
    ensureFleetSignatureTables(db);
    const now = Date.parse('2026-10-22T12:00:00Z');
    // Insert three nonces at different ages
    db.prepare('INSERT INTO fleet_event_nonces (event_id, host, seen_at) VALUES (?, ?, ?)').run('old-1', 'h', now - 3 * FLEET_EVENT_WINDOW_MS);
    db.prepare('INSERT INTO fleet_event_nonces (event_id, host, seen_at) VALUES (?, ?, ?)').run('mid-1', 'h', now - 1.5 * FLEET_EVENT_WINDOW_MS);
    db.prepare('INSERT INTO fleet_event_nonces (event_id, host, seen_at) VALUES (?, ?, ?)').run('recent-1', 'h', now - 1000);

    const deleted = pruneFleetNonces(db, now);
    expect(deleted).toBe(1); // only old-1 is past 2×window

    const remaining = db.prepare('SELECT event_id FROM fleet_event_nonces ORDER BY event_id').all() as Array<{ event_id: string }>;
    expect(remaining.map((r) => r.event_id)).toEqual(['mid-1', 'recent-1']);
  });

  it('returns 0 when there are no nonces to prune', () => {
    ensureFleetSignatureTables(db);
    expect(pruneFleetNonces(db, Date.now())).toBe(0);
  });
});

// ─── fleetSignatureEvidence ───────────────────────────────────────────────────
describe('fleetSignatureEvidence', () => {
  it('returns mode from env and null by_host/keys when tables are absent', () => {
    const ev = fleetSignatureEvidence(db, { FLEET_EVENT_SIGNATURES: 'shadow' });
    expect(ev.mode).toBe('shadow');
    expect(ev.by_host).toBeNull();
    expect(ev.keys).toBeNull();
  });

  it('aggregates verdict counts per host and lists keys (no secrets)', () => {
    ensureFleetSignatureTables(db);
    const reg = registerFleetHostKey(db, 'h-ev', { master: 'm' });
    recordFleetVerdict(db, 'e1', { verdict: 'verified', host: 'h-ev', key_id: reg.key_id }, 'enforce');
    recordFleetVerdict(db, 'e2', { verdict: 'bad_signature', host: 'h-ev', key_id: reg.key_id }, 'enforce');
    recordFleetVerdict(db, 'e3', { verdict: 'unsigned', host: null, key_id: null }, 'off');

    const ev = fleetSignatureEvidence(db, {});
    expect(ev.mode).toBe('off');
    // by_host should have entries for h-ev (verified=1, bad_signature=1) and (none) (unsigned=1)
    expect(Array.isArray(ev.by_host)).toBe(true);
    const hosts = (ev.by_host as Array<{ host: string; verdict: string; n: number }>).map((r) => `${r.host}:${r.verdict}=${r.n}`).sort();
    expect(hosts).toContain('h-ev:bad_signature=1');
    expect(hosts).toContain('h-ev:verified=1');
    expect(hosts).toContain('(none):unsigned=1');

    // keys list includes the registered key with no secret field
    expect(Array.isArray(ev.keys)).toBe(true);
    const k = (ev.keys as Array<Record<string, unknown>>)[0];
    expect(k.host).toBe('h-ev');
    expect(k.key_id).toBe(reg.key_id);
    expect(k.alg).toBe('hmac-sha256');
    expect(k.status).toBe('active');
    expect(k).not.toHaveProperty('secret');
  });

  it('respects the since filter on fleet_event_signatures.at', () => {
    ensureFleetSignatureTables(db);
    recordFleetVerdict(db, 'old-e', { verdict: 'verified', host: 'h', key_id: null }, 'off', Date.parse('2024-01-01T00:00:00Z'));
    recordFleetVerdict(db, 'new-e', { verdict: 'verified', host: 'h', key_id: null }, 'off', Date.parse('2026-01-01T00:00:00Z'));

    const ev = fleetSignatureEvidence(db, {}, '2025-01-01T00:00:00.000Z');
    expect(Array.isArray(ev.by_host)).toBe(true);
    const rows = ev.by_host as Array<{ host: string; n: number }>;
    // Only new-e should be included (at >= 2025-01-01)
    expect(rows.reduce((s, r) => s + r.n, 0)).toBe(1);
  });
});

