import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import Database from 'better-sqlite3';
import {
  autoFailoverMode,
  panelFallbackRuntime,
  panelFallbackModel,
  PANEL_FALLBACK_PREFIX,
  limitWatching,
  ollamaLimitClass,
  limitMarker,
  notPanelFallbackReviewSql,
  readOllamaLimit,
  noteOllamaOutput,
  clearOllamaLimit,
  probeModel,
  recordLimitCalibration,
  PROBE_INTERVAL_MS,
  probeOllama,
} from '../services/inference-failover';
import type { OllamaLimitState } from '../services/inference-failover';

let db: InstanceType<typeof Database>;
beforeEach(() => {
  db = new Database(':memory:');
  // keep the module's console noise out of test output without changing behaviour
  vi.spyOn(console, 'warn').mockImplementation(() => {});
  vi.spyOn(console, 'log').mockImplementation(() => {});
});
afterEach(() => {
  db.close();
  vi.restoreAllMocks();
});

describe('env parsing', () => {
  it('autoFailoverMode is on only for a trimmed lowercase "on"', () => {
    expect(autoFailoverMode({ OLLAMA_AUTO_FAILOVER: 'on' })).toBe('on');
    expect(autoFailoverMode({ OLLAMA_AUTO_FAILOVER: 'ON' })).toBe('on');
    expect(autoFailoverMode({ OLLAMA_AUTO_FAILOVER: '  on  ' })).toBe('on');
    expect(autoFailoverMode({ OLLAMA_AUTO_FAILOVER: 'off' })).toBe('off');
    expect(autoFailoverMode({ OLLAMA_AUTO_FAILOVER: undefined })).toBe('off');
    expect(autoFailoverMode({})).toBe('off');
  });
  it('panelFallbackRuntime is claude only for a trimmed lowercase "claude"', () => {
    expect(panelFallbackRuntime({ PANEL_FALLBACK_RUNTIME: 'claude' })).toBe('claude');
    expect(panelFallbackRuntime({ PANEL_FALLBACK_RUNTIME: 'Claude' })).toBe('claude');
    expect(panelFallbackRuntime({ PANEL_FALLBACK_RUNTIME: 'ollama' })).toBeNull();
    expect(panelFallbackRuntime({})).toBeNull();
  });
  it('panelFallbackModel defaults to haiku and honours the override', () => {
    expect(panelFallbackModel({})).toBe('haiku');
    expect(panelFallbackModel({ PANEL_FALLBACK_MODEL: 'sonnet' })).toBe('sonnet');
    expect(panelFallbackModel({ PANEL_FALLBACK_MODEL: '  opus  ' })).toBe('opus');
  });
  it('limitWatching is true when either flag needs the limit surfaced', () => {
    expect(limitWatching({ OLLAMA_AUTO_FAILOVER: 'on' })).toBe(true);
    expect(limitWatching({ PANEL_FALLBACK_RUNTIME: 'claude' })).toBe(true);
    expect(limitWatching({ OLLAMA_AUTO_FAILOVER: 'off', PANEL_FALLBACK_RUNTIME: 'claude' })).toBe(true);
    expect(limitWatching({})).toBe(false);
  });
});

describe('notPanelFallbackReviewSql', () => {
  it('returns a COALESCE NOT LIKE fragment for the given alias', () => {
    expect(notPanelFallbackReviewSql('r')).toBe(
      `COALESCE(r.model, '') NOT LIKE '${PANEL_FALLBACK_PREFIX}%'`,
    );
  });
  it('uses the claude: prefix constant', () => {
    const sql = notPanelFallbackReviewSql('review');
    expect(sql).toContain("NOT LIKE 'claude:%'");
  });
  it('embeds the alias verbatim in the SQL', () => {
    expect(notPanelFallbackReviewSql('x')).toContain('x.model');
  });
});

describe('limitMarker', () => {
  it('wraps each LimitClass in [ollama_usage_limit:<cls>]', () => {
    expect(limitMarker('weekly')).toBe('[ollama_usage_limit:weekly]');
    expect(limitMarker('session')).toBe('[ollama_usage_limit:session]');
    expect(limitMarker('daily')).toBe('[ollama_usage_limit:daily]');
    expect(limitMarker('hourly')).toBe('[ollama_usage_limit:hourly]');
    expect(limitMarker('monthly')).toBe('[ollama_usage_limit:monthly]');
    expect(limitMarker('usage')).toBe('[ollama_usage_limit:usage]');
  });
});

describe('ollamaLimitClass', () => {
  it('reads the bracketed marker class (capture group 1)', () => {
    expect(ollamaLimitClass('[ollama_usage_limit:daily] failed')).toBe('daily');
    expect(ollamaLimitClass('prefix [ollama_usage_limit:hourly] suffix')).toBe('hourly');
  });
  it('reads the bare "<class> usage limit" phrase (capture group 2)', () => {
    expect(ollamaLimitClass('you hit your session usage limit today')).toBe('session');
    expect(ollamaLimitClass('Monthly Usage Limit reached')).toBe('monthly');
  });
  it('reads the "reached your <class> usage limit" phrase (capture group 3)', () => {
    expect(ollamaLimitClass('you have reached your weekly usage limit, add usage credits')).toBe('weekly');
    expect(ollamaLimitClass('Reached Your Daily Usage Limit')).toBe('daily');
  });
  it('falls back to the generic usage class when no specific window is named', () => {
    expect(ollamaLimitClass('you have reached your usage limit')).toBe('usage');
    expect(ollamaLimitClass('please add usage credits to continue')).toBe('usage');
  });
  it('is case-insensitive and returns null for non-limit errors', () => {
    expect(ollamaLimitClass('[OLLAMA_USAGE_LIMIT:WEEKLY]')).toBe('weekly');
    expect(ollamaLimitClass('connection refused by host')).toBeNull();
    expect(ollamaLimitClass(null)).toBeNull();
    expect(ollamaLimitClass(undefined)).toBeNull();
    expect(ollamaLimitClass('')).toBeNull();
  });
});

describe('readOllamaLimit', () => {
  const KEY = 'inference_ollama_state';
  it('returns null on an empty database (no table)', () => {
    expect(readOllamaLimit(db)).toBeNull();
  });
  it('returns the persisted state for a valid limited row', () => {
    db.exec(`CREATE TABLE system_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)`);
    const s: OllamaLimitState = { state: 'ollama_limited', detected_at: '2026-10-01T00:00:00.000Z', error_class: 'weekly', source: 's', excerpt: 'e' };
    db.prepare('INSERT INTO system_state (key, value) VALUES (?, ?)').run(KEY, JSON.stringify(s));
    expect(readOllamaLimit(db)).toEqual(s);
  });
  it('returns null when the stored state is not ollama_limited', () => {
    db.exec(`CREATE TABLE system_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)`);
    db.prepare('INSERT INTO system_state (key, value) VALUES (?, ?)').run(KEY, JSON.stringify({ state: 'other' }));
    expect(readOllamaLimit(db)).toBeNull();
  });
  it('returns null on malformed JSON instead of throwing', () => {
    db.exec(`CREATE TABLE system_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)`);
    db.prepare('INSERT INTO system_state (key, value) VALUES (?, ?)').run(KEY, '{not json');
    expect(() => readOllamaLimit(db)).not.toThrow();
    expect(readOllamaLimit(db)).toBeNull();
  });
});

describe('noteOllamaOutput', () => {
  const ON = { OLLAMA_AUTO_FAILOVER: 'on' };
  const OFF = { OLLAMA_AUTO_FAILOVER: 'off' };

  it('classifies but does not persist while auto-failover is off', () => {
    expect(noteOllamaOutput(db, 'reached your weekly usage limit', 'src', OFF, new Date())).toBe('weekly');
    expect(readOllamaLimit(db)).toBeNull();
  });
  it('returns the class without a database and never throws', () => {
    expect(() => noteOllamaOutput(null, 'reached your weekly usage limit', 'src', ON, new Date())).not.toThrow();
    expect(noteOllamaOutput(undefined, 'add usage credits', 'src', ON, new Date())).toBe('usage');
  });
  it('persists the limited state on first detection with detected_at from now()', () => {
    const now = new Date('2026-10-01T00:00:00.000Z');
    expect(noteOllamaOutput(db, 'you have reached your weekly usage limit', 'opencode-lease', ON, now)).toBe('weekly');
    const s = readOllamaLimit(db)!;
    expect(s.state).toBe('ollama_limited');
    expect(s.error_class).toBe('weekly');
    expect(s.detected_at).toBe(now.toISOString());
    expect(s.source).toBe('opencode-lease');
    expect(s.excerpt).toContain('usage limit');
  });
  it('truncates the source to 80 characters', () => {
    noteOllamaOutput(db, 'reached your weekly usage limit', 'x'.repeat(200), ON, new Date());
    expect(readOllamaLimit(db)!.source).toHaveLength(80);
  });
  it('leaves the persisted state entirely unchanged on later detections (early return)', () => {
    noteOllamaOutput(db, 'reached your weekly usage limit', 'first-source', ON, new Date('2026-10-01T00:00:00.000Z'));
    const before = readOllamaLimit(db)!;
    // a second detection while already limited must not rewrite any field
    noteOllamaOutput(db, 'reached your session usage limit', 'second-source', ON, new Date('2026-10-05T00:00:00.000Z'));
    const after = readOllamaLimit(db)!;
    expect(after).toEqual(before);
    expect(after.detected_at).toBe('2026-10-01T00:00:00.000Z');
    expect(after.source).toBe('first-source');
    expect(after.error_class).toBe('weekly');
  });
  it('does not persist non-limit errors and returns null', () => {
    expect(noteOllamaOutput(db, 'connection refused', 'src', ON, new Date())).toBeNull();
    expect(readOllamaLimit(db)).toBeNull();
  });
});

describe('clearOllamaLimit', () => {
  const ON = { OLLAMA_AUTO_FAILOVER: 'on' };
  it('returns false when nothing is limited', () => {
    expect(clearOllamaLimit(db, 'probe ok')).toBe(false);
  });
  it('removes the state row and returns true when limited', () => {
    noteOllamaOutput(db, 'reached your weekly usage limit', 's', ON, new Date());
    expect(readOllamaLimit(db)).not.toBeNull();
    expect(clearOllamaLimit(db, 'probe glm-5.3-flash succeeded', new Date('2026-10-02T00:00:00.000Z'))).toBe(true);
    expect(readOllamaLimit(db)).toBeNull();
  });
});

describe('probeModel', () => {
  it('defaults to the cheapest weighted model with a :cloud suffix', () => {
    // default weights: kimi-k3=4,glm-5.3=2,glm-5.3-flash=1 -> glm-5.3-flash
    expect(probeModel({})).toBe('glm-5.3-flash:cloud');
  });
  it('picks the lowest positive weight from MODEL_COST_WEIGHTS (ascending)', () => {
    expect(probeModel({ MODEL_COST_WEIGHTS: 'a-model=9,b-model=3' })).toBe('b-model:cloud');
  });
  it('ignores non-positive / invalid weights when choosing the cheapest', () => {
    // a=0 is excluded (w>0), so b=5 is the only valid and thus cheapest entry
    expect(probeModel({ MODEL_COST_WEIGHTS: 'a=0,b=5' })).toBe('b:cloud');
    expect(probeModel({ MODEL_COST_WEIGHTS: 'bad-entry,c-model=2' })).toBe('c-model:cloud');
  });
  it('does not double-suffix a name that already carries a tag', () => {
    expect(probeModel({ MODEL_COST_WEIGHTS: 'x:y=1,z=2' })).toBe('x:y');
  });
  it('lets OLLAMA_FAILOVER_PROBE_MODEL win verbatim (trimmed, no :cloud appended)', () => {
    expect(probeModel({ OLLAMA_FAILOVER_PROBE_MODEL: 'my-probe' })).toBe('my-probe');
    expect(probeModel({ OLLAMA_FAILOVER_PROBE_MODEL: '  tagged:v1  ', MODEL_COST_WEIGHTS: 'z=1' })).toBe('tagged:v1');
  });
});

describe('probeOllama', () => {
  const ON = { OLLAMA_AUTO_FAILOVER: 'on' };
  const OFF = { OLLAMA_AUTO_FAILOVER: 'off' };

  it('skips when auto-failover is off or nothing is limited', async () => {
    await expect(probeOllama(db, async () => 'ok', ON)).resolves.toBe('skipped');
    noteOllamaOutput(db, 'reached your weekly usage limit', 's', ON, new Date());
    // state exists but mode off -> still skipped
    await expect(probeOllama(db, async () => 'ok', OFF)).resolves.toBe('skipped');
  });
  it('clears the state on a successful probe call', async () => {
    noteOllamaOutput(db, 'reached your weekly usage limit', 's', ON, new Date('2026-10-01T00:00:00.000Z'));
    let seenModel: string | undefined;
    const res = await probeOllama(
      db,
      async (model) => { seenModel = model; return 'ok'; },
      ON,
      () => new Date('2026-10-02T00:00:00.000Z'),
    );
    expect(res).toBe('cleared');
    expect(seenModel).toBe('glm-5.3-flash:cloud');
    expect(readOllamaLimit(db)).toBeNull();
  });
  it('keeps the state and records last_probe_result on a failing probe call', async () => {
    noteOllamaOutput(db, 'reached your weekly usage limit', 's', ON, new Date('2026-10-01T00:00:00.000Z'));
    const res = await probeOllama(
      db,
      async () => { throw new Error('boom quota exceeded'); },
      ON,
      () => new Date('2026-10-02T00:00:00.000Z'),
    );
    expect(res).toBe('still_limited');
    const s = readOllamaLimit(db)!;
    expect(s.last_probe_at).toBe('2026-10-02T00:00:00.000Z');
    expect(s.last_probe_result).toContain('boom quota exceeded');
    // original detection preserved
    expect(s.detected_at).toBe('2026-10-01T00:00:00.000Z');
  });
});

describe('PROBE_INTERVAL_MS', () => {
  it('is thirty minutes in milliseconds', () => {
    expect(PROBE_INTERVAL_MS).toBe(30 * 60_000);
  });
});

describe('recordLimitCalibration', () => {
  const state: OllamaLimitState = {
    state: 'ollama_limited',
    detected_at: '2026-10-01T00:00:00.000Z',
    error_class: 'weekly',
    source: 'test-source',
    excerpt: 'reached your weekly usage limit',
  };
  it('does not throw when the judgments table is absent (fail-soft)', () => {
    // no tables created — ollamaUsage7d and the INSERT both fail silently
    expect(() => recordLimitCalibration(db, state)).not.toThrow();
  });
  it('inserts an ollama_limit_calibration judgment row when the table exists', () => {
    db.exec(`CREATE TABLE judgments (
      id TEXT PRIMARY KEY,
      judgment TEXT NOT NULL,
      subject_type TEXT,
      subject_id TEXT,
      state_hash TEXT,
      mode TEXT,
      decision TEXT,
      reason TEXT,
      answers_json TEXT,
      created_at TEXT
    )`);
    // create empty ledger/lease tables so ollamaUsage7d returns zeros instead of null
    db.exec(`CREATE TABLE llm_model_calls (created_at TEXT, provider TEXT, tokens_in INTEGER, tokens_out INTEGER)`);
    db.exec(`CREATE TABLE worker_leases (runtime TEXT, created_at TEXT, metadata TEXT)`);
    const now = new Date('2026-10-02T00:00:00.000Z');
    recordLimitCalibration(db, state, now);
    const rows = db.prepare("SELECT * FROM judgments WHERE judgment = 'ollama_limit_calibration'").all() as Record<string, unknown>[];
    expect(rows).toHaveLength(1);
    expect(rows[0].subject_type).toBe('inference_provider');
    expect(rows[0].subject_id).toBe('ollama');
    expect(rows[0].mode).toBe('annotation');
    expect(rows[0].decision).toBe('limit_hit');
    expect(rows[0].state_hash).toBe(`${state.error_class}:${state.detected_at}`);
    expect(rows[0].created_at).toBe(now.toISOString());
  });
});
